CREATE OR REPLACE FUNCTION public._guarded_add_presentation_decision_revision(p_decision_id uuid, p_reference_type text, p_snapshot jsonb, p_reason text, p_expected_status text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_user uuid;
  v_actor_name text;
  v_before public.fin_presentation_decisions%ROWTYPE;
  v_after public.fin_presentation_decisions%ROWTYPE;
  v_revision_id uuid;
  v_revision_number integer;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF NOT (SELECT public.has_any_permission(v_user, ARRAY[
    'financeiro:relatorio-socios:manage',
    'system:global:manage'
  ])) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:relatorio-socios:manage';
  END IF;
  IF p_expected_updated_at IS NULL THEN RAISE EXCEPTION 'OPTIMISTIC_LOCK_REQUIRED'; END IF;
  IF p_expected_status NOT IN ('DRAFT', 'APPROVED', 'IN_PROGRESS') THEN RAISE EXCEPTION 'STATUS_INVALID'; END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 4000 THEN
    RAISE EXCEPTION 'JUSTIFICATION_REQUIRED';
  END IF;

  SELECT * INTO v_before
  FROM public.fin_presentation_decisions decision
  WHERE decision.id = p_decision_id AND decision.company_id = v_company
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;
  IF v_before.status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'STATUS_INVALID: expected %, current %', p_expected_status, v_before.status;
  END IF;
  IF v_before.status IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'STATUS_INVALID: reopen decision first';
  END IF;

  SELECT count(*)::integer + 1 INTO v_revision_number
  FROM public.fin_presentation_decision_revisions revision
  WHERE revision.decision_id = p_decision_id AND revision.company_id = v_company;
  IF v_revision_number > 50 THEN RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: revisions'; END IF;

  PERFORM public._validate_fin_presentation_decision_snapshot(
    p_snapshot, v_before.period_start, v_before.period_end_exclusive,
    v_before.granularity, p_reference_type
  );

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_user AND public.is_company_member(profile.id, v_company);
  IF v_actor_name IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

  INSERT INTO public.fin_presentation_decision_revisions (
    company_id, decision_id, revision_number, reference_type, snapshot,
    revision_reason, created_by, created_by_name_snapshot
  ) VALUES (
    v_company, p_decision_id, v_revision_number, p_reference_type, p_snapshot,
    btrim(p_reason), v_user, v_actor_name
  )
  RETURNING id INTO v_revision_id;

  UPDATE public.fin_presentation_decisions
  SET reference_type = p_reference_type,
      current_revision_id = v_revision_id,
      status = 'DRAFT',
      approved_by = NULL,
      approved_by_name_snapshot = NULL,
      approved_at = NULL,
      completed_at = NULL,
      cancelled_at = NULL,
      latest_justification = btrim(p_reason),
      updated_by = v_user,
      updated_by_name_snapshot = v_actor_name,
      updated_at = clock_timestamp(),
      version = version + 1
  WHERE id = p_decision_id
  RETURNING * INTO v_after;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, antes, depois, justificativa, user_id, company_id
  ) VALUES (
    'presentation_decision', p_decision_id, 'REVISION_CREATED',
    jsonb_build_object(
      'actorName', v_actor_name,
      'status', v_before.status,
      'currentRevisionId', v_before.current_revision_id,
      'referenceType', v_before.reference_type,
      'version', v_before.version
    ),
    jsonb_build_object(
      'actorName', v_actor_name,
      'status', v_after.status,
      'currentRevisionId', v_revision_id,
      'revisionNumber', v_revision_number,
      'referenceType', p_reference_type,
      'version', v_after.version
    ),
    btrim(p_reason), v_user, v_company
  );

  RETURN jsonb_build_object(
    'id', p_decision_id,
    'currentRevisionId', v_revision_id,
    'revisionNumber', v_revision_number,
    'status', v_after.status,
    'version', v_after.version,
    'updatedAt', v_after.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_aprovar_conta_pagar(p_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_rows int;
  v_new_updated_at timestamptz;
BEGIN
  v_company_id := assert_tenant();
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- permission check
  IF NOT has_permission(v_user_id, 'financeiro:pagar:approve') THEN
    RAISE EXCEPTION 'Permission denied: financeiro:pagar:approve';
  END IF;

  UPDATE fin_contas_pagar
  SET status = 'APROVADO',
      aprovado_por = v_user_id,
      aprovado_em = now()
  WHERE id = p_id
    AND company_id = v_company_id
    AND updated_at = p_expected_updated_at
    AND status = 'AGUARDANDO_APROVACAO'
  RETURNING updated_at INTO v_new_updated_at;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'Conflito de concorrência ou status inválido. Recarregue a página.';
  END IF;

  -- audit (FIXED: removed ::text cast from p_id)
  INSERT INTO fin_audit_logs (entidade, entidade_id, acao, user_id, company_id)
  VALUES ('contas_pagar', p_id, 'aprovar', v_user_id, v_company_id);

  RETURN jsonb_build_object('id', p_id, 'updated_at', v_new_updated_at);
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_bulk_upsert_orcamento(p_mes_ano text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_item jsonb;
  v_categoria_id uuid;
  v_valor numeric;
  v_orcamento_id uuid;
  v_expected_updated_at timestamptz;
  v_saved_count int := 0;
  v_deleted_count int := 0;
BEGIN
  IF p_mes_ano IS NULL OR p_mes_ano !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION USING ERRCODE = '22007', MESSAGE = 'ORCAMENTO_MES_INVALIDO';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ORCAMENTO_PAYLOAD_INVALIDO';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_categoria_id := NULLIF(v_item->>'categoria_id', '')::uuid;
    v_valor := NULLIF(v_item->>'valor_orcado', '')::numeric;
    v_orcamento_id := NULLIF(v_item->>'orcamento_id', '')::uuid;
    v_expected_updated_at := NULLIF(v_item->>'expected_updated_at', '')::timestamptz;

    IF v_categoria_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ORCAMENTO_PAYLOAD_INVALIDO';
    END IF;

    IF v_valor IS NOT NULL AND v_valor > 0 THEN
      PERFORM public._guarded_upsert_orcamento(
        v_categoria_id, p_mes_ano, v_valor, v_expected_updated_at
      );
      v_saved_count := v_saved_count + 1;
    ELSIF v_orcamento_id IS NOT NULL THEN
      PERFORM public._guarded_delete_orcamento(v_orcamento_id, v_expected_updated_at);
      v_deleted_count := v_deleted_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('salvos', v_saved_count, 'excluidos', v_deleted_count);
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_create_conta_pagar(p_descricao text, p_valor numeric, p_fornecedor text DEFAULT NULL::text, p_supplier_id uuid DEFAULT NULL::uuid, p_data_vencimento date DEFAULT CURRENT_DATE, p_data_competencia date DEFAULT NULL::date, p_categoria_id uuid DEFAULT NULL::uuid, p_centro_custo_id uuid DEFAULT NULL::uuid, p_conta_id uuid DEFAULT NULL::uuid, p_forma_pagamento text DEFAULT 'boleto'::text, p_observacoes text DEFAULT NULL::text, p_rateios jsonb DEFAULT '[]'::jsonb, p_recorrencia jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_status text;
  v_threshold numeric;
  v_id uuid;
  v_child_id uuid;
  v_created_at timestamptz;
  v_desc text;
  v_forn text;
  v_obs text;
  v_rateios jsonb;
  v_recorrencia jsonb;
  v_frequency text;
  v_total integer := 1;
  v_index integer;
  v_due_date date;
  v_competence_date date;
  r record;
BEGIN
  v_company_id := public.assert_tenant();
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.has_permission(v_user_id, 'financeiro:pagar:create') THEN
    RAISE EXCEPTION 'Permission denied: financeiro:pagar:create';
  END IF;

  v_desc := public.strip_html(p_descricao);
  v_forn := public.strip_html(p_fornecedor);
  v_obs := public.strip_html(p_observacoes);

  IF length(btrim(v_desc)) = 0 THEN
    RAISE EXCEPTION 'Descrição é obrigatória';
  END IF;
  IF p_valor <= 0 THEN
    RAISE EXCEPTION 'Valor deve ser positivo';
  END IF;

  IF p_conta_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fin_contas
    WHERE id = p_conta_id AND company_id = v_company_id
  ) THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária não pertence à empresa';
  END IF;

  v_recorrencia := public.fin_validate_recorrencia_config(p_recorrencia);
  IF v_recorrencia IS NOT NULL THEN
    v_frequency := v_recorrencia->>'frequencia';
    v_total := (v_recorrencia->>'parcelas')::integer;
  END IF;

  v_threshold := public.fin_get_limite_aprovacao(v_company_id);
  v_status := CASE WHEN p_valor > v_threshold THEN 'AGUARDANDO_APROVACAO' ELSE 'APROVADO' END;

  INSERT INTO public.fin_contas_pagar (
    descricao, valor, fornecedor, supplier_id,
    data_vencimento, data_competencia,
    categoria_id, centro_custo_id, conta_id,
    forma_pagamento, observacoes, status,
    created_by, company_id, recorrente, recorrencia_config,
    parcela_atual, parcela_total
  ) VALUES (
    v_desc, p_valor, v_forn, p_supplier_id,
    p_data_vencimento, p_data_competencia,
    p_categoria_id, p_centro_custo_id, p_conta_id,
    p_forma_pagamento, v_obs, v_status,
    v_user_id, v_company_id, v_recorrencia IS NOT NULL, v_recorrencia,
    CASE WHEN v_recorrencia IS NOT NULL THEN 1 END,
    CASE WHEN v_recorrencia IS NOT NULL THEN v_total END
  )
  RETURNING id, created_at INTO v_id, v_created_at;

  v_rateios := CASE
    WHEN p_rateios IS NOT NULL AND jsonb_typeof(p_rateios) = 'array' THEN p_rateios
    ELSE '[]'::jsonb
  END;

  IF jsonb_array_length(v_rateios) > 0 THEN
    FOR r IN SELECT * FROM jsonb_to_recordset(v_rateios) AS x(
      categoria_id uuid, centro_custo_id uuid, valor numeric, percentual numeric
    ) LOOP
      INSERT INTO public.fin_lancamento_rateios (
        lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id
      ) VALUES (
        v_id, r.categoria_id, r.centro_custo_id, r.valor, r.percentual, v_company_id
      );
    END LOOP;
  END IF;

  IF v_recorrencia IS NOT NULL THEN
    FOR v_index IN 2..v_total LOOP
      v_due_date := CASE v_frequency
        WHEN 'mensal' THEN (p_data_vencimento + make_interval(months => v_index - 1))::date
        WHEN 'semanal' THEN p_data_vencimento + ((v_index - 1) * 7)
        WHEN 'quinzenal' THEN p_data_vencimento + ((v_index - 1) * 15)
      END;
      v_competence_date := CASE v_frequency
        WHEN 'mensal' THEN (p_data_competencia + make_interval(months => v_index - 1))::date
        WHEN 'semanal' THEN p_data_competencia + ((v_index - 1) * 7)
        WHEN 'quinzenal' THEN p_data_competencia + ((v_index - 1) * 15)
      END;

      INSERT INTO public.fin_contas_pagar (
        descricao, valor, fornecedor, supplier_id,
        data_vencimento, data_competencia,
        categoria_id, centro_custo_id, conta_id,
        forma_pagamento, observacoes, status,
        created_by, company_id, recorrente, recorrencia_config,
        parcela_atual, parcela_total, lancamento_pai_id
      ) VALUES (
        v_desc || ' (' || v_index || '/' || v_total || ')',
        p_valor, v_forn, p_supplier_id,
        v_due_date, v_competence_date,
        p_categoria_id, p_centro_custo_id, p_conta_id,
        p_forma_pagamento, v_obs, v_status,
        v_user_id, v_company_id, false, NULL,
        v_index, v_total, v_id
      ) RETURNING id INTO v_child_id;

      INSERT INTO public.fin_lancamento_rateios (
        lancamento_id, categoria_id, centro_custo_id, valor, percentual, observacao, company_id
      )
      SELECT v_child_id, categoria_id, centro_custo_id, valor, percentual, observacao, v_company_id
      FROM public.fin_lancamento_rateios
      WHERE lancamento_id = v_id AND company_id = v_company_id;
    END LOOP;
  END IF;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, depois, user_id, company_id)
  VALUES (
    'contas_pagar', v_id, 'criar',
    jsonb_build_object(
      'descricao', v_desc,
      'valor', p_valor,
      'status', v_status,
      'limite_aprovacao', v_threshold,
      'lancamentos_criados', v_total
    ),
    v_user_id, v_company_id
  );

  RETURN jsonb_build_object(
    'id', v_id,
    'status', v_status,
    'created_at', v_created_at,
    'limite_aprovacao', v_threshold,
    'lancamentos_criados', v_total
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_create_conta_receber(p_descricao text, p_cliente text DEFAULT NULL::text, p_valor numeric DEFAULT 0, p_data_vencimento date DEFAULT CURRENT_DATE, p_data_competencia date DEFAULT NULL::date, p_categoria_id uuid DEFAULT NULL::uuid, p_centro_custo_id uuid DEFAULT NULL::uuid, p_conta_id uuid DEFAULT NULL::uuid, p_forma_pagamento text DEFAULT 'pix'::text, p_observacoes text DEFAULT NULL::text, p_rateios jsonb DEFAULT '[]'::jsonb, p_recorrencia jsonb DEFAULT NULL::jsonb, p_supplier_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_id uuid;
  v_child_id uuid;
  v_created_at timestamptz;
  v_desc text;
  v_cliente text;
  v_obs text;
  v_rateios jsonb;
  v_recorrencia jsonb;
  v_frequency text;
  v_total integer := 1;
  v_index integer;
  v_due_date date;
  v_competence_date date;
  r record;
BEGIN
  v_company_id := public.assert_tenant();
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.has_permission(v_user_id, 'financeiro:receber:create') THEN
    RAISE EXCEPTION 'Permission denied: financeiro:receber:create';
  END IF;

  v_desc := public.strip_html(p_descricao);
  v_cliente := public.strip_html(p_cliente);
  v_obs := public.strip_html(p_observacoes);

  IF length(btrim(v_desc)) = 0 THEN
    RAISE EXCEPTION 'Descrição é obrigatória';
  END IF;
  IF p_valor <= 0 THEN
    RAISE EXCEPTION 'Valor deve ser positivo';
  END IF;

  IF p_conta_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fin_contas
    WHERE id = p_conta_id AND company_id = v_company_id
  ) THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária não pertence à empresa';
  END IF;

  v_recorrencia := public.fin_validate_recorrencia_config(p_recorrencia);
  IF v_recorrencia IS NOT NULL THEN
    v_frequency := v_recorrencia->>'frequencia';
    v_total := (v_recorrencia->>'parcelas')::integer;
  END IF;

  INSERT INTO public.fin_contas_receber (
    descricao, cliente, valor, data_vencimento, data_competencia,
    categoria_id, centro_custo_id, conta_id, supplier_id,
    forma_pagamento, observacoes, status,
    created_by, company_id, recorrente, recorrencia_config,
    parcela_atual, parcela_total
  ) VALUES (
    v_desc, v_cliente, p_valor, p_data_vencimento, p_data_competencia,
    p_categoria_id, p_centro_custo_id, p_conta_id, p_supplier_id,
    p_forma_pagamento, v_obs, 'A_RECEBER',
    v_user_id, v_company_id, v_recorrencia IS NOT NULL, v_recorrencia,
    CASE WHEN v_recorrencia IS NOT NULL THEN 1 END,
    CASE WHEN v_recorrencia IS NOT NULL THEN v_total END
  )
  RETURNING id, created_at INTO v_id, v_created_at;

  v_rateios := CASE
    WHEN p_rateios IS NOT NULL AND jsonb_typeof(p_rateios) = 'array' THEN p_rateios
    ELSE '[]'::jsonb
  END;

  IF jsonb_array_length(v_rateios) > 0 THEN
    FOR r IN SELECT * FROM jsonb_to_recordset(v_rateios) AS x(
      categoria_id uuid, centro_custo_id uuid, valor numeric, percentual numeric
    ) LOOP
      INSERT INTO public.fin_lancamento_rateios (
        lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id
      ) VALUES (
        v_id, r.categoria_id, r.centro_custo_id, r.valor, r.percentual, v_company_id
      );
    END LOOP;
  END IF;

  IF v_recorrencia IS NOT NULL THEN
    FOR v_index IN 2..v_total LOOP
      v_due_date := CASE v_frequency
        WHEN 'mensal' THEN (p_data_vencimento + make_interval(months => v_index - 1))::date
        WHEN 'semanal' THEN p_data_vencimento + ((v_index - 1) * 7)
        WHEN 'quinzenal' THEN p_data_vencimento + ((v_index - 1) * 15)
      END;
      v_competence_date := CASE v_frequency
        WHEN 'mensal' THEN (p_data_competencia + make_interval(months => v_index - 1))::date
        WHEN 'semanal' THEN p_data_competencia + ((v_index - 1) * 7)
        WHEN 'quinzenal' THEN p_data_competencia + ((v_index - 1) * 15)
      END;

      INSERT INTO public.fin_contas_receber (
        descricao, cliente, valor, data_vencimento, data_competencia,
        categoria_id, centro_custo_id, conta_id, supplier_id,
        forma_pagamento, observacoes, status,
        created_by, company_id, recorrente, recorrencia_config,
        parcela_atual, parcela_total, lancamento_pai_id
      ) VALUES (
        v_desc || ' (' || v_index || '/' || v_total || ')',
        v_cliente, p_valor, v_due_date, v_competence_date,
        p_categoria_id, p_centro_custo_id, p_conta_id, p_supplier_id,
        p_forma_pagamento, v_obs, 'A_RECEBER',
        v_user_id, v_company_id, false, NULL,
        v_index, v_total, v_id
      ) RETURNING id INTO v_child_id;

      INSERT INTO public.fin_lancamento_rateios (
        lancamento_id, categoria_id, centro_custo_id, valor, percentual, observacao, company_id
      )
      SELECT v_child_id, categoria_id, centro_custo_id, valor, percentual, observacao, v_company_id
      FROM public.fin_lancamento_rateios
      WHERE lancamento_id = v_id AND company_id = v_company_id;
    END LOOP;
  END IF;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, depois, user_id, company_id)
  VALUES (
    'contas_receber', v_id, 'criar',
    jsonb_build_object(
      'descricao', v_desc,
      'valor', p_valor,
      'cliente', v_cliente,
      'lancamentos_criados', v_total
    ),
    v_user_id, v_company_id
  );

  RETURN jsonb_build_object(
    'id', v_id,
    'created_at', v_created_at,
    'lancamentos_criados', v_total
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_create_presentation_decision_action(p_decision_id uuid, p_description text, p_responsible_user_id uuid, p_expected_decision_status text, p_expected_decision_updated_at timestamp with time zone, p_due_date date, p_priority text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_user uuid;
  v_actor_name text;
  v_responsible_name text;
  v_decision public.fin_presentation_decisions%ROWTYPE;
  v_action public.fin_presentation_decision_actions%ROWTYPE;
  v_count integer;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF NOT (SELECT public.has_any_permission(v_user, ARRAY[
    'financeiro:relatorio-socios:manage',
    'system:global:manage'
  ])) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:relatorio-socios:manage';
  END IF;
  IF p_description IS NULL OR length(btrim(p_description)) NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'VALIDATION: descricao obrigatoria ou excede 1000 caracteres';
  END IF;
  IF p_responsible_user_id IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_REQUIRED'; END IF;
  IF p_expected_decision_updated_at IS NULL THEN RAISE EXCEPTION 'OPTIMISTIC_LOCK_REQUIRED'; END IF;
  IF p_expected_decision_status NOT IN ('DRAFT', 'APPROVED', 'IN_PROGRESS') THEN RAISE EXCEPTION 'STATUS_INVALID'; END IF;
  IF p_priority IS NOT NULL AND p_priority NOT IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL') THEN
    RAISE EXCEPTION 'VALIDATION: prioridade invalida';
  END IF;

  SELECT * INTO v_decision
  FROM public.fin_presentation_decisions decision
  WHERE decision.id = p_decision_id AND decision.company_id = v_company
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_decision.updated_at IS DISTINCT FROM p_expected_decision_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;
  IF v_decision.status IS DISTINCT FROM p_expected_decision_status THEN
    RAISE EXCEPTION 'STATUS_INVALID: expected %, current %', p_expected_decision_status, v_decision.status;
  END IF;
  IF v_decision.status IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'STATUS_INVALID: reopen decision first';
  END IF;

  SELECT count(*)::integer INTO v_count
  FROM public.fin_presentation_decision_actions action
  WHERE action.decision_id = p_decision_id AND action.company_id = v_company;
  IF v_count >= 100 THEN RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: actions'; END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_user AND public.is_company_member(profile.id, v_company);
  IF v_actor_name IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_responsible_name
  FROM public.profiles profile
  WHERE profile.id = p_responsible_user_id
    AND public.is_company_member(profile.id, v_company)
    AND profile.nome NOT ILIKE '[EXCLUIDO]%'
    AND profile.nome NOT ILIKE '[EXCLUÍDO]%';
  IF v_responsible_name IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_OUT_OF_TENANT'; END IF;

  INSERT INTO public.fin_presentation_decision_actions (
    company_id, decision_id, description, responsible_user_id,
    responsible_name_snapshot, due_date, priority, status,
    created_by, created_by_name_snapshot, updated_by, updated_by_name_snapshot
  ) VALUES (
    v_company, p_decision_id, btrim(p_description), p_responsible_user_id,
    v_responsible_name, p_due_date, p_priority, 'PENDING',
    v_user, v_actor_name, v_user, v_actor_name
  ) RETURNING * INTO v_action;

  UPDATE public.fin_presentation_decisions
  SET updated_by = v_user,
      updated_by_name_snapshot = v_actor_name,
      updated_at = clock_timestamp(),
      version = version + 1
  WHERE id = p_decision_id;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, antes, depois, justificativa, user_id, company_id
  ) VALUES (
    'presentation_decision', p_decision_id, 'ACTION_CREATED', NULL,
    jsonb_build_object(
      'actorName', v_actor_name,
      'actionId', v_action.id,
      'description', v_action.description,
      'responsibleUserId', v_action.responsible_user_id,
      'responsibleName', v_action.responsible_name_snapshot,
      'dueDate', v_action.due_date,
      'priority', v_action.priority,
      'status', v_action.status,
      'version', v_action.version
    ),
    '', v_user, v_company
  );

  INSERT INTO public.notifications (
    recipient_user_id, type, module, title, message, entity_type,
    entity_id, link_path, created_by, metadata
  ) VALUES (
    p_responsible_user_id, 'PRESENTATION_ACTION_ASSIGNED', 'financeiro',
    'Nova acao da Apresentacao Socios',
    btrim(p_description), 'presentation_decision', p_decision_id,
    '/financeiro/relatorio-socios?decision=' || p_decision_id::text,
    v_user, jsonb_build_object('actionId', v_action.id)
  );

  RETURN jsonb_build_object(
    'id', v_action.id,
    'decisionId', v_action.decision_id,
    'status', v_action.status,
    'version', v_action.version,
    'updatedAt', v_action.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_create_presentation_decision(p_title text, p_context text, p_period_start date, p_period_end_exclusive date, p_granularity text, p_reference_type text, p_snapshot jsonb, p_executive_responsible_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_user uuid;
  v_actor_name text;
  v_responsible_name text;
  v_decision_id uuid;
  v_revision_id uuid;
  v_updated_at timestamptz;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF NOT (SELECT public.has_any_permission(v_user, ARRAY[
    'financeiro:relatorio-socios:manage',
    'system:global:manage'
  ])) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:relatorio-socios:manage';
  END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'VALIDATION: titulo obrigatorio ou excede 200 caracteres';
  END IF;
  IF p_context IS NULL OR length(btrim(p_context)) NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'VALIDATION: contexto obrigatorio ou excede 10000 caracteres';
  END IF;
  IF p_period_end_exclusive <= p_period_start THEN
    RAISE EXCEPTION 'VALIDATION: periodo invalido';
  END IF;
  IF p_granularity NOT IN ('day', 'month', 'year') OR p_reference_type NOT IN ('BASE', 'SCENARIO') THEN
    RAISE EXCEPTION 'VALIDATION: referencia ou granularidade invalida';
  END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_user AND public.is_company_member(profile.id, v_company);
  IF v_actor_name IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

  IF p_executive_responsible_user_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
      INTO v_responsible_name
    FROM public.profiles profile
    WHERE profile.id = p_executive_responsible_user_id
      AND public.is_company_member(profile.id, v_company)
      AND profile.nome NOT ILIKE '[EXCLUIDO]%'
      AND profile.nome NOT ILIKE '[EXCLUÍDO]%';
    IF v_responsible_name IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_OUT_OF_TENANT'; END IF;
  END IF;

  PERFORM public._validate_fin_presentation_decision_snapshot(
    p_snapshot, p_period_start, p_period_end_exclusive, p_granularity, p_reference_type
  );

  INSERT INTO public.fin_presentation_decisions (
    company_id, title, context, period_start, period_end_exclusive, granularity,
    reference_type, status, executive_responsible_user_id,
    executive_responsible_name_snapshot, created_by, created_by_name_snapshot,
    updated_by, updated_by_name_snapshot
  ) VALUES (
    v_company, btrim(p_title), btrim(p_context), p_period_start, p_period_end_exclusive,
    p_granularity, p_reference_type, 'DRAFT', p_executive_responsible_user_id,
    v_responsible_name, v_user, v_actor_name, v_user, v_actor_name
  )
  RETURNING id INTO v_decision_id;

  INSERT INTO public.fin_presentation_decision_revisions (
    company_id, decision_id, revision_number, reference_type, snapshot,
    revision_reason, created_by, created_by_name_snapshot
  ) VALUES (
    v_company, v_decision_id, 1, p_reference_type, p_snapshot,
    'Registro inicial', v_user, v_actor_name
  )
  RETURNING id INTO v_revision_id;

  UPDATE public.fin_presentation_decisions
  SET current_revision_id = v_revision_id,
      updated_at = clock_timestamp()
  WHERE id = v_decision_id
  RETURNING updated_at INTO v_updated_at;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, antes, depois, justificativa, user_id, company_id
  ) VALUES (
    'presentation_decision', v_decision_id, 'DECISION_CREATED', NULL,
    jsonb_build_object(
      'actorName', v_actor_name,
      'title', btrim(p_title),
      'status', 'DRAFT',
      'referenceType', p_reference_type,
      'revisionNumber', 1
    ),
    '', v_user, v_company
  );

  RETURN jsonb_build_object(
    'id', v_decision_id,
    'currentRevisionId', v_revision_id,
    'status', 'DRAFT',
    'version', 1,
    'updatedAt', v_updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_create_presentation_session(p_title text, p_context text, p_period_start date, p_period_end_exclusive date, p_granularity text, p_meeting_date date, p_minutes_responsible_user_id uuid, p_participant_user_ids uuid[], p_previous_session_id uuid, p_agenda_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_user uuid;
  v_actor_name text;
  v_responsible_name text;
  v_responsible_email text;
  v_session public.fin_presentation_sessions%ROWTYPE;
  v_content jsonb;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF NOT (SELECT public.has_any_permission(v_user, ARRAY['financeiro:relatorio-socios:manage', 'system:global:manage'])) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:relatorio-socios:manage';
  END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'VALIDATION: titulo obrigatorio'; END IF;
  IF length(COALESCE(p_context, '')) > 10000 THEN RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: context'; END IF;
  IF p_period_start IS NULL OR p_period_end_exclusive IS NULL OR p_period_end_exclusive <= p_period_start THEN
    RAISE EXCEPTION 'VALIDATION: periodo invalido';
  END IF;
  IF p_granularity NOT IN ('day', 'month', 'year') THEN RAISE EXCEPTION 'VALIDATION: granularidade invalida'; END IF;
  IF p_meeting_date IS NULL THEN RAISE EXCEPTION 'VALIDATION: data da reuniao obrigatoria'; END IF;
  IF p_minutes_responsible_user_id IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_REQUIRED'; END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario') INTO v_actor_name
  FROM public.profiles profile WHERE profile.id = v_user AND public.is_company_member(profile.id, v_company);
  IF v_actor_name IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;
  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario'), NULLIF(profile.email, '')
    INTO v_responsible_name, v_responsible_email
  FROM public.profiles profile
  WHERE profile.id = p_minutes_responsible_user_id
    AND public.is_company_member(profile.id, v_company)
    AND profile.nome NOT ILIKE '[EXCLUIDO]%'
    AND profile.nome NOT ILIKE '[EXCLUÍDO]%';
  IF v_responsible_name IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_OUT_OF_TENANT'; END IF;
  IF p_previous_session_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fin_presentation_sessions previous
    WHERE previous.id = p_previous_session_id AND previous.company_id = v_company
  ) THEN RAISE EXCEPTION 'PREVIOUS_SESSION_OUT_OF_TENANT'; END IF;

  INSERT INTO public.fin_presentation_sessions (
    company_id, title, context, period_start, period_end_exclusive, granularity,
    meeting_date, minutes_responsible_user_id, minutes_responsible_name_snapshot,
    minutes_responsible_email_snapshot, previous_session_id, status,
    created_by, created_by_name_snapshot, updated_by, updated_by_name_snapshot
  ) VALUES (
    v_company, btrim(p_title), COALESCE(p_context, ''), p_period_start, p_period_end_exclusive, p_granularity,
    p_meeting_date, p_minutes_responsible_user_id, v_responsible_name,
    v_responsible_email, p_previous_session_id, 'DRAFT',
    v_user, v_actor_name, v_user, v_actor_name
  ) RETURNING * INTO v_session;

  v_content := public._replace_fin_presentation_session_content(
    v_session.id, v_company, v_user, v_actor_name, p_participant_user_ids, p_agenda_items
  );

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, antes, depois, justificativa, user_id, company_id)
  VALUES (
    'presentation_session', v_session.id, 'SESSION_CREATED', NULL,
    jsonb_build_object(
      'actorName', v_actor_name,
      'status', 'DRAFT',
      'title', v_session.title,
      'meetingDate', v_session.meeting_date,
      'minutesResponsibleUserId', v_session.minutes_responsible_user_id,
      'minutesResponsibleName', v_session.minutes_responsible_name_snapshot,
      'periodStart', v_session.period_start,
      'periodEndExclusive', v_session.period_end_exclusive,
      'granularity', v_session.granularity,
      'content', v_content,
      'version', v_session.version
    ), '', v_user, v_company
  );

  BEGIN
    INSERT INTO public.notifications (
      recipient_user_id, type, module, title, message, entity_type,
      entity_id, link_path, created_by, metadata
    ) VALUES (
      p_minutes_responsible_user_id, 'PRESENTATION_MINUTES_ASSIGNED', 'financeiro',
      'Responsabilidade por ata executiva', v_session.title,
      'presentation_session', v_session.id,
      '/financeiro/relatorio-socios?session=' || v_session.id::text,
      v_user, jsonb_build_object('sessionId', v_session.id)
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('id', v_session.id, 'status', v_session.status, 'updatedAt', v_session.updated_at, 'version', v_session.version);
END;
$function$

