CREATE OR REPLACE FUNCTION public._guarded_update_presentation_decision_action(p_action_id uuid, p_description text, p_responsible_user_id uuid, p_due_date date, p_priority text, p_expected_status text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_user uuid;
  v_actor_name text;
  v_responsible_name text;
  v_decision public.fin_presentation_decisions%ROWTYPE;
  v_before public.fin_presentation_decision_actions%ROWTYPE;
  v_after public.fin_presentation_decision_actions%ROWTYPE;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF NOT (SELECT public.has_any_permission(v_user, ARRAY[
    'financeiro:relatorio-socios:manage',
    'system:global:manage'
  ])) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:relatorio-socios:manage';
  END IF;
  IF p_expected_updated_at IS NULL THEN RAISE EXCEPTION 'OPTIMISTIC_LOCK_REQUIRED'; END IF;
  IF p_expected_status NOT IN ('PENDING', 'IN_PROGRESS') THEN RAISE EXCEPTION 'STATUS_INVALID'; END IF;
  IF p_description IS NULL OR length(btrim(p_description)) NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'VALIDATION: descricao obrigatoria ou excede 1000 caracteres';
  END IF;
  IF p_responsible_user_id IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_REQUIRED'; END IF;
  IF p_priority IS NOT NULL AND p_priority NOT IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL') THEN
    RAISE EXCEPTION 'VALIDATION: prioridade invalida';
  END IF;

  SELECT * INTO v_before
  FROM public.fin_presentation_decision_actions action
  WHERE action.id = p_action_id AND action.company_id = v_company
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;
  IF v_before.status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'STATUS_INVALID: expected %, current %', p_expected_status, v_before.status;
  END IF;
  IF v_before.status IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'ACTION_REOPEN_REQUIRED';
  END IF;

  SELECT * INTO v_decision
  FROM public.fin_presentation_decisions decision
  WHERE decision.id = v_before.decision_id AND decision.company_id = v_company
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_decision.status IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'STATUS_INVALID: reopen decision first';
  END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_user AND public.is_company_member(profile.id, v_company);
  IF v_actor_name IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_responsible_name
  FROM public.profiles profile
  WHERE profile.id = p_responsible_user_id
    AND public.is_company_member(profile.id, v_company)
    AND profile.nome NOT ILIKE '[EXCLUIDO]%'
    AND profile.nome NOT ILIKE '[EXCLUÍDO]%';
  IF v_responsible_name IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_OUT_OF_TENANT'; END IF;

  UPDATE public.fin_presentation_decision_actions
  SET description = btrim(p_description),
      responsible_user_id = p_responsible_user_id,
      responsible_name_snapshot = v_responsible_name,
      due_date = p_due_date,
      priority = p_priority,
      updated_by = v_user,
      updated_by_name_snapshot = v_actor_name,
      updated_at = clock_timestamp(),
      version = version + 1
  WHERE id = p_action_id
  RETURNING * INTO v_after;

  UPDATE public.fin_presentation_decisions
  SET updated_by = v_user,
      updated_by_name_snapshot = v_actor_name,
      updated_at = clock_timestamp(),
      version = version + 1
  WHERE id = v_before.decision_id;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, antes, depois, justificativa, user_id, company_id
  ) VALUES (
    'presentation_decision', v_before.decision_id, 'ACTION_UPDATED',
    jsonb_build_object(
      'actorName', v_actor_name,
      'actionId', v_before.id,
      'description', v_before.description,
      'responsibleUserId', v_before.responsible_user_id,
      'responsibleName', v_before.responsible_name_snapshot,
      'dueDate', v_before.due_date,
      'priority', v_before.priority,
      'version', v_before.version
    ),
    jsonb_build_object(
      'actorName', v_actor_name,
      'actionId', v_after.id,
      'description', v_after.description,
      'responsibleUserId', v_after.responsible_user_id,
      'responsibleName', v_after.responsible_name_snapshot,
      'dueDate', v_after.due_date,
      'priority', v_after.priority,
      'version', v_after.version
    ),
    '', v_user, v_company
  );

  IF v_before.responsible_user_id IS DISTINCT FROM p_responsible_user_id THEN
    INSERT INTO public.notifications (
      recipient_user_id, type, module, title, message, entity_type,
      entity_id, link_path, created_by, metadata
    ) VALUES (
      p_responsible_user_id, 'PRESENTATION_ACTION_ASSIGNED', 'financeiro',
      'Acao atribuida na Apresentacao Socios',
      v_after.description, 'presentation_decision', v_before.decision_id,
      '/financeiro/relatorio-socios?decision=' || v_before.decision_id::text,
      v_user, jsonb_build_object('actionId', v_after.id)
    );
  END IF;

  RETURN jsonb_build_object(
    'id', v_after.id,
    'decisionId', v_after.decision_id,
    'status', v_after.status,
    'version', v_after.version,
    'updatedAt', v_after.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_update_presentation_decision_draft(p_decision_id uuid, p_title text, p_context text, p_executive_responsible_user_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_user uuid;
  v_actor_name text;
  v_responsible_name text;
  v_before public.fin_presentation_decisions%ROWTYPE;
  v_after public.fin_presentation_decisions%ROWTYPE;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF NOT (SELECT public.has_any_permission(v_user, ARRAY[
    'financeiro:relatorio-socios:manage',
    'system:global:manage'
  ])) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:relatorio-socios:manage';
  END IF;
  IF p_expected_updated_at IS NULL THEN RAISE EXCEPTION 'OPTIMISTIC_LOCK_REQUIRED'; END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 200
     OR p_context IS NULL OR length(btrim(p_context)) NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'VALIDATION: campos invalidos';
  END IF;

  SELECT * INTO v_before
  FROM public.fin_presentation_decisions decision
  WHERE decision.id = p_decision_id AND decision.company_id = v_company
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_before.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;
  IF v_before.status <> 'DRAFT' THEN RAISE EXCEPTION 'STATUS_INVALID: DRAFT required'; END IF;

  SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
    INTO v_actor_name
  FROM public.profiles profile
  WHERE profile.id = v_user AND public.is_company_member(profile.id, v_company);
  IF v_actor_name IS NULL THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;

  IF p_executive_responsible_user_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(btrim(profile.nome), ''), NULLIF(profile.email, ''), 'Usuario')
      INTO v_responsible_name
    FROM public.profiles profile
    WHERE profile.id = p_executive_responsible_user_id
      AND public.is_company_member(profile.id, v_company)
      AND profile.nome NOT ILIKE '[EXCLUIDO]%'
      AND profile.nome NOT ILIKE '[EXCLUÍDO]%';
    IF v_responsible_name IS NULL THEN RAISE EXCEPTION 'RESPONSIBLE_OUT_OF_TENANT'; END IF;
  END IF;

  UPDATE public.fin_presentation_decisions
  SET title = btrim(p_title),
      context = btrim(p_context),
      executive_responsible_user_id = p_executive_responsible_user_id,
      executive_responsible_name_snapshot = v_responsible_name,
      updated_by = v_user,
      updated_by_name_snapshot = v_actor_name,
      updated_at = clock_timestamp(),
      version = version + 1
  WHERE id = p_decision_id
  RETURNING * INTO v_after;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, antes, depois, justificativa, user_id, company_id
  ) VALUES (
    'presentation_decision', p_decision_id, 'DRAFT_UPDATED',
    jsonb_build_object(
      'actorName', v_actor_name,
      'title', v_before.title,
      'context', v_before.context,
      'executiveResponsibleUserId', v_before.executive_responsible_user_id,
      'executiveResponsibleName', v_before.executive_responsible_name_snapshot,
      'version', v_before.version
    ),
    jsonb_build_object(
      'actorName', v_actor_name,
      'title', v_after.title,
      'context', v_after.context,
      'executiveResponsibleUserId', v_after.executive_responsible_user_id,
      'executiveResponsibleName', v_after.executive_responsible_name_snapshot,
      'version', v_after.version
    ),
    '', v_user, v_company
  );

  RETURN jsonb_build_object('id', v_after.id, 'status', v_after.status, 'version', v_after.version, 'updatedAt', v_after.updated_at);
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_update_reconciled_classification(p_id uuid, p_categoria_id uuid DEFAULT NULL::uuid, p_centro_custo_id uuid DEFAULT NULL::uuid, p_observacoes text DEFAULT NULL::text, p_rateios jsonb DEFAULT '[]'::jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_justificativa_edicao text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_lanc public.fin_lancamentos%ROWTYPE;
  v_rateios jsonb;
  v_rateio_count integer;
  v_rateio_sum numeric;
  v_invalid_count integer;
  v_header_categoria_id uuid;
  v_header_centro_custo_id uuid;
  v_updated_at timestamptz;
  v_antes jsonb;
  v_depois jsonb;
BEGIN
  v_company_id := public.assert_tenant();
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario nao autenticado';
  END IF;

  IF NOT public.has_any_permission(v_user_id, ARRAY[
    'financeiro:lancamentos:edit',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:lancamentos:edit necessario';
  END IF;

  SELECT l.*
  INTO v_lanc
  FROM public.fin_lancamentos l
  WHERE l.id = p_id
    AND l.company_id = v_company_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: Lancamento nao encontrado';
  END IF;

  IF v_lanc.conciliado IS NOT TRUE THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: lancamento nao esta conciliado';
  END IF;

  IF v_lanc.tipo = 'TRANSFERENCIA' THEN
    RAISE EXCEPTION 'TIPO_INVALIDO: transferencia nao possui classificacao contabil';
  END IF;

  IF v_lanc.origem IN ('espelho_cp', 'espelho_cr') THEN
    RAISE EXCEPTION 'ORIGEM_INVALIDA: edite a conta a pagar/receber de origem';
  END IF;

  IF p_expected_updated_at IS NOT NULL
     AND v_lanc.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;

  IF NULLIF(btrim(p_justificativa_edicao), '') IS NULL THEN
    RAISE EXCEPTION 'JUSTIFICATIVA_OBRIGATORIA';
  END IF;

  IF p_rateios IS NULL OR jsonb_typeof(p_rateios) <> 'array' THEN
    RAISE EXCEPTION 'RATEIO_INVALIDO: rateios deve ser um array';
  END IF;

  v_rateios := p_rateios;
  v_rateio_count := jsonb_array_length(v_rateios);

  IF v_rateio_count = 0 THEN
    IF p_categoria_id IS NULL THEN
      RAISE EXCEPTION 'CATEGORIA_OBRIGATORIA';
    END IF;

    PERFORM 1
    FROM public.fin_categorias c
    WHERE c.id = p_categoria_id
      AND c.company_id = v_company_id
      AND c.ativo = true
      AND c.tipo = lower(v_lanc.tipo);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'CATEGORIA_INVALIDA: categoria inativa, de outro tipo ou empresa';
    END IF;

    IF p_centro_custo_id IS NOT NULL THEN
      PERFORM 1
      FROM public.fin_centros_custo cc
      WHERE cc.id = p_centro_custo_id
        AND cc.company_id = v_company_id
        AND cc.ativo = true;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'CENTRO_CUSTO_INVALIDO';
      END IF;
    END IF;

    v_header_categoria_id := p_categoria_id;
    v_header_centro_custo_id := p_centro_custo_id;
  ELSE
    SELECT
      count(*) FILTER (
        WHERE r.categoria_id IS NULL
           OR r.valor IS NULL
           OR r.valor <= 0
           OR c.id IS NULL
           OR (r.centro_custo_id IS NOT NULL AND cc.id IS NULL)
      ),
      COALESCE(sum(r.valor), 0)
    INTO v_invalid_count, v_rateio_sum
    FROM jsonb_to_recordset(v_rateios) AS r(
      categoria_id uuid,
      centro_custo_id uuid,
      valor numeric,
      percentual numeric,
      observacao text
    )
    LEFT JOIN public.fin_categorias c
      ON c.id = r.categoria_id
     AND c.company_id = v_company_id
     AND c.ativo = true
     AND c.tipo = lower(v_lanc.tipo)
    LEFT JOIN public.fin_centros_custo cc
      ON cc.id = r.centro_custo_id
     AND cc.company_id = v_company_id
     AND cc.ativo = true;

    IF v_invalid_count > 0 THEN
      RAISE EXCEPTION 'RATEIO_INVALIDO: categoria, centro de custo ou valor invalido';
    END IF;

    IF abs(v_rateio_sum - v_lanc.valor) >= 0.01 THEN
      RAISE EXCEPTION 'RATEIO_INCOMPLETO: total (%) difere do lancamento (%)',
        v_rateio_sum, v_lanc.valor;
    END IF;

    IF v_rateio_count = 1 THEN
      SELECT r.categoria_id, r.centro_custo_id
      INTO v_header_categoria_id, v_header_centro_custo_id
      FROM jsonb_to_record(v_rateios->0) AS r(
        categoria_id uuid,
        centro_custo_id uuid
      );
    ELSE
      v_header_categoria_id := NULL;
      v_header_centro_custo_id := NULL;
    END IF;
  END IF;

  v_antes := jsonb_build_object(
    'categoria_id', v_lanc.categoria_id,
    'centro_custo_id', v_lanc.centro_custo_id,
    'observacoes', v_lanc.observacoes,
    'rateios', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'categoria_id', r.categoria_id,
        'centro_custo_id', r.centro_custo_id,
        'valor', r.valor,
        'percentual', r.percentual,
        'observacao', r.observacao
      ) ORDER BY r.created_at, r.id)
      FROM public.fin_lancamento_rateios r
      WHERE r.lancamento_id = p_id
        AND r.company_id = v_company_id
    ), '[]'::jsonb)
  );

  UPDATE public.fin_lancamentos l
  SET categoria_id = v_header_categoria_id,
      centro_custo_id = v_header_centro_custo_id,
      observacoes = public.strip_html(p_observacoes),
      justificativa_edicao = btrim(p_justificativa_edicao),
      updated_at = now()
  WHERE l.id = p_id
    AND l.company_id = v_company_id
  RETURNING l.updated_at INTO v_updated_at;

  DELETE FROM public.fin_lancamento_rateios r
  WHERE r.lancamento_id = p_id
    AND r.company_id = v_company_id;

  IF v_rateio_count > 0 THEN
    INSERT INTO public.fin_lancamento_rateios (
      lancamento_id,
      categoria_id,
      centro_custo_id,
      valor,
      percentual,
      observacao,
      company_id
    )
    SELECT
      p_id,
      r.categoria_id,
      r.centro_custo_id,
      r.valor,
      round((r.valor / v_lanc.valor) * 100, 4),
      public.strip_html(r.observacao),
      v_company_id
    FROM jsonb_to_recordset(v_rateios) AS r(
      categoria_id uuid,
      centro_custo_id uuid,
      valor numeric,
      percentual numeric,
      observacao text
    );
  END IF;

  v_depois := jsonb_build_object(
    'categoria_id', v_header_categoria_id,
    'centro_custo_id', v_header_centro_custo_id,
    'observacoes', public.strip_html(p_observacoes),
    'rateios', v_rateios,
    'conciliado_preservado', true,
    'justificativa', btrim(p_justificativa_edicao)
  );

  INSERT INTO public.fin_audit_logs (
    entidade,
    entidade_id,
    acao,
    user_id,
    company_id,
    antes,
    depois
  ) VALUES (
    'lancamentos',
    p_id,
    'editar_classificacao_conciliado',
    v_user_id,
    v_company_id,
    v_antes,
    v_depois
  );

  RETURN QUERY SELECT p_id, v_updated_at;
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_upsert_lancamento(p_id uuid DEFAULT NULL::uuid, p_tipo text DEFAULT 'DESPESA'::text, p_status text DEFAULT 'PREVISTO'::text, p_valor numeric DEFAULT 0, p_conta_id uuid DEFAULT NULL::uuid, p_categoria_id uuid DEFAULT NULL::uuid, p_centro_custo_id uuid DEFAULT NULL::uuid, p_data_competencia date DEFAULT CURRENT_DATE, p_data_vencimento date DEFAULT NULL::date, p_data_pagamento date DEFAULT NULL::date, p_descricao text DEFAULT ''::text, p_observacoes text DEFAULT NULL::text, p_forma_pagamento text DEFAULT 'pix'::text, p_origem text DEFAULT 'manual'::text, p_recorrente boolean DEFAULT false, p_recorrencia_config jsonb DEFAULT NULL::jsonb, p_rateios jsonb DEFAULT '[]'::jsonb, p_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_justificativa_edicao text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _company_id uuid;
  _user_id uuid;
  _v_id uuid;
  _v_updated_at timestamptz;
  _existing record;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  _company_id := public.assert_tenant();

  -- Permission check
  IF p_id IS NULL THEN
    IF NOT public.has_permission(_user_id, 'financeiro:lancamentos:create') THEN
      RAISE EXCEPTION 'Permission denied: financeiro:lancamentos:create';
    END IF;
  ELSE
    IF NOT public.has_permission(_user_id, 'financeiro:lancamentos:edit') THEN
      RAISE EXCEPTION 'Permission denied: financeiro:lancamentos:edit';
    END IF;

    -- Fetch existing for optimistic locking
    SELECT fl.* INTO _existing
    FROM public.fin_lancamentos fl
    WHERE fl.id = p_id AND fl.company_id = _company_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Lancamento not found';
    END IF;

    -- Block editing conciliados
    IF _existing.conciliado = true THEN
      RAISE EXCEPTION 'Lançamento conciliado não pode ser editado. Desconcilie primeiro.';
    END IF;

    -- Optimistic locking
    IF p_updated_at IS NOT NULL AND _existing.updated_at != p_updated_at THEN
      RAISE EXCEPTION 'CONFLICT: Registro alterado por outro usuário';
    END IF;
  END IF;

  IF p_id IS NULL THEN
    -- INSERT
    INSERT INTO public.fin_lancamentos (
      tipo, status, valor, conta_id, categoria_id, centro_custo_id,
      data_competencia, data_vencimento, data_pagamento,
      descricao, observacoes, forma_pagamento, origem,
      recorrente, recorrencia_config,
      created_by, company_id
    ) VALUES (
      p_tipo, p_status, p_valor, p_conta_id, p_categoria_id, p_centro_custo_id,
      p_data_competencia, p_data_vencimento, p_data_pagamento,
      p_descricao, p_observacoes, p_forma_pagamento, p_origem,
      p_recorrente, p_recorrencia_config,
      _user_id, _company_id
    )
    RETURNING fin_lancamentos.id, fin_lancamentos.updated_at
    INTO _v_id, _v_updated_at;
  ELSE
    -- UPDATE
    UPDATE public.fin_lancamentos SET
      tipo = p_tipo,
      status = p_status,
      valor = p_valor,
      conta_id = p_conta_id,
      categoria_id = p_categoria_id,
      centro_custo_id = p_centro_custo_id,
      data_competencia = p_data_competencia,
      data_vencimento = p_data_vencimento,
      data_pagamento = p_data_pagamento,
      descricao = p_descricao,
      observacoes = p_observacoes,
      forma_pagamento = p_forma_pagamento,
      recorrente = p_recorrente,
      recorrencia_config = p_recorrencia_config,
      justificativa_edicao = p_justificativa_edicao,
      updated_at = now()
    WHERE fin_lancamentos.id = p_id AND company_id = _company_id
    RETURNING fin_lancamentos.id, fin_lancamentos.updated_at
    INTO _v_id, _v_updated_at;
  END IF;

  -- Handle rateios atomically
  IF _v_id IS NOT NULL THEN
    DELETE FROM public.fin_lancamento_rateios WHERE lancamento_id = _v_id;

    IF p_rateios IS NOT NULL AND jsonb_array_length(p_rateios) > 0 THEN
      INSERT INTO public.fin_lancamento_rateios (
        lancamento_id, categoria_id, centro_custo_id, valor, percentual, observacao, company_id
      )
      SELECT
        _v_id,
        (r->>'categoria_id')::uuid,
        NULLIF(r->>'centro_custo_id', '')::uuid,
        (r->>'valor')::numeric,
        (r->>'percentual')::numeric,
        NULLIF(r->>'observacao', ''),
        _company_id
      FROM jsonb_array_elements(p_rateios) AS r;
    END IF;
  END IF;

  RETURN QUERY SELECT _v_id, _v_updated_at;
END;
$function$

CREATE OR REPLACE FUNCTION public._guarded_upsert_orcamento(p_categoria_id uuid, p_mes_ano text, p_valor numeric, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_existing public.fin_orcamentos%ROWTYPE;
  v_saved public.fin_orcamentos%ROWTYPE;
BEGIN
  v_company_id := public.assert_tenant();

  IF NOT (SELECT public.has_permission(auth.uid(), 'financeiro:orcamento:edit')) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'PERMISSION_DENIED: financeiro:orcamento:edit';
  END IF;

  IF p_categoria_id IS NULL
     OR p_mes_ano IS NULL
     OR p_mes_ano !~ '^[0-9]{4}-(0[1-9]|1[0-2])$'
     OR p_valor IS NULL
     OR p_valor <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ORCAMENTO_PAYLOAD_INVALIDO';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.fin_categorias category
    WHERE category.id = p_categoria_id
      AND category.company_id = v_company_id
      AND category.excluir_dos_totais IS NOT TRUE
      AND pg_catalog.lower(category.tipo) IN ('receita', 'despesa')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ORCAMENTO_CATEGORIA_FORA_DO_TENANT';
  END IF;

  SELECT budget.*
  INTO v_existing
  FROM public.fin_orcamentos budget
  WHERE budget.company_id = v_company_id
    AND budget.mes_ano = p_mes_ano
    AND budget.categoria_id = p_categoria_id
  FOR UPDATE;

  IF FOUND THEN
    IF p_expected_updated_at IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'OPTIMISTIC_LOCK_REQUIRED';
    END IF;
    IF v_existing.updated_at <> p_expected_updated_at THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'OPTIMISTIC_LOCK_CONFLICT';
    END IF;

    UPDATE public.fin_orcamentos
    SET valor_orcado = p_valor,
        updated_at = pg_catalog.clock_timestamp()
    WHERE id = v_existing.id
      AND company_id = v_company_id
      AND updated_at = p_expected_updated_at
    RETURNING * INTO v_saved;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'OPTIMISTIC_LOCK_CONFLICT';
    END IF;
  ELSE
    IF p_expected_updated_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'OPTIMISTIC_LOCK_CONFLICT';
    END IF;

    INSERT INTO public.fin_orcamentos (
      company_id,
      categoria_id,
      mes_ano,
      valor_orcado,
      created_by
    )
    VALUES (
      v_company_id,
      p_categoria_id,
      p_mes_ano,
      p_valor,
      auth.uid()
    )
    RETURNING * INTO v_saved;
  END IF;

  INSERT INTO public.fin_audit_logs (
    acao,
    entidade,
    entidade_id,
    user_id,
    company_id,
    antes,
    depois
  )
  VALUES (
    CASE WHEN v_existing.id IS NULL THEN 'CREATE' ELSE 'UPDATE' END,
    'fin_orcamentos',
    v_saved.id,
    auth.uid(),
    v_company_id,
    CASE WHEN v_existing.id IS NULL THEN NULL ELSE pg_catalog.to_jsonb(v_existing) END,
    pg_catalog.to_jsonb(v_saved)
  );

  RETURN jsonb_build_object(
    'id', v_saved.id,
    'updated_at', v_saved.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._planning_delete_meta_guarded(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cid uuid;
  v_before jsonb;
  v_found boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  -- Resolve tenant
  v_cid := public.assert_tenant();
  IF v_cid IS NULL THEN
    RAISE EXCEPTION 'Tenant não encontrado';
  END IF;

  IF NOT has_permission(v_uid, 'planning:meta-compras:edit') THEN
    RAISE EXCEPTION 'Sem permissão para remover metas de compras';
  END IF;

  -- Capture before state and verify tenant ownership
  SELECT jsonb_build_object(
    'id', id, 'year', year, 'month', month, 'categoria', categoria,
    'target_value', target_value, 'ativo', ativo
  ), true
  INTO v_before, v_found
  FROM planning_metas_compra
  WHERE id = p_id AND company_id = v_cid;

  IF NOT COALESCE(v_found, false) THEN
    RAISE EXCEPTION 'Meta não encontrada ou não pertence ao tenant';
  END IF;

  -- Soft delete with tracking
  UPDATE planning_metas_compra
  SET ativo = false, updated_at = now(), deleted_at = now(), deleted_by = v_uid
  WHERE id = p_id AND company_id = v_cid;

  -- Audit trail
  PERFORM audit_log_write(
    'planning',
    'delete_meta',
    'planning_metas_compra',
    p_id::text,
    v_before,
    jsonb_build_object('ativo', false, 'deleted_at', now(), 'deleted_by', v_uid),
    NULL
  );

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public._planning_spend_summary_guarded(p_year integer, p_month integer, p_source text DEFAULT NULL::text, p_categoria text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cid uuid;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  -- Resolve tenant
  v_cid := public.assert_tenant();
  IF v_cid IS NULL THEN
    RAISE EXCEPTION 'Tenant não encontrado';
  END IF;

  IF NOT has_permission(v_uid, 'planning:meta-compras:view')
     AND NOT has_permission(v_uid, 'planning:projecao:view')
     AND NOT has_permission(v_uid, 'planning:ritmo:view')
     AND NOT has_permission(v_uid, 'planning:pressao:view')
     AND NOT has_permission(v_uid, 'planning:radar:view')
  THEN
    RAISE EXCEPTION 'Sem permissão para acessar resumo de planejamento';
  END IF;

  -- Pass company_id to the inner function
  SELECT _planning_spend_summary_inner(v_cid, p_year, p_month, p_source, p_categoria) INTO v_result;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public._planning_upsert_meta_guarded(p_year integer, p_month integer, p_categoria text, p_target_value numeric, p_alerta_amarelo numeric DEFAULT 80, p_alerta_vermelho numeric DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cid uuid;
  v_before jsonb;
  v_after jsonb;
  v_result_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  -- Resolve tenant
  v_cid := public.assert_tenant();
  IF v_cid IS NULL THEN
    RAISE EXCEPTION 'Tenant não encontrado';
  END IF;

  IF NOT has_permission(v_uid, 'planning:meta-compras:edit') THEN
    RAISE EXCEPTION 'Sem permissão para editar metas de compras';
  END IF;

  -- Capture before state (for audit)
  SELECT jsonb_build_object(
    'id', id, 'target_value', target_value,
    'alerta_amarelo_percent', alerta_amarelo_percent,
    'alerta_vermelho_percent', alerta_vermelho_percent,
    'ativo', ativo
  ) INTO v_before
  FROM planning_metas_compra
  WHERE company_id = v_cid AND year = p_year AND month = p_month AND categoria = p_categoria;

  -- Upsert with explicit company_id
  INSERT INTO planning_metas_compra (company_id, year, month, categoria, target_value, alerta_amarelo_percent, alerta_vermelho_percent, ativo, created_by)
  VALUES (v_cid, p_year, p_month, p_categoria, p_target_value, p_alerta_amarelo, p_alerta_vermelho, true, v_uid)
  ON CONFLICT (company_id, year, month, categoria) DO UPDATE SET
    target_value = EXCLUDED.target_value,
    alerta_amarelo_percent = EXCLUDED.alerta_amarelo_percent,
    alerta_vermelho_percent = EXCLUDED.alerta_vermelho_percent,
    ativo = true,
    updated_at = now()
  RETURNING id INTO v_result_id;

  -- Capture after state
  SELECT jsonb_build_object(
    'id', id, 'target_value', target_value,
    'alerta_amarelo_percent', alerta_amarelo_percent,
    'alerta_vermelho_percent', alerta_vermelho_percent,
    'ativo', ativo
  ) INTO v_after
  FROM planning_metas_compra
  WHERE id = v_result_id;

  -- Audit trail
  PERFORM audit_log_write(
    'planning', 
    CASE WHEN v_before IS NULL THEN 'create_meta' ELSE 'update_meta' END,
    'planning_metas_compra',
    v_result_id::text,
    v_before,
    v_after,
    jsonb_build_object('year', p_year, 'month', p_month, 'categoria', p_categoria)
  );

  RETURN jsonb_build_object('success', true, 'id', v_result_id);
END;
$function$

