CREATE OR REPLACE FUNCTION public._validate_fin_presentation_decision_snapshot(p_snapshot jsonb, p_period_start date, p_period_end_exclusive date, p_granularity text, p_reference_type text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_metric text;
  v_metric_type text;
  v_revenue numeric;
BEGIN
  IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'SNAPSHOT_INVALID: objeto obrigatório';
  END IF;
  IF octet_length(p_snapshot::text) > 262144 THEN
    RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: snapshot';
  END IF;
  IF p_snapshot->>'contractVersion' <> 'presentation-decision-snapshot-v1.0' THEN
    RAISE EXCEPTION 'SNAPSHOT_VERSION_UNKNOWN';
  END IF;
  IF p_snapshot->>'referenceType' IS DISTINCT FROM p_reference_type THEN
    RAISE EXCEPTION 'SNAPSHOT_SOURCE_INCOMPATIBLE';
  END IF;
  IF p_snapshot#>>'{period,start}' IS DISTINCT FROM p_period_start::text
     OR p_snapshot#>>'{period,endExclusive}' IS DISTINCT FROM p_period_end_exclusive::text
     OR p_snapshot->>'granularity' IS DISTINCT FROM p_granularity THEN
    RAISE EXCEPTION 'SNAPSHOT_PERIOD_INCOMPATIBLE';
  END IF;
  IF p_snapshot->>'metricFormulaVersion' <> 'managerial-result-v1.0'
     OR COALESCE(length(p_snapshot->>'cutoffDate'), 0) = 0
     OR COALESCE(length(p_snapshot->>'capturedAt'), 0) = 0 THEN
    RAISE EXCEPTION 'SNAPSHOT_AUDIT_FIELDS_MISSING';
  END IF;
  BEGIN
    PERFORM (p_snapshot->>'cutoffDate')::date;
    PERFORM (p_snapshot->>'capturedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'SNAPSHOT_AUDIT_FIELDS_INVALID';
  END;
  IF jsonb_typeof(p_snapshot->'sources') <> 'object'
     OR jsonb_typeof(p_snapshot->'rules') <> 'object'
     OR jsonb_typeof(p_snapshot->'metrics') <> 'object'
     OR jsonb_typeof(p_snapshot->'assumptions') <> 'array' THEN
    RAISE EXCEPTION 'SNAPSHOT_CONTRACT_INVALID';
  END IF;

  FOREACH v_metric IN ARRAY ARRAY['revenue', 'expense', 'result', 'marginPercent', 'cmv', 'cmvPercent'] LOOP
    IF NOT ((p_snapshot->'metrics') ? v_metric) THEN
      RAISE EXCEPTION 'SNAPSHOT_METRIC_MISSING: %', v_metric;
    END IF;
    v_metric_type := jsonb_typeof(p_snapshot->'metrics'->v_metric);
    IF v_metric_type NOT IN ('number', 'null') THEN
      RAISE EXCEPTION 'SNAPSHOT_METRIC_INVALID: %', v_metric;
    END IF;
  END LOOP;
  IF jsonb_typeof(p_snapshot#>'{metrics,revenue}') <> 'number'
     OR jsonb_typeof(p_snapshot#>'{metrics,expense}') <> 'number'
     OR jsonb_typeof(p_snapshot#>'{metrics,result}') <> 'number' THEN
    RAISE EXCEPTION 'SNAPSHOT_METRIC_MISSING';
  END IF;
  v_revenue := (p_snapshot#>>'{metrics,revenue}')::numeric;
  IF v_revenue = 0 AND (
    jsonb_typeof(p_snapshot#>'{metrics,marginPercent}') <> 'null'
    OR jsonb_typeof(p_snapshot#>'{metrics,cmvPercent}') <> 'null'
  ) THEN
    RAISE EXCEPTION 'SNAPSHOT_METRIC_INCOMPATIBLE: zero revenue';
  END IF;

  IF p_snapshot#>>'{sources,actual}' <> 'fin_lancamentos'
     OR p_snapshot#>>'{sources,budget}' <> 'fin_orcamentos'
     OR p_snapshot#>>'{sources,cmvTarget}' <> 'metas_cmv.meta_cmv_total' THEN
    RAISE EXCEPTION 'SNAPSHOT_SOURCE_INCOMPATIBLE';
  END IF;

  IF p_reference_type = 'SCENARIO' THEN
    IF p_snapshot->>'formulaVersion' <> 'presentation-scenario-v1.0'
       OR p_snapshot->>'sourceMode' <> 'scenario'
       OR jsonb_typeof(p_snapshot->'scenarioResult') <> 'object'
       OR jsonb_typeof(p_snapshot->'scenarioDraft') <> 'object'
       OR p_snapshot#>>'{scenarioResult,contractVersion}' <> '1.0'
       OR p_snapshot#>>'{scenarioResult,formulaVersion}' <> 'presentation-scenario-v1.0'
       OR p_snapshot#>>'{scenarioResult,period,start}' IS DISTINCT FROM p_period_start::text
       OR p_snapshot#>>'{scenarioResult,period,endExclusive}' IS DISTINCT FROM p_period_end_exclusive::text
       OR p_snapshot#>>'{scenarioResult,sources,actual}' <> 'fin_lancamentos'
       OR p_snapshot#>>'{scenarioResult,sources,budget}' <> 'fin_orcamentos'
       OR p_snapshot#>>'{scenarioResult,sources,cmvTarget}' <> 'metas_cmv.meta_cmv_total'
       OR jsonb_typeof(p_snapshot#>'{scenarioResult,activeLevers}') <> 'array'
       OR jsonb_array_length(p_snapshot#>'{scenarioResult,activeLevers}') = 0
       OR jsonb_array_length(p_snapshot->'assumptions') = 0
       OR jsonb_array_length(p_snapshot->'assumptions') <> jsonb_array_length(p_snapshot#>'{scenarioResult,activeLevers}')
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(p_snapshot->'assumptions') assumption
         WHERE COALESCE(length(btrim(assumption->>'exactValue')), 0) = 0
       ) THEN
      RAISE EXCEPTION 'SCENARIO_WITHOUT_EXPLICIT_LEVER';
    END IF;
  ELSE
    IF p_snapshot->>'formulaVersion' <> 'presentation-plan-v1.0'
       OR p_snapshot->>'sourceMode' NOT IN ('actual', 'budget', 'projection') THEN
      RAISE EXCEPTION 'SNAPSHOT_SOURCE_INCOMPATIBLE';
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._validate_fin_presentation_meeting_snapshot(p_snapshot jsonb, p_company_id uuid, p_period_start date, p_period_end_exclusive date, p_granularity text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_metric text;
  v_item jsonb;
  v_id uuid;
  v_decision_id uuid;
  v_version integer;
  v_status text;
  v_current_version integer;
  v_current_status text;
BEGIN
  IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'SNAPSHOT_INVALID';
  END IF;
  IF octet_length(p_snapshot::text) > 262144 THEN RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: snapshot'; END IF;
  IF p_snapshot->>'contractVersion' <> 'presentation-meeting-snapshot-v1.0' THEN
    RAISE EXCEPTION 'SNAPSHOT_VERSION_UNKNOWN';
  END IF;
  IF p_snapshot#>>'{period,start}' IS DISTINCT FROM p_period_start::text
     OR p_snapshot#>>'{period,endExclusive}' IS DISTINCT FROM p_period_end_exclusive::text
     OR p_snapshot->>'granularity' IS DISTINCT FROM p_granularity THEN
    RAISE EXCEPTION 'SNAPSHOT_PERIOD_INCOMPATIBLE';
  END IF;
  IF p_snapshot->>'formulaVersion' <> 'presentation-plan-v1.0'
     OR p_snapshot#>>'{sources,actual}' <> 'fin_lancamentos'
     OR p_snapshot#>>'{sources,budget}' <> 'fin_orcamentos'
     OR p_snapshot#>>'{sources,cmvTarget}' <> 'metas_cmv.meta_cmv_total' THEN
    RAISE EXCEPTION 'SNAPSHOT_SOURCE_INCOMPATIBLE';
  END IF;
  IF jsonb_typeof(p_snapshot->'rules') <> 'object'
     OR jsonb_typeof(p_snapshot->'metrics') <> 'object'
     OR jsonb_typeof(p_snapshot->'dataUnavailable') <> 'array'
     OR jsonb_typeof(p_snapshot->'filters') <> 'object'
     OR jsonb_typeof(p_snapshot->'decisions') <> 'array'
     OR jsonb_typeof(p_snapshot->'actions') <> 'array' THEN
    RAISE EXCEPTION 'SNAPSHOT_CONTRACT_INVALID';
  END IF;
  IF jsonb_array_length(p_snapshot->'decisions') > 100
     OR jsonb_array_length(p_snapshot->'actions') > 500
     OR jsonb_array_length(p_snapshot->'dataUnavailable') > 100 THEN
    RAISE EXCEPTION 'PAYLOAD_TOO_LARGE: snapshot lists';
  END IF;
  IF p_snapshot#>>'{filters,comparisonMode}' NOT IN ('actual', 'budget', 'projection')
     OR COALESCE((p_snapshot#>>'{filters,rankingLimit}')::integer, 0) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'SNAPSHOT_FILTER_INVALID';
  END IF;
  BEGIN
    PERFORM (p_snapshot->>'capturedAt')::timestamptz;
    PERFORM (p_snapshot->>'cutoffDate')::date;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'SNAPSHOT_AUDIT_FIELDS_INVALID';
  END;

  FOREACH v_metric IN ARRAY ARRAY['revenue', 'expense', 'result', 'marginPercent', 'cmv', 'cmvPercent'] LOOP
    IF NOT ((p_snapshot->'metrics') ? v_metric)
       OR jsonb_typeof(p_snapshot->'metrics'->v_metric) NOT IN ('number', 'null') THEN
      RAISE EXCEPTION 'SNAPSHOT_METRIC_INVALID: %', v_metric;
    END IF;
  END LOOP;
  IF jsonb_typeof(p_snapshot#>'{metrics,revenue}') = 'number'
     AND (p_snapshot#>>'{metrics,revenue}')::numeric = 0
     AND (jsonb_typeof(p_snapshot#>'{metrics,marginPercent}') <> 'null'
          OR jsonb_typeof(p_snapshot#>'{metrics,cmvPercent}') <> 'null') THEN
    RAISE EXCEPTION 'SNAPSHOT_METRIC_INCOMPATIBLE: zero revenue';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_snapshot->'decisions') LOOP
    BEGIN
      v_id := (v_item->>'id')::uuid;
      v_decision_id := (v_item->>'decisionId')::uuid;
      v_version := (v_item->>'version')::integer;
      v_status := v_item->>'status';
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SNAPSHOT_REFERENCE_INVALID'; END;
    IF v_id <> v_decision_id OR v_version < 1 OR v_status NOT IN ('DRAFT', 'APPROVED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED') THEN
      RAISE EXCEPTION 'SNAPSHOT_REFERENCE_INVALID';
    END IF;
    SELECT decision.version, decision.status INTO v_current_version, v_current_status
    FROM public.fin_presentation_decisions decision
    WHERE decision.id = v_id AND decision.company_id = p_company_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'REFERENCE_OUT_OF_TENANT'; END IF;
    IF v_current_version IS DISTINCT FROM v_version OR v_current_status IS DISTINCT FROM v_status THEN
      RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT: decision %', v_id;
    END IF;
  END LOOP;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_snapshot->'actions') LOOP
    BEGIN
      v_id := (v_item->>'id')::uuid;
      v_decision_id := (v_item->>'decisionId')::uuid;
      v_version := (v_item->>'version')::integer;
      v_status := v_item->>'status';
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SNAPSHOT_REFERENCE_INVALID'; END;
    IF v_version < 1 OR v_status NOT IN ('PENDING', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED') THEN
      RAISE EXCEPTION 'SNAPSHOT_REFERENCE_INVALID';
    END IF;
    SELECT action.version, action.status INTO v_current_version, v_current_status
    FROM public.fin_presentation_decision_actions action
    WHERE action.id = v_id AND action.decision_id = v_decision_id AND action.company_id = p_company_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'REFERENCE_OUT_OF_TENANT'; END IF;
    IF v_current_version IS DISTINCT FROM v_version OR v_current_status IS DISTINCT FROM v_status THEN
      RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT: action %', v_id;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_checkup_suite()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_company uuid;
  v_sections jsonb := '{}'::jsonb;
  v_status text;
  v_details jsonb;
  v_profile_company uuid;
  v_current_company uuid;
  v_tables text[] := ARRAY['produtos','suppliers','movimentacoes_estoque','purchase_orders','purchase_order_items','salmon_entries','fin_lancamentos'];
  v_tbl text;
  v_rls_items jsonb := '[]'::jsonb;
  v_rls_ok boolean := true;
  v_rel_row boolean;
  v_rel_force boolean;
  v_pol_items jsonb := '[]'::jsonb;
  v_pol_ok boolean := true;
  v_mov_count bigint;
  v_start date := current_date - 7;
  v_end date := current_date;
  v_rpc_items jsonb := '[]'::jsonb;
  v_rpc_ok boolean := true;
  v_dummy record;
BEGIN
  v_actor := auth.uid();
  IF NOT public.has_permission(v_actor, 'system:global:manage') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  v_company := public.assert_tenant();

  -- A) tenant_identity
  SELECT company_id INTO v_profile_company FROM public.profiles WHERE id = v_actor;
  BEGIN
    SELECT public.get_current_company_id() INTO v_current_company;
  EXCEPTION WHEN OTHERS THEN
    v_current_company := NULL;
  END;
  IF v_profile_company IS NULL OR v_current_company IS NULL OR v_profile_company <> v_current_company THEN
    v_status := 'FAIL';
  ELSE
    v_status := 'PASS';
  END IF;
  v_sections := v_sections || jsonb_build_object('tenant_identity', jsonb_build_object(
    'status', v_status,
    'details', jsonb_build_object('profile_company_id', v_profile_company, 'get_current_company_id', v_current_company)
  ));

  -- B) company_id_integrity
  DECLARE v_comp_exists boolean;
  BEGIN
    SELECT EXISTS(SELECT 1 FROM public.companies WHERE id = v_company) INTO v_comp_exists;
    v_status := CASE WHEN v_comp_exists THEN 'PASS' ELSE 'FAIL' END;
    v_details := jsonb_build_object('note', 'enforced by FK + trg_block_placeholder_company', 'company_exists', v_comp_exists);
    v_sections := v_sections || jsonb_build_object('company_id_integrity', jsonb_build_object('status', v_status, 'details', v_details));
  END;

  -- C) rls_force_rls
  FOR v_tbl IN SELECT unnest(v_tables) LOOP
    BEGIN
      SELECT relrowsecurity, relforcerowsecurity INTO v_rel_row, v_rel_force
      FROM pg_class WHERE relname = v_tbl AND relnamespace = 'public'::regnamespace;
      IF NOT FOUND THEN
        v_rls_items := v_rls_items || jsonb_build_object('table', v_tbl, 'status', 'SKIP', 'note', 'table not found');
      ELSIF NOT v_rel_row OR NOT v_rel_force THEN
        v_rls_ok := false;
        v_rls_items := v_rls_items || jsonb_build_object('table', v_tbl, 'status', 'FAIL', 'rls_enabled', v_rel_row, 'force_rls', v_rel_force);
      ELSE
        v_rls_items := v_rls_items || jsonb_build_object('table', v_tbl, 'status', 'PASS');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_rls_items := v_rls_items || jsonb_build_object('table', v_tbl, 'status', 'FAIL', 'error', SQLERRM);
      v_rls_ok := false;
    END;
  END LOOP;
  v_sections := v_sections || jsonb_build_object('rls_force_rls', jsonb_build_object(
    'status', CASE WHEN v_rls_ok THEN 'PASS' ELSE 'FAIL' END, 'details', jsonb_build_object('tables', v_rls_items)
  ));

  -- D) policy_safety_scan
  BEGIN
    SELECT jsonb_agg(jsonb_build_object('table', tablename, 'policy', policyname, 'cmd', cmd, 'qual_preview', LEFT(qual::text, 120)))
    INTO v_details FROM pg_policies
    WHERE schemaname = 'public' AND tablename = ANY(v_tables) AND cmd = 'SELECT'
      AND (qual::text = 'true' OR qual::text NOT ILIKE '%company_id%');
    IF v_details IS NOT NULL AND jsonb_array_length(v_details) > 0 THEN
      v_pol_ok := false; v_pol_items := v_details;
    ELSE
      v_pol_items := '[]'::jsonb;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_pol_ok := false; v_pol_items := jsonb_build_object('error', SQLERRM);
  END;
  v_sections := v_sections || jsonb_build_object('policy_safety_scan', jsonb_build_object(
    'status', CASE WHEN v_pol_ok THEN 'PASS' ELSE 'FAIL' END, 'details', jsonb_build_object('suspicious_policies', v_pol_items)
  ));

  -- E) estoque_sanity
  BEGIN
    SELECT count(*) INTO v_mov_count FROM public.movimentacoes_estoque WHERE company_id = v_company;
    v_details := jsonb_build_object('movimentacoes_count', v_mov_count);
    v_status := 'PASS';
  EXCEPTION WHEN OTHERS THEN
    v_details := jsonb_build_object('error', SQLERRM); v_status := 'FAIL';
  END;
  v_sections := v_sections || jsonb_build_object('estoque_sanity', jsonb_build_object('status', v_status, 'details', v_details));

  -- F) relatorios_sanity — static PERFORM, no EXECUTE
  BEGIN
    PERFORM public.get_relatorios_kpis(v_start, v_end);
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_kpis', 'status', 'PASS');
  EXCEPTION WHEN OTHERS THEN
    v_rpc_ok := false;
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_kpis', 'status', 'FAIL', 'error', SQLERRM);
  END;

  BEGIN
    PERFORM public.get_relatorios_score(v_start, v_end);
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_score', 'status', 'PASS');
  EXCEPTION WHEN OTHERS THEN
    v_rpc_ok := false;
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_score', 'status', 'FAIL', 'error', SQLERRM);
  END;

  BEGIN
    PERFORM public.get_relatorios_tendencia(v_start, v_end);
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_tendencia', 'status', 'PASS');
  EXCEPTION WHEN OTHERS THEN
    v_rpc_ok := false;
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_tendencia', 'status', 'FAIL', 'error', SQLERRM);
  END;

  BEGIN
    PERFORM public.get_relatorios_compras(v_start, v_end);
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_compras', 'status', 'PASS');
  EXCEPTION WHEN OTHERS THEN
    v_rpc_ok := false;
    v_rpc_items := v_rpc_items || jsonb_build_object('rpc', 'get_relatorios_compras', 'status', 'FAIL', 'error', SQLERRM);
  END;

  v_sections := v_sections || jsonb_build_object('relatorios_sanity', jsonb_build_object(
    'status', CASE WHEN v_rpc_ok THEN 'PASS' ELSE 'FAIL' END, 'details', jsonb_build_object('rpcs', v_rpc_items)
  ));

  -- G) rbac_sql_lint
  v_sections := v_sections || jsonb_build_object('rbac_sql_lint', jsonb_build_object(
    'status', 'SKIPPED', 'details', jsonb_build_object('reason', 'run via Edge/CI when configured')
  ));

  RETURN jsonb_build_object(
    'meta', jsonb_build_object('ran_at', now(), 'company_id', v_company, 'actor_user_id', v_actor),
    'sections', v_sections
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_users()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_company uuid:=public.assert_tenant(); v_result jsonb;
BEGIN
 IF NOT public.has_any_permission(auth.uid(),ARRAY['configuracoes:usuarios:view','configuracoes:usuarios:manage','users:manage','system:global:manage']) THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PERMISSION_DENIED';
 END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p.id,'nome',p.nome,'email',p.email,'company_id',m.company_id)), '[]'::jsonb)
 INTO v_result FROM public.profiles p JOIN public.company_memberships m ON m.user_id=p.id WHERE m.company_id=v_company;
 RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_super_admin(p_target_user_id uuid, p_enable boolean, p_confirmation_email text, p_confirmation_phrase text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_company uuid;
  v_target_email text;
  v_target_company uuid;
  v_was_super boolean;
BEGIN
  IF NOT public.has_permission(v_actor, 'system:global:manage') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  v_company := public.assert_tenant();

  -- Block self-demotion
  IF v_actor = p_target_user_id AND NOT p_enable THEN
    RETURN jsonb_build_object('success', false, 'error', 'Não é possível rebaixar a si mesmo.');
  END IF;

  -- Get target info
  SELECT email, company_id INTO v_target_email, v_target_company
  FROM public.profiles WHERE id = p_target_user_id;

  IF v_target_email IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Usuário não encontrado.');
  END IF;

  IF NOT public.is_company_member(p_target_user_id,v_company) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Usuário não pertence a esta empresa.');
  END IF;

  -- Double confirmation
  IF p_confirmation_email IS DISTINCT FROM v_target_email THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email de confirmação não confere.');
  END IF;

  IF p_enable AND p_confirmation_phrase IS DISTINCT FROM 'PROMOVER' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Frase de confirmação incorreta. Digite PROMOVER.');
  END IF;

  IF NOT p_enable AND p_confirmation_phrase IS DISTINCT FROM 'REBAIXAR' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Frase de confirmação incorreta. Digite REBAIXAR.');
  END IF;

  -- Check current status using has_permission
  v_was_super := public.has_permission(p_target_user_id, 'system:global:manage');

  -- Apply change
  IF p_enable THEN
    INSERT INTO public.user_permissions (user_id, company_id, permission_key, effect, granted_by)
    VALUES (p_target_user_id, v_company, 'system:global:manage', 'ALLOW', v_actor)
    ON CONFLICT (user_id,company_id,permission_key) DO UPDATE SET effect='ALLOW',granted_by=EXCLUDED.granted_by;
  ELSE
    DELETE FROM public.user_permissions
    WHERE user_id = p_target_user_id AND company_id = v_company AND permission_key = 'system:global:manage';
  END IF;

  -- Audit log
  INSERT INTO public.admin_actions_log (company_id, actor_user_id, action, target_user_id, target_email, details)
  VALUES (
    v_company, v_actor,
    CASE WHEN p_enable THEN 'SET_SUPER_ADMIN' ELSE 'UNSET_SUPER_ADMIN' END,
    p_target_user_id, v_target_email,
    jsonb_build_object(
      'before', jsonb_build_object('is_super_admin', v_was_super),
      'after', jsonb_build_object('is_super_admin', p_enable)
    )
  );

  RETURN jsonb_build_object('success', true, 'message',
    CASE WHEN p_enable THEN 'Usuário promovido a super_admin.' ELSE 'Permissão super_admin removida.' END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_company_membership(p_actor_user_id uuid, p_company_id uuid, p_user_id uuid, p_role app_role DEFAULT NULL::app_role, p_permissions text[] DEFAULT NULL::text[], p_status text DEFAULT 'active'::text, p_job_role_id uuid DEFAULT NULL::uuid, p_sector text DEFAULT NULL::text, p_if_not_exists boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor_permissions text[]; v_id uuid; v_existed boolean; v_previous_status text;
BEGIN
 v_actor_permissions:=public.get_company_permissions(p_actor_user_id,p_company_id);
 -- Cross-company provisioning is reserved for the platform permission in the
 -- actor's original company. It does not grant operational access to the actor.
 IF NOT v_actor_permissions && ARRAY['configuracoes:usuarios:manage','users:manage','system:global:manage'] THEN
   SELECT public.get_company_permissions(p_actor_user_id,p.company_id) INTO v_actor_permissions
   FROM public.profiles p WHERE p.id=p_actor_user_id;
   IF NOT COALESCE('system:global:manage'=ANY(v_actor_permissions),false) THEN
     RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PERMISSION_DENIED';
   END IF;
 END IF;
 IF p_status NOT IN ('active','inactive','revoked') THEN RAISE EXCEPTION 'INVALID_MEMBERSHIP_STATUS'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=p_company_id AND ativo
   AND id<>'00000000-0000-0000-0000-000000000001'::uuid) THEN RAISE EXCEPTION 'COMPANY_INACTIVE'; END IF;
 IF p_job_role_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.job_roles WHERE id=p_job_role_id AND company_id=p_company_id) THEN
   RAISE EXCEPTION 'JOB_ROLE_COMPANY_MISMATCH';
 END IF;
 -- Serialize retries/concurrent creation for the same identity and unit.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text||':'||p_company_id::text,0));
 SELECT id,status INTO v_id,v_previous_status FROM public.company_memberships WHERE user_id=p_user_id AND company_id=p_company_id FOR UPDATE;
 v_existed:=v_id IS NOT NULL;
 IF v_existed AND p_if_not_exists THEN
   IF v_previous_status<>'revoked' THEN RETURN jsonb_build_object('membership_id',v_id,'already_exists',true); END IF;
   -- Explicitly adding a removed user restores only the newly selected grants.
   DELETE FROM public.user_roles WHERE user_id=p_user_id AND company_id=p_company_id;
   DELETE FROM public.user_permissions WHERE user_id=p_user_id AND company_id=p_company_id;
 END IF;
 -- Só system:global:manage confere super-admin (no banco e, após a remoção da
 -- expansão legada, também na UI). system:admin é chave legada de módulo, faz
 -- parte do role admin e não pode bloquear a atribuição do perfil.
 IF NOT COALESCE('system:global:manage'=ANY(v_actor_permissions),false) AND
   (COALESCE(p_permissions,ARRAY[]::text[]) && ARRAY['system:global:manage']
     OR EXISTS(SELECT 1 FROM public.role_permissions WHERE role=p_role::text AND permission_key='system:global:manage')) THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PRIVILEGE_ESCALATION_DENIED';
 END IF;
 -- Delegar system:admin (criar ou promover outro Admin) exige que o próprio
 -- ator já seja Admin na unidade, ou super-admin. Sem isso, qualquer ator com
 -- users:manage/configuracoes:usuarios:manage (o gate básico desta função)
 -- poderia criar Admins livremente — regressão silenciosa vs. 20260910003448.
 IF NOT COALESCE('system:global:manage'=ANY(v_actor_permissions),false)
   AND NOT COALESCE('system:admin'=ANY(v_actor_permissions),false)
   AND (COALESCE(p_permissions,ARRAY[]::text[]) && ARRAY['system:admin']
     OR EXISTS(SELECT 1 FROM public.role_permissions WHERE role=p_role::text AND permission_key='system:admin')) THEN
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PRIVILEGE_ESCALATION_DENIED';
 END IF;
 IF p_permissions IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(p_permissions) k WHERE NOT EXISTS(SELECT 1 FROM public.permissions WHERE key=k)) THEN
   RAISE EXCEPTION 'UNKNOWN_PERMISSION';
 END IF;
 INSERT INTO public.company_memberships(user_id,company_id,status,job_role_id,sector)
 VALUES(p_user_id,p_company_id,p_status,p_job_role_id,p_sector)
 ON CONFLICT(user_id,company_id) DO UPDATE SET status=EXCLUDED.status,job_role_id=EXCLUDED.job_role_id,
   sector=EXCLUDED.sector,updated_at=now() RETURNING id INTO v_id;
 IF p_role IS NOT NULL THEN
   DELETE FROM public.user_roles WHERE user_id=p_user_id AND company_id=p_company_id;
   INSERT INTO public.user_roles(user_id,company_id,role) VALUES(p_user_id,p_company_id,p_role);
 END IF;
 IF p_permissions IS NOT NULL THEN
   DELETE FROM public.user_permissions WHERE user_id=p_user_id AND company_id=p_company_id;
   INSERT INTO public.user_permissions(user_id,company_id,permission_key,effect,granted_by)
   SELECT p_user_id,p_company_id,p.key,
     CASE WHEN p.key=ANY(p_permissions) THEN 'ALLOW' ELSE 'DENY' END,p_actor_user_id
   FROM public.permissions p WHERE p.key=ANY(p_permissions) OR EXISTS(
     SELECT 1 FROM public.user_roles ur JOIN public.role_permissions rp ON rp.role=ur.role::text
     WHERE ur.user_id=p_user_id AND ur.company_id=p_company_id AND rp.permission_key=p.key);
 END IF;
 INSERT INTO public.admin_actions_log(actor_user_id,company_id,action,target_user_id,details)
 VALUES(p_actor_user_id,p_company_id,CASE WHEN v_existed THEN 'MEMBERSHIP_UPDATED' ELSE 'MEMBERSHIP_CREATED' END,p_user_id,
   jsonb_build_object('status',p_status,'role',p_role,'permissions_count',cardinality(p_permissions)));
 RETURN jsonb_build_object('membership_id',v_id,'already_exists',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.aplicar_regras_categorizacao()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_total int := 0;
  v_categorizados int := 0;
  v_regra record;
  v_match_count int;
BEGIN
  v_company_id := assert_tenant();

  IF NOT has_any_permission(auth.uid(), ARRAY[
    'financeiro:categorizacao:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  -- Count uncategorized (excluding those with categorized rateio)
  SELECT count(*) INTO v_total
  FROM fin_lancamentos fl
  WHERE fl.company_id = v_company_id
    AND fl.categoria_id IS NULL
    AND fl.status NOT IN ('CANCELADO')
    AND NOT EXISTS (
      SELECT 1 FROM fin_lancamento_rateios flr
      WHERE flr.lancamento_id = fl.id
        AND flr.categoria_id IS NOT NULL
    );

  IF v_total = 0 THEN
    RETURN json_build_object('total', 0, 'categorizados', 0);
  END IF;

  FOR v_regra IN
    SELECT id, padrao, tipo_match, categoria_id, centro_custo_id
    FROM fin_regras_categorizacao
    WHERE company_id = v_company_id AND ativo = true
    ORDER BY prioridade DESC, created_at ASC
  LOOP
    WITH matched AS (
      UPDATE fin_lancamentos fl
      SET
        categoria_id = v_regra.categoria_id,
        centro_custo_id = COALESCE(v_regra.centro_custo_id, fl.centro_custo_id),
        updated_at = now()
      WHERE fl.company_id = v_company_id
        AND fl.categoria_id IS NULL
        AND fl.status NOT IN ('CANCELADO')
        AND NOT EXISTS (
          SELECT 1 FROM fin_lancamento_rateios flr
          WHERE flr.lancamento_id = fl.id
            AND flr.categoria_id IS NOT NULL
        )
        AND (
          CASE v_regra.tipo_match
            WHEN 'contem' THEN lower(COALESCE(fl.descricao, '')) LIKE '%' || lower(v_regra.padrao) || '%'
            WHEN 'exato'  THEN lower(COALESCE(fl.descricao, '')) = lower(v_regra.padrao)
            WHEN 'regex'  THEN COALESCE(fl.descricao, '') ~* v_regra.padrao
            ELSE false
          END
        )
      RETURNING fl.id
    )
    SELECT count(*) INTO v_match_count FROM matched;
    v_categorizados := v_categorizados + v_match_count;
  END LOOP;

  RETURN json_build_object('total', v_total, 'categorizados', v_categorizados);
END;
$function$

CREATE OR REPLACE FUNCTION public.aprovar_ferias(p_registro_id uuid, p_aprovado_por uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_registro RECORD;
  v_saldo RECORD;
  v_new_gozados int;
  v_new_restantes int;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;
  IF NOT public.has_any_permission(auth.uid(), ARRAY['rh:ferias:approve', 'rh:manage', 'rh:admin', 'system:global:manage']) THEN
    RAISE EXCEPTION 'Sem permissão para aprovar férias.';
  END IF;

  SELECT * INTO v_registro FROM rh_ferias_afastamentos WHERE id = p_registro_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro não encontrado'; END IF;
  IF v_registro.status != 'SOLICITADO' THEN RAISE EXCEPTION 'Solicitação já processada (status: %)', v_registro.status; END IF;

  IF v_registro.tipo = 'ferias' THEN
    SELECT * INTO v_saldo FROM rh_ferias_saldo WHERE colaborador_id = v_registro.colaborador_id FOR UPDATE;
    IF FOUND AND v_saldo.dias_restantes < v_registro.dias_uteis THEN
      RAISE EXCEPTION 'Saldo insuficiente! Disponível: % dias. Solicitado: % dias.', v_saldo.dias_restantes, v_registro.dias_uteis;
    END IF;
  END IF;

  UPDATE rh_ferias_afastamentos SET status = 'APROVADO', aprovado_por = p_aprovado_por, aprovado_em = now(), updated_at = now() WHERE id = p_registro_id;

  IF v_registro.tipo = 'ferias' AND v_saldo.id IS NOT NULL THEN
    v_new_gozados := v_saldo.dias_gozados + v_registro.dias_uteis;
    v_new_restantes := GREATEST(0, v_saldo.dias_direito - v_new_gozados - v_saldo.dias_vendidos);
    UPDATE rh_ferias_saldo SET dias_gozados = v_new_gozados, dias_restantes = v_new_restantes, updated_at = now() WHERE id = v_saldo.id;
  END IF;

  PERFORM public.log_audit('rpc', 'rh', 'rh_ferias_afastamentos', p_registro_id, 'FERIAS_APPROVE',
    jsonb_build_object('status_anterior', 'SOLICITADO', 'colaborador_id', v_registro.colaborador_id),
    jsonb_build_object('status', 'APROVADO', 'aprovado_por', p_aprovado_por));
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_requisicao_estoque_movement_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  req_item record;
  prod record;
  expected_qty numeric;
  v_item_id uuid;
BEGIN
  IF NEW.origem IS DISTINCT FROM 'REQUISICAO_ESTOQUE' OR NEW.status IS DISTINCT FROM 'ATIVO' THEN
    RETURN NEW;
  END IF;

  IF NEW.produto_id IS NULL THEN
    RAISE EXCEPTION 'Movimentação de requisição sem produto_id';
  END IF;

  IF COALESCE(NEW.reference_type, '') = 'REQUISICAO_ITEM' THEN
    IF NEW.reference_id IS NULL THEN
      RAISE EXCEPTION 'Movimentação de requisição por item sem reference_id';
    END IF;

    BEGIN
      v_item_id := NEW.reference_id::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'reference_id da movimentação de requisição é inválido: %', NEW.reference_id;
    END;

    SELECT rei.id,
           rei.requisicao_id,
           rei.quantidade_solicitada,
           rei.quantidade_atendida,
           r.company_id
      INTO req_item
    FROM public.requisicao_estoque_itens rei
    JOIN public.requisicoes_estoque r ON r.id = rei.requisicao_id
    WHERE rei.id = v_item_id
      AND rei.produto_id = NEW.produto_id
      AND r.company_id = NEW.company_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Movimentação não corresponde ao item da requisição';
    END IF;

    IF NEW.referencia_id IS NOT NULL AND NEW.referencia_id <> req_item.requisicao_id::text THEN
      RAISE EXCEPTION 'referencia_id divergente para baixa do item da requisição';
    END IF;
  ELSE
    IF NEW.referencia_id IS NULL THEN
      RAISE EXCEPTION 'Movimentação de requisição sem referencia_id';
    END IF;

    SELECT rei.id,
           rei.requisicao_id,
           rei.quantidade_solicitada,
           rei.quantidade_atendida,
           r.company_id
      INTO req_item
    FROM public.requisicao_estoque_itens rei
    JOIN public.requisicoes_estoque r ON r.id = rei.requisicao_id
    WHERE rei.requisicao_id = NEW.referencia_id::uuid
      AND rei.produto_id = NEW.produto_id
      AND r.company_id = NEW.company_id
    ORDER BY rei.created_at DESC, rei.id DESC
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Movimentação não corresponde a item da requisição';
    END IF;
  END IF;

  SELECT p.fator_conversao_padrao
    INTO prod
  FROM public.produtos p
  WHERE p.id = NEW.produto_id
    AND p.company_id = NEW.company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto da movimentação de requisição não encontrado';
  END IF;

  expected_qty := ROUND((
    COALESCE(NULLIF(req_item.quantidade_atendida, 0), req_item.quantidade_solicitada)
    * COALESCE(NULLIF(prod.fator_conversao_padrao, 0), 1)
  )::numeric, 3);

  IF NEW.direction IS DISTINCT FROM 'OUT' THEN
    RAISE EXCEPTION 'Baixa de requisição deve ter direction OUT';
  END IF;

  IF NEW.tipo IS DISTINCT FROM 'SAIDA' THEN
    RAISE EXCEPTION 'Baixa de requisição deve ter tipo SAIDA';
  END IF;

  IF ROUND(COALESCE(NEW.quantidade, 0)::numeric, 3) <> expected_qty THEN
    RAISE EXCEPTION 'Quantidade inconsistente para baixa de requisição. Esperado: %, recebido: %', expected_qty, NEW.quantidade;
  END IF;

  RETURN NEW;
END;
$function$

