CREATE OR REPLACE FUNCTION public.audit_log_write(_module text, _action text, _entity_type text, _entity_id text DEFAULT NULL::text, _before jsonb DEFAULT NULL::jsonb, _after jsonb DEFAULT NULL::jsonb, _metadata jsonb DEFAULT NULL::jsonb, _severity text DEFAULT 'INFO'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_email text;
  v_role text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT public.assert_tenant(), p.email INTO v_company_id, v_email
  FROM profiles p WHERE p.id = v_user_id;

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Tenant not found';
  END IF;

  SELECT string_agg(ur.role::text, ',') INTO v_role
  FROM user_roles ur WHERE ur.user_id = v_user_id AND ur.company_id = public.assert_tenant();

  INSERT INTO audit_logs (
    company_id, actor_user_id, actor_email, actor_role,
    module, action, entity, entity_id,
    before, after, metadata, severity, source, success
  ) VALUES (
    v_company_id, v_user_id, v_email, v_role,
    _module, _action, _entity_type, _entity_id::uuid,
    _before, _after, _metadata, _severity, 'edge_function', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_trigger_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text;
  v_entity text;
  v_action text;
  v_before jsonb;
  v_after jsonb;
  v_entity_id uuid;
  v_sensitive_keys text[] := ARRAY['cpf','senha','password','token','card_number','secret'];
  k text;
BEGIN
  v_module := TG_ARGV[0];
  v_entity := TG_ARGV[1];

  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE';
    v_after := row_to_json(NEW)::jsonb;
    v_entity_id := NEW.id;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'UPDATE';
    v_before := row_to_json(OLD)::jsonb;
    v_after := row_to_json(NEW)::jsonb;
    v_entity_id := NEW.id;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'DELETE';
    v_before := row_to_json(OLD)::jsonb;
    v_entity_id := OLD.id;
  END IF;

  -- Mask sensitive fields
  FOREACH k IN ARRAY v_sensitive_keys LOOP
    IF v_before IS NOT NULL AND v_before ? k THEN
      v_before := v_before || jsonb_build_object(k, '***');
    END IF;
    IF v_after IS NOT NULL AND v_after ? k THEN
      v_after := v_after || jsonb_build_object(k, '***');
    END IF;
  END LOOP;

  INSERT INTO public.audit_logs (actor_user_id, source, module, entity, entity_id, action, before, after)
  VALUES (auth.uid(), 'db', v_module, v_entity, v_entity_id, v_action, v_before, v_after);

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.batch_reorder_fin_categorias(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_company_id uuid;
  v_item jsonb;
  v_cat_id uuid;
  v_ordem int;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  -- Resolve company
  v_company_id := public.assert_tenant();

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Empresa não encontrada';
  END IF;

  -- Validate all categories belong to same company and are active
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_items) AS item
    LEFT JOIN fin_categorias fc ON fc.id = (item->>'id')::uuid
    WHERE fc.id IS NULL OR fc.company_id != v_company_id OR fc.ativo = false
  ) THEN
    RAISE EXCEPTION 'Uma ou mais categorias inválidas ou de outro tenant';
  END IF;

  -- Validate all categories share same parent_id and tipo
  IF (
    SELECT COUNT(DISTINCT COALESCE(fc.parent_id, '00000000-0000-0000-0000-000000000000') || '|' || fc.tipo)
    FROM jsonb_array_elements(p_items) AS item
    JOIN fin_categorias fc ON fc.id = (item->>'id')::uuid
  ) > 1 THEN
    RAISE EXCEPTION 'Todas as categorias devem ter o mesmo parent_id e tipo';
  END IF;

  -- Apply updates with lock
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_cat_id := (v_item->>'id')::uuid;
    v_ordem := (v_item->>'ordem')::int;

    UPDATE fin_categorias
    SET ordem = v_ordem, updated_at = now()
    WHERE id = v_cat_id AND company_id = v_company_id;
  END LOOP;

  RETURN jsonb_build_object('status', 'ok', 'updated', jsonb_array_length(p_items));
END;
$function$

CREATE OR REPLACE FUNCTION public.can_access_company_document(p_path text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_collaborator uuid; v_company uuid; v_requested text; v_permissions text[];
BEGIN
 IF auth.uid() IS NULL OR p_action NOT IN ('view','create','edit','delete') THEN RETURN false; END IF;
 BEGIN v_collaborator:=split_part(p_path,'/',1)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
 SELECT company_id INTO v_company FROM public.rh_colaboradores WHERE id=v_collaborator;
 IF NOT public.is_company_member(auth.uid(),v_company) THEN RETURN false; END IF;
 v_requested:=NULLIF(current_setting('request.headers',true),'')::jsonb->>'x-company-id';
 IF v_requested IS NOT NULL AND v_requested<>v_company::text THEN RETURN false; END IF;
 v_permissions:=public.get_company_permissions(auth.uid(),v_company);
 RETURN v_permissions && ARRAY['rh:documentos:'||p_action,'rh:documentos:manage','rh:manage','system:global:manage'];
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_salmon_entry_atomic(p_entry_id uuid, p_reason text DEFAULT 'Cancelamento de entrada'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry RECORD;
  v_mov RECORD;
  v_estorno_id uuid;
  v_caller uuid;
  v_company_id uuid;
BEGIN
  v_company_id := assert_tenant();
  v_caller := auth.uid();
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;

  SELECT * INTO v_entry FROM salmon_entries
  WHERE id = p_entry_id AND company_id = v_company_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada não encontrada ou sem permissão.'; END IF;
  IF v_entry.status = 'CANCELLED' THEN RAISE EXCEPTION 'Entrada já cancelada.'; END IF;

  IF EXISTS (SELECT 1 FROM salmon_manipulations
             WHERE entry_id = p_entry_id AND status = 'ACTIVE' AND company_id = v_company_id) THEN
    RAISE EXCEPTION 'Existem manipulações ativas vinculadas. Cancele-as primeiro.';
  END IF;

  UPDATE salmon_entries SET status = 'CANCELLED', updated_at = now()
  WHERE id = p_entry_id AND company_id = v_company_id;

  SELECT * INTO v_mov FROM movimentacoes_estoque
    WHERE reference_type = 'SALMON_ENTRY' AND reference_id = p_entry_id::text
      AND status = 'ATIVO' AND company_id = v_company_id
    FOR UPDATE;

  IF v_mov.id IS NOT NULL THEN
    -- Insere o estorno ANTES de cancelar o original (trg_validate_estorno recusa
    -- estorno_de_id que já esteja CANCELADO).
    INSERT INTO movimentacoes_estoque (
      produto_id, data, tipo, quantidade, custo_unitario, custo_total,
      origem, observacao, created_by, status, estorno_de_id,
      reference_type, reference_id, internal_transfer, source_module, salmon_lot_id, company_id
    ) VALUES (
      v_mov.produto_id, CURRENT_DATE, 'ENTRADA_ESTORNO', v_mov.quantidade,
      v_mov.custo_unitario, v_mov.custo_total, 'ESTORNO',
      'Estorno — ' || p_reason, v_caller, 'ATIVO', v_mov.id,
      'SALMON_ENTRY', v_mov.reference_id || '_ESTORNO', false, 'salmon', v_mov.salmon_lot_id, v_company_id
    ) RETURNING id INTO v_estorno_id;

    UPDATE movimentacoes_estoque SET
      status = 'CANCELADO', cancelado_em = now(), cancelado_por = v_caller,
      justificativa_cancelamento = p_reason
    WHERE id = v_mov.id AND company_id = v_company_id;
  END IF;

  PERFORM log_audit('rpc', 'salmon', 'salmon_entries', p_entry_id, 'CANCEL_ATOMIC',
    jsonb_build_object('status_anterior', 'ACTIVE', 'gross_kg', v_entry.gross_kg),
    jsonb_build_object('reason', p_reason, 'estorno_id', v_estorno_id));

  RETURN jsonb_build_object('cancelled', true, 'entry_id', p_entry_id, 'estorno_id', v_estorno_id, 'company_id', v_company_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_salmon_manipulation_atomic(p_manip_id uuid, p_reason text DEFAULT 'Cancelamento de manipulação'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_manip RECORD;
  v_mov RECORD;
  v_estorno_id uuid;
  v_caller uuid;
  v_company_id uuid;
BEGIN
  v_company_id := assert_tenant();
  v_caller := auth.uid();
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;

  SELECT * INTO v_manip FROM salmon_manipulations
  WHERE id = p_manip_id AND company_id = v_company_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Manipulação não encontrada ou sem permissão.'; END IF;
  IF v_manip.status = 'CANCELLED' THEN RAISE EXCEPTION 'Manipulação já cancelada.'; END IF;

  UPDATE salmon_manipulations SET status = 'CANCELLED', updated_at = now()
  WHERE id = p_manip_id AND company_id = v_company_id;

  SELECT * INTO v_mov FROM movimentacoes_estoque
    WHERE reference_type = 'SALMON_MANIPULATION' AND reference_id = p_manip_id::text
      AND status = 'ATIVO' AND company_id = v_company_id
    FOR UPDATE;

  IF v_mov.id IS NOT NULL THEN
    -- Insere o estorno ANTES de cancelar o original (trg_validate_estorno recusa
    -- estorno_de_id que já esteja CANCELADO).
    INSERT INTO movimentacoes_estoque (
      produto_id, data, tipo, quantidade, custo_unitario, custo_total,
      origem, observacao, created_by, status, estorno_de_id,
      reference_type, reference_id, internal_transfer, source_module, salmon_lot_id, setor, company_id
    ) VALUES (
      v_mov.produto_id, CURRENT_DATE, 'SAIDA_ESTORNO', v_mov.quantidade,
      v_mov.custo_unitario, v_mov.custo_total, 'ESTORNO',
      'Estorno — ' || p_reason, v_caller, 'ATIVO', v_mov.id,
      'SALMON_MANIPULATION', v_mov.reference_id || '_ESTORNO', true, 'salmon', v_mov.salmon_lot_id, v_mov.setor, v_company_id
    ) RETURNING id INTO v_estorno_id;

    UPDATE movimentacoes_estoque SET
      status = 'CANCELADO', cancelado_em = now(), cancelado_por = v_caller,
      justificativa_cancelamento = p_reason
    WHERE id = v_mov.id AND company_id = v_company_id;
  END IF;

  PERFORM log_audit('rpc', 'salmon', 'salmon_manipulations', p_manip_id, 'CANCEL_ATOMIC',
    jsonb_build_object('status_anterior', 'ACTIVE', 'gross_out_kg', v_manip.gross_out_kg),
    jsonb_build_object('reason', p_reason, 'estorno_id', v_estorno_id));

  RETURN jsonb_build_object('cancelled', true, 'manipulation_id', p_manip_id, 'estorno_id', v_estorno_id, 'company_id', v_company_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_old_audit_logs(p_months integer DEFAULT 24)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_deleted int;
BEGIN
  DELETE FROM audit_logs WHERE created_at < now() - (p_months || ' months')::interval;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  INSERT INTO audit_logs (source, module, entity, action, metadata, success)
  VALUES ('db', 'system', 'audit_logs', 'JOB_CLEANUP', jsonb_build_object('deleted_count', v_deleted, 'retention_months', p_months), true);
  RETURN v_deleted;
END; $function$

CREATE OR REPLACE FUNCTION public.compute_requisicao_status_agregado(p_requisicao_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total_items int;
  atendidos int;
  recusados int;
  solicitados int;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.requisicoes_estoque r
    WHERE r.id = p_requisicao_id
      AND r.company_id = public.get_current_company_id()
  ) THEN
    RETURN NULL;
  END IF;

  SELECT
    count(*),
    count(*) FILTER (WHERE status = 'ATENDIDO'),
    count(*) FILTER (WHERE status = 'RECUSADO'),
    count(*) FILTER (WHERE status = 'SOLICITADO')
  INTO total_items, atendidos, recusados, solicitados
  FROM public.requisicao_estoque_itens
  WHERE requisicao_id = p_requisicao_id;

  IF total_items = 0 THEN RETURN 'SOLICITADA'; END IF;
  IF recusados = total_items THEN RETURN 'NEGADA'; END IF;
  IF atendidos = total_items THEN RETURN 'ATENDIDA'; END IF;
  IF solicitados = total_items THEN RETURN 'SOLICITADA'; END IF;
  IF atendidos > 0 AND recusados > 0 AND solicitados = 0 THEN RETURN 'PARCIALMENTE_ATENDIDA'; END IF;
  IF atendidos > 0 AND solicitados > 0 THEN RETURN 'PARCIALMENTE_ATENDIDA'; END IF;
  IF recusados > 0 AND solicitados > 0 THEN RETURN 'SOLICITADA'; END IF;

  RETURN 'SOLICITADA';
END;
$function$

CREATE OR REPLACE FUNCTION public.contar_lancamentos_sem_categoria()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_count int;
BEGIN
  v_company_id := assert_tenant();

  IF NOT has_any_permission(auth.uid(), ARRAY[
    'financeiro:categorizacao:view',
    'financeiro:categorizacao:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  SELECT count(*)::int INTO v_count
  FROM fin_lancamentos fl
  WHERE fl.company_id = v_company_id
    AND fl.categoria_id IS NULL
    AND fl.status NOT IN ('CANCELADO')
    AND NOT EXISTS (
      SELECT 1 FROM fin_lancamento_rateios flr
      WHERE flr.lancamento_id = fl.id
        AND flr.categoria_id IS NOT NULL
    );

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.copiar_orcamento_mes(p_origem text, p_destino text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_inserted integer;
BEGIN
  v_company_id := assert_tenant();

  IF NOT has_any_permission(auth.uid(), ARRAY[
    'financeiro:orcamento:edit',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED';
  END IF;

  INSERT INTO fin_orcamentos (company_id, categoria_id, mes_ano, valor_orcado)
  SELECT v_company_id, categoria_id, p_destino, valor_orcado
  FROM fin_orcamentos
  WHERE mes_ano = p_origem AND company_id = v_company_id
  ON CONFLICT (company_id, mes_ano, categoria_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  INSERT INTO fin_audit_logs (acao, entidade, user_id, company_id, depois)
  VALUES (
    'COPY_ORCAMENTO', 'fin_orcamentos', auth.uid(), v_company_id,
    jsonb_build_object('origem', p_origem, 'destino', p_destino, 'linhas_copiadas', v_inserted)
  );

  RETURN v_inserted;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_cotacao_atomic(p_titulo text, p_observacao text DEFAULT NULL::text, p_data_validade date DEFAULT NULL::date, p_origin_type text DEFAULT 'MANUAL'::text, p_origin_ref uuid DEFAULT NULL::uuid, p_itens jsonb DEFAULT '[]'::jsonb, p_fornecedores jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_user    uuid;
  v_id      uuid;
  v_codigo  text;
  v_base    int;
  v_elem    jsonb;
  i         int;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF v_user IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: não autenticado'; END IF;

  IF NOT public.has_any_permission(v_user, ARRAY['compras:cotacao:create','system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: compras:cotacao:create';
  END IF;

  IF p_titulo IS NULL OR length(btrim(p_titulo)) = 0 THEN
    RAISE EXCEPTION 'VALIDATION: título obrigatório';
  END IF;
  IF p_origin_type IS NOT NULL AND p_origin_type NOT IN ('MANUAL','ALERTA','REQUISICAO') THEN
    RAISE EXCEPTION 'VALIDATION: origin_type inválido';
  END IF;

  v_base := (SELECT count(*) FROM public.cotacoes WHERE company_id = v_company);
  FOR i IN 1..15 LOOP
    v_codigo := 'COT-' || lpad((v_base + i)::text, 5, '0');
    BEGIN
      INSERT INTO public.cotacoes (company_id, codigo, titulo, observacao, data_validade, origin_type, origin_ref, status, created_by)
      VALUES (v_company, v_codigo, btrim(p_titulo), NULLIF(btrim(coalesce(p_observacao,'')),''), p_data_validade,
              coalesce(p_origin_type,'MANUAL'), p_origin_ref, 'RASCUNHO', v_user)
      RETURNING id INTO v_id;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      v_id := NULL;
    END;
  END LOOP;
  IF v_id IS NULL THEN RAISE EXCEPTION 'VALIDATION: falha ao gerar código da cotação'; END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_itens
      (cotacao_id, company_id, produto_id, produto_nome_snapshot, unidade_snapshot,
       purchase_unit_snapshot, conversion_factor_snapshot, quantidade, observacao)
    VALUES (
      v_id, v_company,
      NULLIF(v_elem->>'produto_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'produto_nome_snapshot'),''), 'Item'),
      NULLIF(v_elem->>'unidade_snapshot',''),
      NULLIF(v_elem->>'purchase_unit_snapshot',''),
      coalesce((v_elem->>'conversion_factor_snapshot')::numeric, 1),
      coalesce((v_elem->>'quantidade')::numeric, 0),
      NULLIF(v_elem->>'observacao','')
    );
  END LOOP;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_fornecedores, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_fornecedores
      (cotacao_id, company_id, supplier_id, supplier_nome_snapshot, whatsapp_snapshot, pedido_minimo_snapshot, status)
    VALUES (
      v_id, v_company,
      NULLIF(v_elem->>'supplier_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'supplier_nome_snapshot'),''), 'Fornecedor'),
      NULLIF(v_elem->>'whatsapp_snapshot',''),
      coalesce((v_elem->>'pedido_minimo_snapshot')::numeric, 0),
      'AGUARDANDO'
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', v_id, 'codigo', v_codigo);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_inventory_atomic(p_tipo text, p_data date, p_hora text, p_turno_id uuid, p_categorias text[] DEFAULT '{}'::text[], p_observacao text DEFAULT ''::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_user_id uuid;
  v_inv_id uuid;
  v_itens_count int := 0;
BEGIN
  BEGIN
    v_tenant := assert_tenant();
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Erro de Tenant: %', SQLERRM;
  END;

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;

  IF NOT has_any_permission(v_user_id, ARRAY['inventario:criar:create', 'system:global:manage']) THEN
    RAISE EXCEPTION 'Permissão negada: inventario:criar:create necessário';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_inv_id FROM inventarios WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN RETURN v_inv_id; END IF;
  END IF;

  INSERT INTO inventarios (
    company_id, tipo, data, hora, turno_id, categorias,
    responsavel_user_id, observacao, status, idempotency_key
  ) VALUES (
    v_tenant, p_tipo, p_data, p_hora::time, p_turno_id, COALESCE(p_categorias, '{}'),
    v_user_id, COALESCE(p_observacao, ''), 'RASCUNHO', p_idempotency_key
  ) RETURNING id INTO v_inv_id;

  IF p_tipo = 'completo' THEN
    INSERT INTO inventario_itens (company_id, inventario_id, produto_id, tipo_item, saldo_teorico, custo_snapshot)
    SELECT
      v_tenant, v_inv_id, p.id, 'geral',
      GREATEST(0, COALESCE(p.saldo_atual, 0)),
      -- Use default_cost_base_unit (per base unit) as primary.
      -- Fallback divides custo_padrao (per purchase unit) by fator to get per-base-unit cost.
      COALESCE(
        NULLIF(p.default_cost_base_unit, 0),
        CASE
          WHEN COALESCE(p.fator_conversao_padrao, 0) > 0
            THEN p.custo_padrao / p.fator_conversao_padrao
          ELSE p.custo_padrao
        END,
        0
      )
    FROM produtos p
    WHERE p.ativo = true AND p.company_id = v_tenant;

    GET DIAGNOSTICS v_itens_count = ROW_COUNT;
  END IF;

  INSERT INTO audit_inventario_log (company_id, inventario_id, user_id, user_role, acao, depois)
  VALUES (
    v_tenant, v_inv_id, v_user_id,
    COALESCE((SELECT string_agg(role::text, ',') FROM user_roles WHERE user_id = v_user_id AND company_id = public.assert_tenant()), 'unknown'),
    'CRIACAO',
    jsonb_build_object('tipo', p_tipo, 'turno_id', p_turno_id, 'itens_count', v_itens_count)
  );

  RETURN v_inv_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_order_atomic(p_payload jsonb, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_company uuid;
  v_order_id uuid;
  v_title text;
  v_type text;
  v_status text;
  v_total numeric := 0;
  v_item jsonb;
  v_is_mercado boolean;
  v_shopping_status text;
  v_existing_id uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_company := assert_tenant();

  SELECT id INTO v_existing_id
  FROM purchase_orders
  WHERE company_id = v_company AND idempotency_key = p_idempotency_key;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object('status','idempotent','order_id', v_existing_id);
  END IF;

  v_title := p_payload->>'title';
  v_type  := p_payload->>'type';
  v_is_mercado := v_type IN ('MERCADO','SAZONAL');
  v_status := CASE WHEN v_is_mercado THEN 'PENDING' ELSE 'OPEN' END;
  v_shopping_status := CASE WHEN v_is_mercado THEN 'PENDING' ELSE 'OK' END;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload->'items')
  LOOP
    v_total := v_total + (v_item->>'qty_requested')::numeric * (v_item->>'estimated_unit_value')::numeric;
  END LOOP;

  INSERT INTO purchase_orders (
    title, type, priority, category, supplier_name, payment_type,
    need_by_date, delivery_forecast_date, responsible_user_id, notes,
    status, total_estimated, created_by, company_id, idempotency_key,
    origin, origin_ref
  ) VALUES (
    v_title, v_type,
    COALESCE(p_payload->>'priority','MEDIA'),
    COALESCE(p_payload->>'category',''),
    NULLIF(p_payload->>'supplier_name',''),
    NULLIF(p_payload->>'payment_type',''),
    NULLIF(p_payload->>'need_by_date','')::date,
    NULLIF(p_payload->>'delivery_forecast_date','')::date,
    NULLIF(p_payload->>'responsible_user_id','')::uuid,
    COALESCE(p_payload->>'notes',''),
    v_status, v_total, v_user, v_company, p_idempotency_key,
    COALESCE(NULLIF(p_payload->>'origin',''), 'MANUAL'),
    NULLIF(p_payload->>'origin_ref','')
  ) RETURNING id INTO v_order_id;

  INSERT INTO purchase_order_items (
    order_id, stock_item_id, name_snapshot, unit_snapshot,
    estimated_unit_value, qty_requested,
    purchase_unit_snapshot, purchase_unit_cost_snapshot, conversion_factor_snapshot,
    shopping_status, company_id
  )
  SELECT
    v_order_id,
    NULLIF(item->>'stock_item_id','')::uuid,
    item->>'name_snapshot',
    item->>'unit_snapshot',
    (item->>'estimated_unit_value')::numeric,
    (item->>'qty_requested')::numeric,
    COALESCE(NULLIF(item->>'purchase_unit_snapshot',''), item->>'unit_snapshot'),
    COALESCE((item->>'purchase_unit_cost_snapshot')::numeric, (item->>'estimated_unit_value')::numeric),
    COALESCE((item->>'conversion_factor_snapshot')::numeric, 1),
    v_shopping_status,
    v_company
  FROM jsonb_array_elements(p_payload->'items') AS item;

  INSERT INTO audit_log (tabela, registro_id, acao, user_id)
  VALUES ('purchase_orders', v_order_id, 'CRIACAO', v_user);

  RETURN jsonb_build_object('status','created','order_id', v_order_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_orders_from_cotacao_atomic(p_cotacao_id uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company     uuid;
  v_user        uuid;
  v_cot         record;
  v_forn        record;
  v_order_id    uuid;
  v_total       numeric;
  v_items       int;
  v_orders      int := 0;
  v_total_items int := 0;
  v_order_ids   uuid[] := '{}';
  v_sel_count   int;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();
  IF v_user IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: não autenticado'; END IF;

  IF NOT public.has_any_permission(v_user, ARRAY['compras:cotacao:close','compras:cotacao:manage','system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: compras:cotacao:close';
  END IF;

  SELECT id, codigo, titulo, status, updated_at
    INTO v_cot
  FROM public.cotacoes
  WHERE id = p_cotacao_id AND company_id = v_company AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;

  IF v_cot.status = 'CONVERTIDA' THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: % (cotação já convertida em pedido)', v_cot.status;
  END IF;
  IF v_cot.status IN ('CANCELADA','ENCERRADA') THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: % (cotação encerrada)', v_cot.status;
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_cot.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;

  SELECT count(*) INTO v_sel_count
  FROM public.cotacao_respostas r
  JOIN public.cotacao_fornecedores f ON f.id = r.cotacao_fornecedor_id
  WHERE f.cotacao_id = p_cotacao_id
    AND r.company_id = v_company
    AND r.selecionado = true
    AND r.disponivel = true
    AND r.preco_unitario IS NOT NULL;
  IF v_sel_count = 0 THEN
    RAISE EXCEPTION 'VALIDATION: nenhuma resposta selecionada — gere e salve a sugestão antes de converter';
  END IF;

  FOR v_forn IN
    SELECT f.id, f.supplier_nome_snapshot, f.condicao_pagamento
    FROM public.cotacao_fornecedores f
    WHERE f.cotacao_id = p_cotacao_id
      AND f.company_id = v_company
      AND EXISTS (
        SELECT 1 FROM public.cotacao_respostas r
        WHERE r.cotacao_fornecedor_id = f.id
          AND r.company_id = v_company
          AND r.selecionado = true
          AND r.disponivel = true
          AND r.preco_unitario IS NOT NULL
      )
    ORDER BY f.supplier_nome_snapshot
  LOOP
    SELECT coalesce(sum(r.preco_unitario * i.quantidade), 0) INTO v_total
    FROM public.cotacao_respostas r
    JOIN public.cotacao_itens i ON i.id = r.cotacao_item_id
    WHERE r.cotacao_fornecedor_id = v_forn.id
      AND r.company_id = v_company
      AND r.selecionado = true
      AND r.disponivel = true
      AND r.preco_unitario IS NOT NULL;

    INSERT INTO public.purchase_orders (
      title, type, priority, category, supplier_name, payment_type,
      notes, status, total_estimated, created_by, company_id,
      idempotency_key, origin, origin_ref
    ) VALUES (
      v_cot.codigo || ' — ' || v_forn.supplier_nome_snapshot,
      'FORNECEDOR', 'MEDIA', '',
      v_forn.supplier_nome_snapshot,
      NULLIF(btrim(coalesce(v_forn.condicao_pagamento,'')), ''),
      'Gerado da cotação ' || v_cot.codigo || ' (' || v_cot.titulo || ')',
      'OPEN', coalesce(v_total, 0), v_user, v_company,
      gen_random_uuid(), 'COTACAO', p_cotacao_id::text
    ) RETURNING id INTO v_order_id;

    INSERT INTO public.purchase_order_items (
      order_id, stock_item_id, name_snapshot, unit_snapshot,
      estimated_unit_value, qty_requested,
      purchase_unit_snapshot, purchase_unit_cost_snapshot, conversion_factor_snapshot,
      shopping_status, company_id
    )
    SELECT
      v_order_id,
      i.produto_id,
      i.produto_nome_snapshot,
      coalesce(NULLIF(i.unidade_snapshot,''), 'UN'),
      r.preco_unitario,
      i.quantidade,
      coalesce(NULLIF(i.purchase_unit_snapshot,''), NULLIF(i.unidade_snapshot,''), 'UN'),
      r.preco_unitario,
      coalesce(i.conversion_factor_snapshot, 1),
      'OK',
      v_company
    FROM public.cotacao_respostas r
    JOIN public.cotacao_itens i ON i.id = r.cotacao_item_id
    WHERE r.cotacao_fornecedor_id = v_forn.id
      AND r.company_id = v_company
      AND r.selecionado = true
      AND r.disponivel = true
      AND r.preco_unitario IS NOT NULL;

    GET DIAGNOSTICS v_items = ROW_COUNT;
    v_total_items := v_total_items + v_items;
    v_orders := v_orders + 1;
    v_order_ids := array_append(v_order_ids, v_order_id);

    UPDATE public.cotacao_fornecedores
       SET status = 'FECHADO'
     WHERE id = v_forn.id AND company_id = v_company;

    INSERT INTO public.audit_log (tabela, registro_id, acao, user_id)
    VALUES ('purchase_orders', v_order_id, 'CRIACAO', v_user);
  END LOOP;

  UPDATE public.cotacoes
     SET status = 'CONVERTIDA'
   WHERE id = p_cotacao_id AND company_id = v_company;

  UPDATE public.cotacao_sugestoes s
     SET dados_json = coalesce(s.dados_json, '{}'::jsonb)
                      || jsonb_build_object('generated_order_ids', to_jsonb(v_order_ids))
   WHERE s.id = (
     SELECT id FROM public.cotacao_sugestoes
     WHERE cotacao_id = p_cotacao_id AND company_id = v_company
     ORDER BY created_at DESC
     LIMIT 1
   );

  RETURN jsonb_build_object(
    'success', true,
    'orders', v_orders,
    'items', v_total_items,
    'order_ids', to_jsonb(v_order_ids)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_quick_inventory_atomic(p_items jsonb, p_observacao text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor_id       uuid;
    v_company_id     uuid;
    v_inv_id         uuid;
    v_item           jsonb;
    v_product        record;
    v_saldo          numeric;
    v_counted        numeric;
    v_diff           numeric;
    v_diff_pct       numeric;
    v_cost_base      numeric;
    v_impact         numeric;
    v_today          text;
    v_now            timestamptz;
    v_total_items    int := 0;
    v_adjusted       int := 0;
    v_total_impact   numeric := 0;
    v_acuracia_sum   numeric := 0;
    v_acuracia_count int := 0;
    v_turno_id       uuid;
BEGIN
    v_actor_id := auth.uid();
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Não autenticado' USING ERRCODE = 'P0001';
    END IF;

    IF NOT has_any_permission(v_actor_id, ARRAY['inventario:rapido:create', 'inventario:criar:create', 'system:global:manage']) THEN
        RAISE EXCEPTION 'Forbidden: inventario:rapido:create required';
    END IF;

    v_company_id := public.assert_tenant();

    IF v_company_id IS NULL OR v_company_id = '00000000-0000-0000-0000-000000000001'::uuid THEN
        RAISE EXCEPTION 'Tenant inválido' USING ERRCODE = 'P0001';
    END IF;

    IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' THEN
        IF EXISTS (
            SELECT 1 FROM public.inventarios
            WHERE company_id = v_company_id
              AND idempotency_key = p_idempotency_key
        ) THEN
            RETURN jsonb_build_object('success', false, 'reason', 'duplicate', 'message', 'Inventário rápido já registrado');
        END IF;
    END IF;

    IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Nenhum item informado para contagem';
    END IF;

    v_now := now();
    v_today := to_char(v_now AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD');

    SELECT id INTO v_turno_id
    FROM public.turnos
    WHERE company_id = v_company_id
    ORDER BY created_at ASC
    LIMIT 1;

    v_inv_id := gen_random_uuid();
    BEGIN
        INSERT INTO public.inventarios (
            id, company_id, tipo, status, data, hora,
            responsavel_user_id, observacao, idempotency_key, turno_id
        ) VALUES (
            v_inv_id, v_company_id, 'rapido', 'EM_CONTAGEM', v_today,
            to_char(v_now AT TIME ZONE 'America/Sao_Paulo', 'HH24:MI:SS'),
            v_actor_id, COALESCE(p_observacao, 'Inventário Rápido'),
            COALESCE(NULLIF(p_idempotency_key, ''), gen_random_uuid()::text),
            v_turno_id
        );
    EXCEPTION WHEN unique_violation THEN
        RETURN jsonb_build_object('success', false, 'reason', 'duplicate', 'message', 'Inventário rápido já registrado');
    END;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_counted := COALESCE((v_item->>'counted_quantity')::numeric, 0);
        IF v_counted < 0 THEN
            RAISE EXCEPTION 'Quantidade negativa não permitida para produto %', v_item->>'product_id';
        END IF;

        SELECT * INTO v_product
        FROM public.produtos
        WHERE id = (v_item->>'product_id')::uuid
          AND company_id = v_company_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Produto não encontrado: %', v_item->>'product_id';
        END IF;
        IF NOT v_product.ativo THEN
            RAISE EXCEPTION 'Produto inativo: %', v_product.nome_produto;
        END IF;

        SELECT COALESCE(SUM(
            CASE WHEN direction = 'IN' THEN quantidade ELSE -quantidade END
        ), 0) INTO v_saldo
        FROM public.movimentacoes_estoque
        WHERE produto_id = v_product.id
          AND company_id = v_company_id
          AND status = 'ATIVO';

        v_diff := v_counted - v_saldo;
        v_diff_pct := CASE WHEN v_saldo > 0 THEN round((v_diff / v_saldo) * 100, 2) ELSE 0 END;

        v_cost_base := COALESCE(NULLIF(v_product.avg30_cost_base_unit, 0),
                                NULLIF(v_product.last_cost_base_unit, 0),
                                NULLIF(v_product.default_cost_base_unit, 0), 0);
        v_impact := round(abs(v_diff) * v_cost_base, 2);

        INSERT INTO public.inventario_itens (
            inventario_id, company_id, produto_id, tipo_item,
            saldo_teorico, contagem_fisica,
            diferenca_qtd, diferenca_percent,
            custo_snapshot, impacto_financeiro,
            classificacao, contado_por, contagem_inicio, contagem_fim
        ) VALUES (
            v_inv_id, v_company_id, v_product.id, 'geral',
            v_saldo, v_counted,
            v_diff, v_diff_pct,
            v_cost_base, v_impact,
            CASE
                WHEN abs(v_diff_pct) > 10 OR v_impact > 500 THEN 'CRITICO'
                WHEN abs(v_diff_pct) > 5 OR v_impact > 100 THEN 'ALERTA'
                ELSE 'NORMAL'
            END,
            v_actor_id, v_now, v_now
        );

        v_total_items := v_total_items + 1;
        v_total_impact := v_total_impact + v_impact;

        IF v_saldo > 0 THEN
            v_acuracia_sum := v_acuracia_sum + LEAST(v_counted / v_saldo, 1.0);
            v_acuracia_count := v_acuracia_count + 1;
        ELSIF v_counted = 0 THEN
            v_acuracia_sum := v_acuracia_sum + 1.0;
            v_acuracia_count := v_acuracia_count + 1;
        END IF;

        IF v_diff <> 0 THEN
            INSERT INTO public.movimentacoes_estoque (
                produto_id, company_id, data, tipo, quantidade,
                custo_unitario, custo_total, origem, observacao,
                created_by, reference_type, reference_id,
                source_module, direction
            ) VALUES (
                v_product.id, v_company_id, v_today,
                CASE WHEN v_diff > 0 THEN 'ENTRADA' ELSE 'SAIDA' END,
                abs(v_diff),
                round(v_cost_base, 4),
                round(abs(v_diff) * v_cost_base, 2),
                'Inventário Rápido',
                format('Ajuste inventário rápido: %s (%s → %s %s)',
                    v_product.nome_produto,
                    round(v_saldo, 2)::text,
                    round(v_counted, 2)::text,
                    v_product.unidade_medida),
                v_actor_id,
                'QUICK_INVENTORY', v_inv_id::text,
                'inventario',
                CASE WHEN v_diff > 0 THEN 'IN' ELSE 'OUT' END
            );
            v_adjusted := v_adjusted + 1;
        END IF;
    END LOOP;

    UPDATE public.inventarios
    SET status = 'FINALIZADO',
        finalizado_em = v_now,
        finalizado_por = v_actor_id,
        acuracia_percent = CASE WHEN v_acuracia_count > 0
            THEN round((v_acuracia_sum / v_acuracia_count) * 100, 2)
            ELSE 100 END,
        drift_total_valor = v_total_impact,
        updated_at = v_now
    WHERE id = v_inv_id;

    INSERT INTO public.audit_logs (
        action, entity, entity_id, module, actor_user_id, company_id,
        severity, source, success, metadata
    ) VALUES (
        'QUICK_INVENTORY', 'inventarios', v_inv_id::text,
        'inventario', v_actor_id, v_company_id,
        CASE WHEN v_total_impact > 500 THEN 'warning' ELSE 'info' END,
        'rpc', true,
        jsonb_build_object(
            'total_items', v_total_items,
            'adjusted', v_adjusted,
            'total_impact', v_total_impact,
            'acuracia', CASE WHEN v_acuracia_count > 0
                THEN round((v_acuracia_sum / v_acuracia_count) * 100, 2)
                ELSE 100 END
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'inventory_id', v_inv_id,
        'total_items', v_total_items,
        'adjusted', v_adjusted,
        'total_impact', v_total_impact
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_salmon_entry_atomic(p_entry_date date, p_lot text, p_sif text, p_supplier_name text, p_boxes integer, p_units integer, p_gross_kg numeric, p_total_value numeric, p_notes text DEFAULT ''::text, p_expiration_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_id uuid;
  v_mov_id uuid;
  v_produto_id uuid;
  v_cost_per_kg numeric;
  v_supplier_uuid uuid;
  v_caller uuid;
  v_company_id uuid;
BEGIN
  -- Multi-tenant enforcement
  v_company_id := assert_tenant();
  v_caller := auth.uid();
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;
  IF p_gross_kg <= 0 THEN RAISE EXCEPTION 'gross_kg deve ser > 0'; END IF;
  IF p_total_value < 0 THEN RAISE EXCEPTION 'total_value não pode ser negativo'; END IF;
  IF p_expiration_date IS NOT NULL AND p_expiration_date < p_entry_date THEN
    RAISE EXCEPTION 'Validade (%) não pode ser anterior à data de entrada (%).', p_expiration_date, p_entry_date;
  END IF;

  v_cost_per_kg := CASE WHEN p_gross_kg > 0 THEN ROUND(p_total_value / p_gross_kg, 4) ELSE 0 END;

  -- 1. Insert salmon_entries
  INSERT INTO salmon_entries (
    entry_date, lot, sif, supplier_name, boxes, units, gross_kg, total_value, notes, created_by, company_id,
    expiration_date
  ) VALUES (
    p_entry_date, COALESCE(p_lot,''), COALESCE(p_sif,''), COALESCE(p_supplier_name,''),
    COALESCE(p_boxes,0), COALESCE(p_units,0), p_gross_kg, p_total_value,
    COALESCE(p_notes,''), v_caller, v_company_id,
    p_expiration_date
  ) RETURNING id INTO v_entry_id;

  -- 2. Ensure salmon raw product (v_produto_id is global reference but logically belongs to the tenant)
  SELECT ensure_salmon_raw_product() INTO v_produto_id;

  -- 3. Mirror to stock (ENTRADA)
  SELECT id INTO v_mov_id FROM movimentacoes_estoque
    WHERE reference_type = 'SALMON_ENTRY' AND reference_id = v_entry_id::text
      AND status = 'ATIVO' AND company_id = v_company_id
    FOR UPDATE;

  IF v_mov_id IS NOT NULL THEN
    UPDATE movimentacoes_estoque SET
      quantidade = p_gross_kg, custo_unitario = v_cost_per_kg,
      custo_total = ROUND((p_gross_kg * v_cost_per_kg)::numeric, 2),
      data = p_entry_date,
      observacao = 'Entrada Salmão Bruto — Lote: ' || COALESCE(p_lot,'') || ' — Forn: ' || COALESCE(p_supplier_name,'')
        || CASE WHEN p_expiration_date IS NULL THEN '' ELSE ' — Val: ' || to_char(p_expiration_date, 'DD/MM/YYYY') END,
      editado_em = now(), editado_por = v_caller,
      salmon_lot_id = p_lot
    WHERE id = v_mov_id AND company_id = v_company_id;
  ELSE
    INSERT INTO movimentacoes_estoque (
      produto_id, data, tipo, quantidade, custo_unitario, custo_total,
      origem, observacao, created_by, status,
      reference_type, reference_id, internal_transfer, source_module, salmon_lot_id, company_id
    ) VALUES (
      v_produto_id, p_entry_date, 'ENTRADA', p_gross_kg, v_cost_per_kg,
      ROUND((p_gross_kg * v_cost_per_kg)::numeric, 2),
      'Controle de Salmão',
      'Entrada Salmão Bruto — Lote: ' || COALESCE(p_lot,'') || ' — Forn: ' || COALESCE(p_supplier_name,'')
        || CASE WHEN p_expiration_date IS NULL THEN '' ELSE ' — Val: ' || to_char(p_expiration_date, 'DD/MM/YYYY') END,
      v_caller, 'ATIVO', 'SALMON_ENTRY', v_entry_id::text, false, 'salmon', p_lot, v_company_id
    ) RETURNING id INTO v_mov_id;
  END IF;

  -- 4. Update produto cost (Global but context of company insert)
  IF v_cost_per_kg > 0 THEN
    UPDATE produtos SET
      last_cost_purchase_unit = v_cost_per_kg, last_cost_base_unit = v_cost_per_kg,
      last_purchase_date = p_entry_date::text, last_supplier = p_supplier_name,
      custo_padrao = CASE WHEN custo_padrao = 0 THEN v_cost_per_kg ELSE custo_padrao END,
      default_cost_purchase_unit = CASE WHEN default_cost_purchase_unit = 0 THEN v_cost_per_kg ELSE default_cost_purchase_unit END,
      default_cost_base_unit = CASE WHEN default_cost_base_unit = 0 THEN v_cost_per_kg ELSE default_cost_base_unit END
    WHERE id = v_produto_id AND (company_id = v_company_id OR company_id IS NULL);
  END IF;

  -- 5. Upsert supplier + supplier_item_prices
  IF p_supplier_name IS NOT NULL AND p_supplier_name != '' THEN
    INSERT INTO suppliers (name, company_id) VALUES (p_supplier_name, v_company_id)
    ON CONFLICT (name, company_id) DO UPDATE SET updated_at = now()
    RETURNING id INTO v_supplier_uuid;

    IF v_supplier_uuid IS NOT NULL THEN
      INSERT INTO supplier_item_prices (supplier_id, supplier_uuid, stock_item_id, unit_cost, purchase_unit, last_updated_at, source, company_id)
      VALUES (p_supplier_name, v_supplier_uuid, v_produto_id, v_cost_per_kg, 'KG', now(), 'salmon', v_company_id)
      ON CONFLICT (supplier_id, stock_item_id, company_id) DO UPDATE SET
        unit_cost = EXCLUDED.unit_cost, supplier_uuid = EXCLUDED.supplier_uuid,
        last_updated_at = EXCLUDED.last_updated_at, source = 'salmon';
    END IF;
  END IF;

  -- 6. Audit (includes company_id)
  PERFORM log_audit('rpc', 'salmon', 'salmon_entries', v_entry_id, 'CREATE_ATOMIC', NULL,
    jsonb_build_object('gross_kg', p_gross_kg, 'total_value', p_total_value, 'lot', p_lot,
      'supplier', p_supplier_name, 'mov_id', v_mov_id, 'expiration_date', p_expiration_date));

  RETURN jsonb_build_object('entry_id', v_entry_id, 'movement_id', v_mov_id, 'unit_cost', v_cost_per_kg,
    'expiration_date', p_expiration_date, 'company_id', v_company_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_salmon_manipulation_atomic(p_entry_id uuid, p_manipulation_date date, p_fish_count integer, p_gross_out_kg numeric, p_clean_in_kg numeric, p_leftover_kg numeric DEFAULT 0, p_notes text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry RECORD;
  v_manip_id uuid;
  v_mov_id uuid;
  v_produto_id uuid;
  v_cost_per_kg numeric;
  v_caller uuid;
  v_company_id uuid;
BEGIN
  v_company_id := assert_tenant();
  v_caller := auth.uid();
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;
  IF p_gross_out_kg <= 0 THEN RAISE EXCEPTION 'gross_out_kg deve ser > 0'; END IF;
  IF p_clean_in_kg < 0 THEN RAISE EXCEPTION 'clean_in_kg não pode ser negativo'; END IF;

  -- Lock parent entry by company_id
  SELECT * INTO v_entry FROM salmon_entries 
  WHERE id = p_entry_id AND company_id = v_company_id 
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada não encontrada ou sem permissão.'; END IF;
  IF v_entry.status != 'ACTIVE' THEN RAISE EXCEPTION 'Entrada não está ativa (status: %)', v_entry.status; END IF;

  v_cost_per_kg := CASE WHEN v_entry.gross_kg > 0 THEN ROUND(v_entry.total_value / v_entry.gross_kg, 4) ELSE 0 END;

  -- 1. Insert manipulation
  INSERT INTO salmon_manipulations (
    entry_id, manipulation_date, lot, sif, supplier_name, fish_count,
    gross_out_kg, clean_in_kg, leftover_kg, cost_per_kg_gross, notes, created_by, company_id
  ) VALUES (
    p_entry_id, p_manipulation_date, v_entry.lot, v_entry.sif, v_entry.supplier_name,
    COALESCE(p_fish_count, 0), p_gross_out_kg, p_clean_in_kg,
    COALESCE(p_leftover_kg, 0), v_cost_per_kg, COALESCE(p_notes,''), v_caller, v_company_id
  ) RETURNING id INTO v_manip_id;

  -- 2. Mirror to stock (SAIDA for gross)
  SELECT ensure_salmon_raw_product() INTO v_produto_id;

  SELECT id INTO v_mov_id FROM movimentacoes_estoque
    WHERE reference_type = 'SALMON_MANIPULATION' AND reference_id = v_manip_id::text 
      AND status = 'ATIVO' AND company_id = v_company_id
    FOR UPDATE;

  IF v_mov_id IS NOT NULL THEN
    UPDATE movimentacoes_estoque SET
      quantidade = p_gross_out_kg, custo_unitario = v_cost_per_kg,
      custo_total = ROUND((p_gross_out_kg * v_cost_per_kg)::numeric, 2),
      data = p_manipulation_date,
      observacao = 'Saída Manipulação — Lote: ' || v_entry.lot,
      editado_em = now(), editado_por = v_caller, salmon_lot_id = v_entry.lot
    WHERE id = v_mov_id AND company_id = v_company_id;
  ELSE
    INSERT INTO movimentacoes_estoque (
      produto_id, data, tipo, quantidade, custo_unitario, custo_total,
      origem, observacao, created_by, status,
      reference_type, reference_id, internal_transfer, source_module, salmon_lot_id, setor, company_id
    ) VALUES (
      v_produto_id, p_manipulation_date, 'SAIDA', p_gross_out_kg, v_cost_per_kg,
      ROUND((p_gross_out_kg * v_cost_per_kg)::numeric, 2),
      'Controle de Salmão', 'Saída Manipulação — Lote: ' || v_entry.lot,
      v_caller, 'ATIVO', 'SALMON_MANIPULATION', v_manip_id::text, true, 'salmon', v_entry.lot, 'Sushi', v_company_id
    ) RETURNING id INTO v_mov_id;
  END IF;

  -- 3. Audit
  PERFORM log_audit('rpc', 'salmon', 'salmon_manipulations', v_manip_id, 'CREATE_ATOMIC', NULL,
    jsonb_build_object(
      'entry_id', p_entry_id, 'gross_out_kg', p_gross_out_kg, 'clean_in_kg', p_clean_in_kg,
      'cost_per_kg', v_cost_per_kg, 'mov_id', v_mov_id
    ));

  RETURN jsonb_build_object(
    'manipulation_id', v_manip_id, 'movement_id', v_mov_id,
    'waste_kg', GREATEST(p_gross_out_kg - p_clean_in_kg, 0),
    'yield_percent', CASE WHEN p_gross_out_kg > 0 THEN ROUND(p_clean_in_kg / p_gross_out_kg * 100, 2) ELSE 0 END,
    'cost_per_kg_gross', v_cost_per_kg,
    'company_id', v_company_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_transfer(p_conta_origem uuid, p_conta_destino uuid, p_valor numeric, p_data date, p_descricao text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_company uuid;
BEGIN
  v_company := assert_tenant();
  IF NOT (has_permission(auth.uid(), 'finance:manage') OR has_permission(auth.uid(), 'financeiro:lancamentos:create')) THEN
    RAISE EXCEPTION 'Sem permissão (financeiro:lancamentos:create)';
  END IF;
  IF p_valor <= 0 THEN RAISE EXCEPTION 'Valor deve ser positivo'; END IF;
  IF NOT EXISTS (SELECT 1 FROM fin_contas WHERE id = p_conta_origem AND company_id = v_company) THEN RAISE EXCEPTION 'Conta origem não encontrada'; END IF;
  IF NOT EXISTS (SELECT 1 FROM fin_contas WHERE id = p_conta_destino AND company_id = v_company) THEN RAISE EXCEPTION 'Conta destino não encontrada'; END IF;
  INSERT INTO fin_lancamentos (tipo, valor, data_competencia, descricao, conta_id, conta_destino_id, status, created_by, company_id)
  VALUES ('TRANSFERENCIA', p_valor, p_data, COALESCE(p_descricao,'Transferência'), p_conta_origem, p_conta_destino, 'REALIZADO', COALESCE(p_created_by, auth.uid()), v_company)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id);
END; $function$

CREATE OR REPLACE FUNCTION public.debug_tenant()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_uid uuid;
  v_company uuid;
  v_email text;
  v_profile_company uuid;
BEGIN
  v_uid := auth.uid();

  SELECT p.email, p.company_id
    INTO v_email, v_profile_company
    FROM public.profiles p
   WHERE p.id = v_uid;

  BEGIN
    v_company := get_current_company_id();
  EXCEPTION WHEN OTHERS THEN
    v_company := null;
  END;

  RETURN jsonb_build_object(
    'auth_uid', v_uid,
    'get_current_company_id', v_company,
    'profile_email', v_email,
    'profile_company_id', v_profile_company
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_transfer(p_lancamento_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_target public.fin_lancamentos%ROWTYPE;
  v_parent_id uuid;
  v_child_id uuid;
  v_before jsonb;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:lancamentos:delete', 'finance:manage', 'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:lancamentos:delete necessário';
  END IF;

  SELECT l.* INTO v_target
  FROM public.fin_lancamentos l
  WHERE l.id = p_lancamento_id
    AND l.company_id = v_company
    AND l.tipo = 'TRANSFERENCIA';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: transferência';
  END IF;

  v_parent_id := COALESCE(v_target.lancamento_pai_id, v_target.id);
  SELECT l.id INTO v_child_id
  FROM public.fin_lancamentos l
  WHERE l.lancamento_pai_id = v_parent_id
    AND l.company_id = v_company
    AND l.tipo = 'TRANSFERENCIA'
  LIMIT 1;

  v_before := jsonb_build_object(
    'lancamento_id', v_target.id,
    'legacy_child_id', v_child_id,
    'valor', v_target.valor,
    'conta_origem_id', v_target.conta_id,
    'conta_destino_id', v_target.conta_destino_id
  );

  IF v_child_id IS NOT NULL THEN
    DELETE FROM public.fin_lancamentos
    WHERE id = v_child_id AND company_id = v_company;
    DELETE FROM public.fin_lancamentos
    WHERE id = v_parent_id AND company_id = v_company;
  ELSE
    DELETE FROM public.fin_lancamentos
    WHERE id = v_target.id AND company_id = v_company;
  END IF;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, user_id, company_id, antes
  )
  VALUES ('transferencia', v_target.id, 'excluir', v_uid, v_company, v_before);

  RETURN jsonb_build_object(
    'ok', true,
    'lancamento_id', v_target.id,
    'legacy_child_id', v_child_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_salmon_raw_product()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_sku text;
  v_company_id uuid;
BEGIN
  -- Enforcement
  v_company_id := assert_tenant();

  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;

  -- 1. Look for existing linked product within company context
  SELECT id INTO v_id FROM produtos 
  WHERE is_salmon_raw_linked = true 
    AND ativo = true 
    AND company_id = v_company_id 
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  -- 2. Generate SKU (will use get_current_company_id fallback which is now dynamic)
  SELECT generate_next_sku('SALM') INTO v_sku;

  -- 3. Create product if missing for this company
  INSERT INTO produtos (
    nome_produto, sku, categoria, unidade_medida, unidade_compra,
    fator_conversao_padrao, custo_padrao, default_cost_purchase_unit, default_cost_base_unit,
    estoque_minimo, estoque_ideal, ativo, is_salmon_raw_linked, observacoes, company_id
  ) VALUES (
    'Salmão Fresco', v_sku, 'Pescados', 'KG', 'KG',
    1, 0, 0, 0,
    0, 0, true, true, 'Item vinculado automaticamente ao Controle de Salmão. Não editar unidades.',
    v_company_id
  )
  RETURNING id INTO v_id;

  -- 4. Audit with correct metadata
  PERFORM public.log_audit('rpc', 'salmon', 'produtos', v_id, 'ENSURE_RAW_PRODUCT', NULL,
    jsonb_build_object('sku', v_sku, 'created', true, 'company_id', v_company_id));

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.ficha_salvar_componente_itens_atomic(_componente_pai_id uuid, _itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_parent_tipo text;
  v_child_tipo text;
  v_item jsonb;
  v_idx int := 0;
  v_custo_total numeric := 0;
  v_custo_unitario numeric := 0;
  v_rendimento numeric;
  v_perda numeric;
  v_rendimento_liq numeric;
  v_custo_indireto numeric;
BEGIN
  -- 1. Assert tenant (fail-closed)
  v_company_id := assert_tenant();

  -- 2. Lock parent component (prevent concurrent edits)
  SELECT tipo, rendimento, perda_estimada_percent, custo_indireto
  INTO v_parent_tipo, v_rendimento, v_perda, v_custo_indireto
  FROM ficha_componentes
  WHERE id = _componente_pai_id
    AND company_id = v_company_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_parent_tipo IS NULL THEN
    RAISE EXCEPTION 'Componente pai não encontrado ou não pertence ao tenant';
  END IF;

  -- 3. Validate hierarchy for each child component
  FOR v_item IN SELECT * FROM jsonb_array_elements(_itens)
  LOOP
    IF v_item->>'componente_filho_id' IS NOT NULL AND v_item->>'componente_filho_id' != '' THEN
      SELECT tipo INTO v_child_tipo
      FROM ficha_componentes
      WHERE id = (v_item->>'componente_filho_id')::uuid
        AND company_id = v_company_id
        AND deleted_at IS NULL;

      IF v_child_tipo IS NULL THEN
        RAISE EXCEPTION 'Componente filho % não encontrado no tenant', v_item->>'componente_filho_id';
      END IF;

      IF v_parent_tipo = 'PRE_PREPARO' AND v_child_tipo != 'PRE_PREPARO' THEN
        RAISE EXCEPTION 'Pré-Preparo só aceita insumos e outros pré-preparos. "%" não permitido.', v_child_tipo;
      END IF;
      IF v_parent_tipo = 'ITEM_PRONTO' AND v_child_tipo != 'PRE_PREPARO' THEN
        RAISE EXCEPTION 'Item Pronto só aceita insumos, pré-preparos e salmão. "%" não permitido.', v_child_tipo;
      END IF;
      IF v_parent_tipo = 'PRODUTO_FINAL' AND v_child_tipo != 'ITEM_PRONTO' THEN
        RAISE EXCEPTION 'Produto Final só aceita itens prontos e insumos. "%" não permitido.', v_child_tipo;
      END IF;
    END IF;

    -- Block PRODUTO_FINAL from using salmon directly
    IF v_parent_tipo = 'PRODUTO_FINAL' AND (v_item->>'origem') = 'MODULO_SALMAO' THEN
      RAISE EXCEPTION 'Produto Final não pode usar salmão diretamente.';
    END IF;
  END LOOP;

  -- 4. Delete existing items (within tenant scope)
  DELETE FROM ficha_componente_itens
  WHERE componente_pai_id = _componente_pai_id
    AND company_id = v_company_id;

  -- 5. Insert new items (with explicit company_id)
  v_idx := 0;
  FOR v_item IN SELECT * FROM jsonb_array_elements(_itens)
  LOOP
    INSERT INTO ficha_componente_itens (
      componente_pai_id, componente_filho_id, produto_id,
      quantidade, unidade, custo_snapshot, ordem, origem,
      unidade_original, quantidade_original, company_id
    ) VALUES (
      _componente_pai_id,
      NULLIF(v_item->>'componente_filho_id', '')::uuid,
      NULLIF(v_item->>'produto_id', '')::uuid,
      COALESCE((v_item->>'quantidade')::numeric, 0),
      COALESCE(v_item->>'unidade', 'un'),
      COALESCE((v_item->>'custo_snapshot')::numeric, 0),
      v_idx,
      COALESCE(v_item->>'origem', 'ESTOQUE_GERAL'),
      COALESCE(v_item->>'unidade_original', ''),
      COALESCE((v_item->>'quantidade_original')::numeric, 0),
      v_company_id
    );
    v_idx := v_idx + 1;
  END LOOP;

  -- 6. Simple cost recalculation (sum of snapshots + indirect)
  -- Full recursive calc is done by the EF after this returns
  SELECT COALESCE(SUM(quantidade * custo_snapshot), 0)
  INTO v_custo_total
  FROM ficha_componente_itens
  WHERE componente_pai_id = _componente_pai_id
    AND company_id = v_company_id;

  v_custo_total := v_custo_total + COALESCE(v_custo_indireto, 0);
  v_rendimento_liq := COALESCE(v_rendimento, 1) * (1 - COALESCE(v_perda, 0) / 100);
  IF v_rendimento_liq > 0 THEN
    v_custo_unitario := v_custo_total / v_rendimento_liq;
  ELSE
    v_custo_unitario := v_custo_total;
  END IF;

  -- 7. Update parent costs
  UPDATE ficha_componentes
  SET custo_total_calculado = ROUND(v_custo_total, 2),
      custo_unitario_calculado = ROUND(v_custo_unitario, 2),
      updated_at = now()
  WHERE id = _componente_pai_id
    AND company_id = v_company_id;

  RETURN jsonb_build_object(
    'ok', true,
    'custoTotal', ROUND(v_custo_total, 2),
    'custoUnitario', ROUND(v_custo_unitario, 2),
    'itensCount', v_idx
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_block_contamax_ledger_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_descricao text;
BEGIN
  IF NEW.status NOT IN ('REALIZADO', 'CONCILIADO') THEN
    RETURN NEW;
  END IF;

  v_descricao := lower(public.immutable_unaccent(
    regexp_replace(btrim(COALESCE(NEW.descricao, '')), '\s+', ' ', 'g')
  ));
  IF v_descricao NOT LIKE '%aplicacao%contamax%'
     AND v_descricao NOT LIKE '%resgate%contamax%' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.fin_contas c
    WHERE c.company_id = NEW.company_id
      AND c.id IN (NEW.conta_id, NEW.conta_destino_id)
      AND (
        regexp_replace(COALESCE(c.banco, ''), '\D', '', 'g') = '033'
        OR lower(public.immutable_unaccent(btrim(COALESCE(c.banco, '')))) LIKE '%santander%'
      )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'AUTOMATIC_INVESTMENT_IS_INTERNAL: aplicação/resgate ContaMax não cria lançamento financeiro';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_get_categoria_desconto_baixa(p_company_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_id uuid;
  v_raiz uuid;
BEGIN
  SELECT id INTO v_raiz
  FROM public.fin_categorias
  WHERE company_id = p_company_id AND system_key = 'receitas_nao_operacionais'
  LIMIT 1;

  IF v_raiz IS NULL THEN
    INSERT INTO public.fin_categorias (system_key, nome, tipo, codigo, ordem, company_id)
    VALUES ('receitas_nao_operacionais', 'RECEITAS NÃO OPERACIONAIS', 'receita', 'NO-R', 9990, p_company_id)
    RETURNING id INTO v_raiz;
  END IF;

  SELECT id INTO v_id
  FROM public.fin_categorias
  WHERE company_id = p_company_id
    AND parent_id = v_raiz
    AND lower(nome) = 'descontos obtidos'
  ORDER BY ativo DESC, created_at
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE public.fin_categorias
    SET ativo = true
    WHERE id = v_id AND company_id = p_company_id AND ativo = false;
    RETURN v_id;
  END IF;

  INSERT INTO public.fin_categorias
    (nome, tipo, codigo, parent_id, ordem, ativo, company_id)
  VALUES
    ('Descontos Obtidos', 'receita', 'NO-R.90', v_raiz, 9991, true, p_company_id)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

