CREATE OR REPLACE FUNCTION public.fin_prepare_category_reporting_class()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_parent public.fin_categorias%ROWTYPE;
BEGIN
  IF NEW.system_key IS NOT NULL THEN
    IF NEW.system_key = 'receitas_nao_operacionais' THEN
      NEW.nome := 'RECEITAS NÃO OPERACIONAIS';
      NEW.codigo := 'NO-R';
      NEW.tipo := 'receita';
    ELSIF NEW.system_key = 'despesas_nao_operacionais' THEN
      NEW.nome := 'DESPESAS NÃO OPERACIONAIS';
      NEW.codigo := 'NO-D';
      NEW.tipo := 'despesa';
    ELSE
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'SYSTEM_CATEGORY_INVALID';
    END IF;
    NEW.parent_id := NULL;
    NEW.ativo := true;
    NEW.excluir_dos_totais := true;
    RETURN NEW;
  END IF;

  IF NEW.parent_id IS NULL THEN
    NEW.excluir_dos_totais := false;
    RETURN NEW;
  END IF;

  SELECT * INTO v_parent
  FROM public.fin_categorias
  WHERE id = NEW.parent_id AND company_id = NEW.company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'CATEGORY_PARENT_INVALID';
  END IF;
  NEW.excluir_dos_totais := v_parent.excluir_dos_totais;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_preserve_materialized_recurrence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.recorrente
     AND COALESCE((OLD.recorrencia_config->>'materializada')::boolean, false)
     AND NEW.recorrente THEN
    IF lower(NEW.recorrencia_config->>'frequencia') IS DISTINCT FROM lower(OLD.recorrencia_config->>'frequencia')
       OR (NEW.recorrencia_config->>'parcelas')::integer IS DISTINCT FROM (OLD.recorrencia_config->>'parcelas')::integer THEN
      RAISE EXCEPTION 'RECORRENCIA_SERIE_IMUTAVEL: desative esta recorrência e crie uma nova série'
        USING ERRCODE = '22023';
    END IF;
    NEW.recorrencia_config := OLD.recorrencia_config;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_recompute_entity_report_exclusion(p_entity_id uuid, p_company_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_min boolean;
  v_max boolean;
  v_excluded boolean;
BEGIN
  SELECT min(c.excluir_dos_totais::int) = 1,
         max(c.excluir_dos_totais::int) = 1
  INTO v_min, v_max
  FROM public.fin_lancamento_rateios r
  JOIN public.fin_categorias c
    ON c.id = r.categoria_id AND c.company_id = p_company_id
  WHERE r.lancamento_id = p_entity_id AND r.company_id = p_company_id;

  IF v_min IS DISTINCT FROM v_max THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'RATEIO_MIXED_REPORTING_CLASS';
  END IF;

  IF v_min IS NOT NULL THEN
    v_excluded := v_min;
  ELSE
    SELECT public.fin_category_is_excluded(x.categoria_id, p_company_id)
    INTO v_excluded
    FROM (
      SELECT categoria_id FROM public.fin_lancamentos WHERE id = p_entity_id AND company_id = p_company_id
      UNION ALL
      SELECT categoria_id FROM public.fin_contas_pagar WHERE id = p_entity_id AND company_id = p_company_id
      UNION ALL
      SELECT categoria_id FROM public.fin_contas_receber WHERE id = p_entity_id AND company_id = p_company_id
      LIMIT 1
    ) x;
  END IF;
  v_excluded := COALESCE(v_excluded, false);

  UPDATE public.fin_lancamentos
  SET excluir_dos_relatorios = v_excluded
  WHERE id = p_entity_id AND company_id = p_company_id
    AND excluir_dos_relatorios IS DISTINCT FROM v_excluded;
  UPDATE public.fin_contas_pagar
  SET excluir_dos_relatorios = v_excluded
  WHERE id = p_entity_id AND company_id = p_company_id
    AND excluir_dos_relatorios IS DISTINCT FROM v_excluded;
  UPDATE public.fin_contas_receber
  SET excluir_dos_relatorios = v_excluded
  WHERE id = p_entity_id AND company_id = p_company_id
    AND excluir_dos_relatorios IS DISTINCT FROM v_excluded;
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_recorrencia_config_valida(p_config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_frequency text;
  v_count_text text;
  v_count integer;
  v_limit integer;
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RETURN false;
  END IF;

  v_frequency := lower(btrim(p_config->>'frequencia'));
  v_count_text := btrim(p_config->>'parcelas');

  v_limit := CASE v_frequency
    WHEN 'mensal' THEN 36
    WHEN 'semanal' THEN 144
    WHEN 'quinzenal' THEN 72
    ELSE NULL
  END;

  IF v_limit IS NULL
     OR v_count_text IS NULL
     OR v_count_text !~ '^[0-9]+$'
     OR length(v_count_text) > 3 THEN
    RETURN false;
  END IF;

  v_count := v_count_text::integer;
  RETURN v_count BETWEEN 2 AND v_limit;
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_set_limite_aprovacao(p_valor numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:pagar:approve', 'finance:manage', 'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:pagar:approve necessário';
  END IF;

  IF p_valor IS NULL OR p_valor < 0 THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: limite deve ser zero ou positivo';
  END IF;

  INSERT INTO public.fin_config (company_id, key, value, updated_by)
  VALUES (v_company, 'limite_aprovacao_contas_pagar', p_valor::text, v_uid)
  ON CONFLICT (company_id, key)
  DO UPDATE SET value = EXCLUDED.value, updated_at = now(), updated_by = EXCLUDED.updated_by;

  INSERT INTO public.fin_audit_logs (entidade, acao, user_id, company_id, depois)
  VALUES ('config', 'limite_aprovacao', v_uid, v_company,
    jsonb_build_object('limite_aprovacao_contas_pagar', p_valor));

  RETURN jsonb_build_object('status', 'ok', 'valor', p_valor);
END;
$function$

CREATE OR REPLACE FUNCTION public.fin_validate_recorrencia_config(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_frequency text;
  v_count_text text;
  v_count integer;
  v_limit integer;
BEGIN
  IF p_config IS NULL THEN
    RETURN NULL;
  END IF;

  IF jsonb_typeof(p_config) <> 'object' THEN
    RAISE EXCEPTION 'RECORRENCIA_CONFIG_INVALIDA: informe frequência e quantidade'
      USING ERRCODE = '22023';
  END IF;

  v_frequency := lower(btrim(p_config->>'frequencia'));
  v_limit := CASE v_frequency
    WHEN 'mensal' THEN 36
    WHEN 'semanal' THEN 144
    WHEN 'quinzenal' THEN 72
    ELSE NULL
  END;

  IF v_limit IS NULL THEN
    RAISE EXCEPTION 'RECORRENCIA_FREQUENCIA_INVALIDA: use mensal, semanal ou quinzenal'
      USING ERRCODE = '22023';
  END IF;

  v_count_text := btrim(p_config->>'parcelas');
  IF v_count_text IS NULL
     OR v_count_text !~ '^[0-9]+$'
     OR length(v_count_text) > 3 THEN
    RAISE EXCEPTION 'RECORRENCIA_QUANTIDADE_INVALIDA: informe uma quantidade inteira'
      USING ERRCODE = '22023';
  END IF;

  v_count := v_count_text::integer;
  IF v_count < 2 THEN
    RAISE EXCEPTION 'RECORRENCIA_QUANTIDADE_INVALIDA: informe pelo menos 2 lançamentos'
      USING ERRCODE = '22023';
  END IF;
  IF v_count > v_limit THEN
    RAISE EXCEPTION 'RECORRENCIA_LIMITE_EXCEDIDO: % permite no máximo % lançamentos',
      initcap(v_frequency), v_limit
      USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'frequencia', v_frequency,
    'parcelas', v_count,
    'parcelas_geradas', v_count,
    'materializada', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_inventory_atomic(p_id uuid, p_justificativa text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_user_id uuid; v_inv record; v_item record;
  v_before jsonb; v_after jsonb; v_adjustments_inserted int := 0;
  v_diff numeric; v_fisica numeric; v_teorico numeric;
  v_drift_total numeric := 0; v_valor_total_estoque numeric := 0;
  v_acuracia numeric; v_user_role text;
  v_total_itens int; v_total_contados int;
BEGIN
  v_tenant := assert_tenant(); v_user_id := auth.uid();

  IF length(COALESCE(p_justificativa, '')) < 10 THEN RAISE EXCEPTION 'Justificativa deve ter no mínimo 10 caracteres.'; END IF;
  IF NOT has_any_permission(v_user_id, ARRAY['inventario:detalhe:close', 'system:global:manage']) THEN RAISE EXCEPTION 'Forbidden: inventario:detalhe:close required'; END IF;

  SELECT * INTO v_inv FROM inventarios WHERE id = p_id AND company_id = v_tenant AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inventário não encontrado ou pertence a outro tenant.'; END IF;

  IF v_inv.status = 'FINALIZADO' THEN
    RETURN jsonb_build_object('success', true, 'already_finalized', true, 'adjustments_inserted', 0, 'status', 'FINALIZADO');
  END IF;
  IF v_inv.status = 'SOB_ANALISE' THEN RAISE EXCEPTION 'Inventário sob análise — use aprovar_analise primeiro.'; END IF;
  IF v_inv.status NOT IN ('EM_CONTAGEM', 'EM_REVISAO') THEN RAISE EXCEPTION 'Status atual (%) não permite fechamento.', v_inv.status; END IF;

  -- Count totals for coverage tracking
  SELECT count(*), count(*) FILTER (WHERE contagem_fisica IS NOT NULL)
    INTO v_total_itens, v_total_contados
    FROM inventario_itens WHERE inventario_id = p_id AND deleted_at IS NULL;

  v_before := jsonb_build_object('status', v_inv.status, 'item_count', v_total_itens, 'counted', v_total_contados);

  -- Process ONLY counted items (uncounted items keep current stock)
  FOR v_item IN SELECT id, produto_id, contagem_fisica, saldo_teorico, custo_snapshot, diferenca_qtd, impacto_financeiro
    FROM inventario_itens WHERE inventario_id = p_id AND deleted_at IS NULL AND contagem_fisica IS NOT NULL FOR UPDATE
  LOOP
    v_fisica := COALESCE(v_item.contagem_fisica, 0);
    v_teorico := COALESCE(v_item.saldo_teorico, 0);
    v_diff := v_fisica - v_teorico;
    v_valor_total_estoque := v_valor_total_estoque + abs(v_teorico * COALESCE(v_item.custo_snapshot, 0));
    v_drift_total := v_drift_total + COALESCE(v_item.impacto_financeiro, 0);

    IF v_diff > 0 THEN
      INSERT INTO movimentacoes_estoque (company_id, produto_id, tipo, direction, quantidade, custo_unitario, custo_total, origem, referencia_id, data, observacao, reference_type, reference_id, created_by, status)
      VALUES (v_tenant, v_item.produto_id, 'AJUSTE_INVENTARIO_POSITIVO', 'IN', v_diff, COALESCE(v_item.custo_snapshot, 0), v_diff * COALESCE(v_item.custo_snapshot, 0), 'INVENTARIO', p_id::text, v_inv.data, 'Ajuste inventário #' || left(p_id::text, 8) || ' item=' || left(v_item.id::text, 8), 'INVENTARIO_AJUSTE', p_id::text, v_user_id, 'ATIVO')
      ON CONFLICT (reference_type, reference_id, produto_id, tipo) WHERE reference_type = 'INVENTARIO_AJUSTE' AND status = 'ATIVO' DO NOTHING;
      IF FOUND THEN v_adjustments_inserted := v_adjustments_inserted + 1; END IF;
    ELSIF v_diff < 0 THEN
      INSERT INTO movimentacoes_estoque (company_id, produto_id, tipo, direction, quantidade, custo_unitario, custo_total, origem, referencia_id, data, observacao, reference_type, reference_id, created_by, status)
      VALUES (v_tenant, v_item.produto_id, 'AJUSTE_INVENTARIO_NEGATIVO', 'OUT', abs(v_diff), COALESCE(v_item.custo_snapshot, 0), abs(v_diff) * COALESCE(v_item.custo_snapshot, 0), 'INVENTARIO', p_id::text, v_inv.data, 'Ajuste inventário #' || left(p_id::text, 8) || ' item=' || left(v_item.id::text, 8), 'INVENTARIO_AJUSTE', p_id::text, v_user_id, 'ATIVO')
      ON CONFLICT (reference_type, reference_id, produto_id, tipo) WHERE reference_type = 'INVENTARIO_AJUSTE' AND status = 'ATIVO' DO NOTHING;
      IF FOUND THEN v_adjustments_inserted := v_adjustments_inserted + 1; END IF;
    END IF;
  END LOOP;

  v_acuracia := CASE WHEN v_valor_total_estoque > 0 THEN GREATEST(0, (1 - abs(v_drift_total) / v_valor_total_estoque) * 100) ELSE 100 END;

  UPDATE inventarios SET status = 'FINALIZADO', finalizado_em = now(), finalizado_por = v_user_id, acuracia_percent = v_acuracia, drift_total_valor = v_drift_total, updated_at = now()
  WHERE id = p_id AND company_id = v_tenant;

  v_after := jsonb_build_object('status', 'FINALIZADO', 'adjustments_inserted', v_adjustments_inserted, 'acuracia', round(v_acuracia, 2), 'drift_total', round(v_drift_total, 2), 'justificativa', p_justificativa, 'total_itens', v_total_itens, 'total_contados', v_total_contados);
  v_user_role := COALESCE((SELECT string_agg(role::text, ',') FROM user_roles WHERE user_id = v_user_id AND company_id = public.assert_tenant()), 'unknown');

  INSERT INTO audit_inventario_log (company_id, inventario_id, user_id, user_role, acao, antes, depois, ip_address)
  VALUES (v_tenant, p_id, v_user_id, v_user_role, 'FINALIZACAO', v_before, v_after, '');

  RETURN jsonb_build_object(
    'success', true,
    'adjustments_inserted', v_adjustments_inserted,
    'acuracia', round(v_acuracia, 2),
    'drift_total', round(v_drift_total, 2),
    'status', 'FINALIZADO',
    'total_itens', v_total_itens,
    'total_contados', v_total_contados
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_update_product_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_produto_id uuid;
  v_company_id uuid;
BEGIN
  -- Identificar o produto e a empresa afetados
  IF (TG_OP = 'DELETE') THEN
    v_produto_id := OLD.produto_id;
    v_company_id := OLD.company_id;
  ELSE
    v_produto_id := NEW.produto_id;
    v_company_id := NEW.company_id;
  END IF;

  -- Reutilizar a função de recomputação para garantir consistência
  PERFORM public.fn_recompute_product_saldo(v_produto_id, v_company_id);

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_next_sku(p_prefix text DEFAULT 'MP'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_next bigint;
  v_pad integer;
  v_candidate text;
  v_attempts integer := 0;
  v_max_attempts integer := 1000;
BEGIN
  v_company_id := public.get_current_company_id();

  INSERT INTO public.stock_sku_counter (company_id, prefix, next_value, pad_length, updated_at)
  VALUES (v_company_id, p_prefix, 0, 4, now())
  ON CONFLICT (company_id, prefix) DO NOTHING;

  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > v_max_attempts THEN
      RAISE EXCEPTION
        'generate_next_sku: nao foi possivel gerar SKU unico apos % tentativas (company=%, prefix=%)',
        v_max_attempts, v_company_id, p_prefix;
    END IF;

    UPDATE public.stock_sku_counter
       SET next_value = next_value + 1,
           updated_at = now()
     WHERE company_id = v_company_id
       AND prefix = p_prefix
    RETURNING next_value, pad_length INTO v_next, v_pad;

    v_candidate := p_prefix || '-' || lpad(v_next::text, GREATEST(COALESCE(v_pad, 4), 1), '0');

    IF NOT EXISTS (
      SELECT 1
      FROM public.produtos
      WHERE company_id = v_company_id
        AND sku = v_candidate
    ) THEN
      RETURN v_candidate;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_requisition_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count INTEGER;
  v_year TEXT;
BEGIN
  v_year := to_char(now(), 'YYYY');
  SELECT COUNT(*) + 1 INTO v_count FROM purchase_requisitions WHERE codigo LIKE 'REQ-' || v_year || '-%';
  NEW.codigo := 'REQ-' || v_year || '-' || lpad(v_count::text, 4, '0');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.gerar_parcela_recorrente(p_lancamento_pai_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_company_id uuid;
  v_pai record;
  v_config jsonb;
  v_freq text;
  v_max_parcelas int;
  v_geradas int;
  v_num int;
  v_nova_data date;
  v_base_date date;
  v_new_id uuid;
BEGIN
  -- Auth + tenant
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  v_company_id := assert_tenant();

  -- Permission check
  IF NOT has_any_permission(v_user_id, ARRAY['financeiro:lancamentos:create', 'system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:lancamentos:create necessário';
  END IF;

  -- Lock parent row to prevent concurrent generation
  SELECT * INTO v_pai
  FROM fin_lancamentos
  WHERE id = p_lancamento_pai_id
    AND company_id = v_company_id
    AND recorrente = true
    AND lancamento_pai_id IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: Lançamento pai não encontrado ou não é recorrente';
  END IF;

  v_config := COALESCE(v_pai.recorrencia_config, '{}'::jsonb);
  v_freq := COALESCE(v_config->>'frequencia', 'mensal');
  v_max_parcelas := COALESCE((v_config->>'parcelas')::int, 0);
  v_geradas := COALESCE((v_config->>'parcelas_geradas')::int, 0);

  -- Check if all parcels already generated
  IF v_max_parcelas > 0 AND v_geradas >= v_max_parcelas THEN
    RETURN jsonb_build_object('status', 'noop', 'message', 'Todas as parcelas já foram geradas');
  END IF;

  v_num := v_geradas + 1;
  v_base_date := v_pai.data_competencia;

  -- Calculate new date
  IF v_freq = 'mensal' THEN
    v_nova_data := v_base_date + (v_num || ' months')::interval;
  ELSIF v_freq = 'semanal' THEN
    v_nova_data := v_base_date + (v_num * 7 || ' days')::interval;
  ELSIF v_freq = 'quinzenal' THEN
    v_nova_data := v_base_date + (v_num * 15 || ' days')::interval;
  ELSE
    v_nova_data := v_base_date + (v_num || ' months')::interval;
  END IF;

  -- Idempotency key to prevent duplicates
  INSERT INTO fin_lancamentos (
    descricao, tipo, valor, categoria_id, centro_custo_id, conta_id,
    forma_pagamento, recorrente, lancamento_pai_id, parcela_atual,
    parcela_total, data_competencia, status, created_by, company_id,
    idempotency_key
  )
  VALUES (
    CASE WHEN v_max_parcelas > 0
      THEN v_pai.descricao || ' (' || v_num || '/' || v_max_parcelas || ')'
      ELSE v_pai.descricao || ' (parcela ' || v_num || ')'
    END,
    v_pai.tipo, v_pai.valor, v_pai.categoria_id, v_pai.centro_custo_id,
    v_pai.conta_id, v_pai.forma_pagamento, false, v_pai.id,
    v_num, CASE WHEN v_max_parcelas > 0 THEN v_max_parcelas ELSE NULL END,
    v_nova_data, 'PREVISTO', v_user_id, v_company_id,
    'recorrencia:' || v_pai.id || ':' || v_num
  )
  ON CONFLICT (company_id, idempotency_key) WHERE idempotency_key IS NOT NULL
  DO NOTHING
  RETURNING id INTO v_new_id;

  -- If insert was a noop (duplicate), return early
  IF v_new_id IS NULL THEN
    RETURN jsonb_build_object('status', 'noop', 'message', 'Parcela já existia (idempotente)');
  END IF;

  -- Update parent config atomically
  UPDATE fin_lancamentos
  SET recorrencia_config = jsonb_set(
    COALESCE(recorrencia_config, '{}'::jsonb),
    '{parcelas_geradas}',
    to_jsonb(v_num)
  )
  WHERE id = v_pai.id AND company_id = v_company_id;

  -- Audit
  INSERT INTO fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
  VALUES ('lancamentos', v_new_id, 'gerar_parcela', v_user_id, v_company_id,
    jsonb_build_object('pai_id', v_pai.id, 'parcela_num', v_num, 'data', v_nova_data));

  RETURN jsonb_build_object('status', 'ok', 'parcela_id', v_new_id, 'parcela_num', v_num);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_catalog_counts()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_total int;
  v_active int;
  v_inactive int;
BEGIN
  -- Obter a empresa do contexto do usuário atual com segurança
  v_company_id := public.assert_tenant();

  IF v_company_id IS NULL THEN
    RETURN json_build_object('total', 0, 'active', 0, 'inactive', 0);
  END IF;

  -- Realizar as contagens em uma única passagem ou de forma otimizada
  SELECT count(*) INTO v_total FROM public.produtos WHERE company_id = v_company_id;
  SELECT count(*) INTO v_active FROM public.produtos WHERE company_id = v_company_id AND ativo = true;
  SELECT count(*) INTO v_inactive FROM public.produtos WHERE company_id = v_company_id AND ativo = false;

  RETURN json_build_object(
    'total', v_total,
    'active', v_active,
    'inactive', v_inactive
  );
END;
$function$

