CREATE OR REPLACE FUNCTION public.get_current_company_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user uuid := auth.uid(); v_company uuid; v_requested text;
BEGIN
 IF v_user IS NULL THEN RETURN NULL; END IF;
 v_requested := NULLIF(current_setting('request.headers',true),'')::jsonb->>'x-company-id';
 IF v_requested IS NOT NULL THEN
   BEGIN v_company := v_requested::uuid;
   EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='COMPANY_ACCESS_DENIED'; END;
 ELSE
   SELECT company_id INTO v_company FROM public.profiles WHERE id=v_user;
 END IF;
 IF NOT public.is_company_member(v_user,v_company) THEN
   IF v_requested IS NULL THEN RETURN NULL; END IF;
   RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='COMPANY_ACCESS_DENIED';
 END IF;
 RETURN v_company;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_effective_permissions(_user_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_company uuid; v_requested text;
BEGIN
 IF auth.uid() IS NOT NULL THEN v_company:=public.get_current_company_id();
 ELSIF (NULLIF(current_setting('request.jwt.claims',true),'')::jsonb->>'role')='service_role' THEN
   v_requested:=NULLIF(current_setting('request.headers',true),'')::jsonb->>'x-company-id';
   IF v_requested IS NOT NULL THEN v_company:=v_requested::uuid;
   ELSE SELECT company_id INTO v_company FROM public.profiles WHERE id=_user_id; END IF;
 ELSE RETURN ARRAY[]::text[];
 END IF;
 RETURN public.get_company_permissions(_user_id,v_company);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_fin_bordero(p_inicio date, p_fim date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
BEGIN
  v_company_id := public.assert_tenant();

  -- A tela Borderô é gateada pela mesma chave do antigo Relatório Sócios.
  IF NOT public.has_any_permission(auth.uid(), ARRAY[
    'financeiro:relatorio-socios:view',
    'finance:read',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'PERMISSION_DENIED: financeiro:relatorio-socios:view';
  END IF;

  IF p_inicio IS NULL OR p_fim IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'BORDERO_PERIODO_OBRIGATORIO';
  END IF;
  IF p_fim < p_inicio THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'BORDERO_PERIODO_INVALIDO';
  END IF;
  IF p_fim - p_inicio > 366 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'BORDERO_PERIODO_LONGO';
  END IF;

  RETURN public._fin_bordero_payload(v_company_id, p_inicio, p_fim);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_fin_dashboard_summary(p_start date, p_end date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  _result json;
  v_company uuid;
  v_today date;
  v_receita numeric;
  v_despesa numeric;
  v_a_receber numeric;
  v_a_pagar numeric;
  v_a_pagar_vencido numeric;
  v_a_pagar_vencido_qtd integer;
  v_saldo_caixa numeric;
  v_saldo_inicial_contas numeric;
  v_receita_prev numeric;
  v_despesa_prev numeric;
  v_prev_start date;
BEGIN
  v_company := public.assert_tenant();
  IF NOT public.has_any_permission(auth.uid(), ARRAY['finance:read', 'financeiro:dashboard:view', 'system:global:manage']) THEN
    RAISE EXCEPTION 'Sem permissao (financeiro:dashboard:view)';
  END IF;

  v_today := (now() AT TIME ZONE 'America/Sao_Paulo')::date;

  v_receita := (
    SELECT COALESCE(SUM(valor), 0) FROM public.fin_lancamentos
    WHERE company_id = v_company AND tipo = 'RECEITA'
      AND excluir_dos_relatorios IS NOT TRUE
      AND status IN ('REALIZADO', 'CONCILIADO')
      AND NOT (origem = 'conciliacao' AND conciliado IS NOT TRUE)
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) >= p_start
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) < p_end
  );

  v_despesa := (
    SELECT COALESCE(SUM(valor), 0) FROM public.fin_lancamentos
    WHERE company_id = v_company AND tipo = 'DESPESA'
      AND excluir_dos_relatorios IS NOT TRUE
      AND status IN ('REALIZADO', 'CONCILIADO')
      AND NOT (origem = 'conciliacao' AND conciliado IS NOT TRUE)
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) >= p_start
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) < p_end
  );

  SELECT COALESCE(SUM(valor), 0) INTO v_a_receber
  FROM public.fin_contas_receber
  WHERE company_id = v_company
    AND status NOT IN ('RECEBIDO', 'CANCELADO')
    AND data_vencimento >= p_start
    AND data_vencimento < p_end;

  SELECT COALESCE(SUM(valor), 0) INTO v_a_pagar
  FROM public.fin_contas_pagar
  WHERE company_id = v_company
    AND status NOT IN ('PAGO', 'CANCELADO')
    AND data_vencimento >= p_start
    AND data_vencimento < p_end;

  SELECT COALESCE(SUM(valor), 0), COUNT(*)::int INTO v_a_pagar_vencido, v_a_pagar_vencido_qtd
  FROM public.fin_contas_pagar
  WHERE company_id = v_company
    AND status IN ('APROVADO', 'AGUARDANDO_APROVACAO')
    AND data_vencimento < v_today;

  SELECT COALESCE(SUM(saldo_inicial), 0) INTO v_saldo_inicial_contas
  FROM public.fin_contas
  WHERE company_id = v_company AND ativo = true;

  SELECT v_saldo_inicial_contas + COALESCE(SUM(
    CASE WHEN tipo = 'RECEITA' THEN valor
         WHEN tipo = 'DESPESA' THEN -valor
         ELSE 0 END
  ), 0) INTO v_saldo_caixa
  FROM public.fin_lancamentos
  WHERE company_id = v_company
    AND status IN ('REALIZADO', 'CONCILIADO')
    AND tipo != 'TRANSFERENCIA'
    AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) < p_end;

  v_prev_start := p_start - (p_end - p_start);

  v_receita_prev := (
    SELECT COALESCE(SUM(valor), 0) FROM public.fin_lancamentos
    WHERE company_id = v_company AND tipo = 'RECEITA'
      AND excluir_dos_relatorios IS NOT TRUE
      AND status IN ('REALIZADO', 'CONCILIADO')
      AND NOT (origem = 'conciliacao' AND conciliado IS NOT TRUE)
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) >= v_prev_start
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) < p_start
  );

  v_despesa_prev := (
    SELECT COALESCE(SUM(valor), 0) FROM public.fin_lancamentos
    WHERE company_id = v_company AND tipo = 'DESPESA'
      AND excluir_dos_relatorios IS NOT TRUE
      AND status IN ('REALIZADO', 'CONCILIADO')
      AND NOT (origem = 'conciliacao' AND conciliado IS NOT TRUE)
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) >= v_prev_start
      AND COALESCE(data_pagamento, conciliado_em::date, data_competencia) < p_start
  );

  _result := json_build_object(
    'receita', v_receita,
    'despesa', v_despesa,
    'resultado', v_receita - v_despesa,
    'a_receber', v_a_receber,
    'a_pagar', v_a_pagar,
    'a_pagar_vencido', v_a_pagar_vencido,
    'a_pagar_vencido_qtd', v_a_pagar_vencido_qtd,
    'saldo_caixa', v_saldo_caixa,
    'receita_prev', v_receita_prev,
    'despesa_prev', v_despesa_prev,
    'resultado_prev', v_receita_prev - v_despesa_prev
  );

  RETURN _result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_fin_presentation_category_metadata()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
