  SELECT COALESCE(SUM(valor_empresa), 0)
    INTO v_total_beneficios
    FROM public.rh_beneficios
   WHERE company_id = v_company
     AND status     = 'ATIVO';

  RETURN jsonb_build_object('total_beneficios', v_total_beneficios);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_saldo_conta(p_conta_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_saldo numeric; v_company uuid;
BEGIN
  v_company := assert_tenant();
  IF NOT EXISTS (SELECT 1 FROM fin_contas WHERE id = p_conta_id AND company_id = v_company) THEN RAISE EXCEPTION 'Conta não encontrada'; END IF;
  SELECT COALESCE(saldo_inicial, 0) INTO v_saldo FROM fin_contas WHERE id = p_conta_id;
  v_saldo := v_saldo + COALESCE((
    SELECT SUM(CASE
      WHEN tipo = 'TRANSFERENCIA' AND conta_id = p_conta_id THEN -valor
      WHEN tipo = 'TRANSFERENCIA' AND conta_destino_id = p_conta_id THEN valor
      WHEN tipo = 'RECEITA' AND conta_id = p_conta_id THEN valor
      WHEN tipo = 'DESPESA' AND conta_id = p_conta_id THEN -valor ELSE 0 END)
    FROM fin_lancamentos WHERE status = 'REALIZADO' AND company_id = v_company
      AND (conta_id = p_conta_id OR conta_destino_id = p_conta_id)
  ), 0);
  RETURN ROUND(v_saldo, 2);
END; $function$

CREATE OR REPLACE FUNCTION public.get_saldo_produto(p_produto_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_saldo numeric; v_company uuid;
BEGIN
  v_company := assert_tenant();
  SELECT COALESCE(SUM(CASE WHEN tipo IN ('ENTRADA_ESTORNO','SAIDA_ESTORNO') THEN 0 WHEN direction = 'IN' THEN quantidade ELSE -quantidade END), 0) INTO v_saldo
  FROM movimentacoes_estoque WHERE produto_id = p_produto_id AND status = 'ATIVO' AND company_id = v_company;
  RETURN ROUND(v_saldo, 4);
END; $function$

CREATE OR REPLACE FUNCTION public.get_salmon_dashboard_summary(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_company uuid;
  v_entries_count int;
  v_total_entries_kg numeric;
  v_total_value numeric;
  v_avg_cost_per_kg numeric;
  v_manipulation_count int;
  v_total_manipulated_kg numeric;
  v_total_clean_kg numeric;
  v_total_waste_kg numeric;
  v_avg_yield_percent numeric;
  v_avg_loss_percent numeric;
  v_saldo_bruto_kg numeric;
  v_estoque_limpo_kg numeric;
  v_consumido_kg numeric;
  v_min_gross_kg numeric;
  v_min_clean_kg numeric;
  v_faturamento numeric;
  v_cmv_salmon_cost numeric;
  v_cmv_salmon_percent numeric;
  v_custo_medio_kg_limpo numeric;
  v_fifo jsonb;
  v_lotes_parados jsonb;
  v_avg_daily_consumption numeric;
  v_days_remaining numeric;
  v_perda_valor numeric;
BEGIN
  v_company := public.assert_tenant();

  IF NOT public.has_any_permission(auth.uid(), ARRAY[
    'salmon:dashboard:view','salmon:dashboard:read','salmon:read','system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'Sem permissão (salmon:dashboard:view/read ou salmon:read).';
  END IF;

  -- 1. Entries in period
  SELECT COUNT(*), COALESCE(SUM(gross_kg),0), COALESCE(SUM(total_value),0),
         COALESCE(AVG(CASE WHEN unit_cost>0 THEN unit_cost END),0)
  INTO v_entries_count, v_total_entries_kg, v_total_value, v_avg_cost_per_kg
  FROM salmon_entries
  WHERE company_id=v_company AND status='ACTIVE' AND entry_date BETWEEN p_start AND p_end;

  -- 2. Manipulations in period
  SELECT COUNT(*), COALESCE(SUM(gross_out_kg),0), COALESCE(SUM(clean_in_kg),0),
         COALESCE(SUM(waste_kg),0), COALESCE(AVG(yield_percent),0), COALESCE(AVG(loss_percent),0)
  INTO v_manipulation_count, v_total_manipulated_kg, v_total_clean_kg, v_total_waste_kg,
       v_avg_yield_percent, v_avg_loss_percent
  FROM salmon_manipulations
  WHERE company_id=v_company AND status='ACTIVE' AND manipulation_date BETWEEN p_start AND p_end;

  -- 3. Saldo bruto (all-time ledger)
  SELECT COALESCE(SUM(CASE
    WHEN tipo IN ('ENTRADA_ESTORNO','SAIDA_ESTORNO') THEN 0
    WHEN direction='IN' THEN quantidade ELSE -quantidade END),0)
  INTO v_saldo_bruto_kg
  FROM movimentacoes_estoque
  WHERE company_id=v_company AND status='ATIVO' AND source_module='salmon';

  -- 4. Estoque limpo (all-time clean produced)
  SELECT COALESCE(SUM(clean_in_kg),0) INTO v_estoque_limpo_kg
  FROM salmon_manipulations WHERE company_id=v_company AND status='ACTIVE';

  v_consumido_kg := v_total_clean_kg;

  -- 5. Config
  SELECT COALESCE(min_gross_kg,50), COALESCE(min_clean_kg,30)
  INTO v_min_gross_kg, v_min_clean_kg
  FROM salmon_config WHERE company_id=v_company LIMIT 1;
  IF NOT FOUND THEN v_min_gross_kg:=50; v_min_clean_kg:=30; END IF;

  -- 6. Perda valor
  SELECT COALESCE(SUM(waste_kg*cost_per_kg_gross),0) INTO v_perda_valor
  FROM salmon_manipulations
  WHERE company_id=v_company AND status='ACTIVE' AND manipulation_date BETWEEN p_start AND p_end;

  -- 7. Custo médio/kg limpo
  v_custo_medio_kg_limpo := CASE WHEN v_total_clean_kg>0 THEN ROUND(
    (SELECT COALESCE(SUM(gross_out_kg*cost_per_kg_gross),0) FROM salmon_manipulations
     WHERE company_id=v_company AND status='ACTIVE' AND manipulation_date BETWEEN p_start AND p_end
    ) / v_total_clean_kg, 2) ELSE 0 END;

  -- 8. Revenue & CMV
  SELECT COALESCE(SUM(faturamento_bruto),0) INTO v_faturamento
  FROM financeiro_fechamento_caixa WHERE company_id=v_company AND data BETWEEN p_start AND p_end;

  SELECT COALESCE(SUM(custo_total),0) INTO v_cmv_salmon_cost
  FROM movimentacoes_estoque
  WHERE company_id=v_company AND data BETWEEN p_start AND p_end AND status='ATIVO'
    AND source_module='salmon' AND tipo NOT IN ('ENTRADA_ESTORNO','SAIDA_ESTORNO') AND direction='OUT';

  v_cmv_salmon_percent := CASE WHEN v_faturamento>0 THEN ROUND(v_cmv_salmon_cost/v_faturamento*100,2) ELSE NULL END;

  -- 9. Avg daily consumption (last 30 days)
  SELECT COALESCE(AVG(daily_clean),0) INTO v_avg_daily_consumption
  FROM (SELECT manipulation_date, SUM(clean_in_kg) as daily_clean
        FROM salmon_manipulations
        WHERE company_id=v_company AND status='ACTIVE' AND manipulation_date>=CURRENT_DATE-30
        GROUP BY manipulation_date) sub;

  v_days_remaining := CASE WHEN v_avg_daily_consumption>0 THEN ROUND(v_saldo_bruto_kg/v_avg_daily_consumption,1) ELSE -1 END;

  -- 10. FIFO recomendados
  SELECT COALESCE(jsonb_agg(row_to_json(f)::jsonb),'[]'::jsonb) INTO v_fifo
  FROM (
    SELECT e.id as entry_id, e.lot, e.sif, e.supplier_name as supplier,
           e.entry_date::text as entry_date,
           ROUND(e.gross_kg - COALESCE(SUM(m.gross_out_kg),0), 2) as balance_kg,
           e.unit_cost as cost_per_kg
    FROM salmon_entries e
    LEFT JOIN salmon_manipulations m ON m.entry_id=e.id AND m.status='ACTIVE'
    WHERE e.company_id=v_company AND e.status='ACTIVE'
    GROUP BY e.id, e.lot, e.sif, e.supplier_name, e.entry_date, e.gross_kg, e.unit_cost
    HAVING (e.gross_kg - COALESCE(SUM(m.gross_out_kg),0)) > 0.01
    ORDER BY e.entry_date ASC
    LIMIT 5
  ) f;

  -- 11. Lotes parados
  SELECT COALESCE(jsonb_agg(row_to_json(lp)::jsonb),'[]'::jsonb) INTO v_lotes_parados
  FROM (
    SELECT e.id as entry_id, e.lot, e.supplier_name as supplier,
           ROUND(e.gross_kg - COALESCE(SUM(m.gross_out_kg),0), 2) as balance_kg,
           COALESCE(MAX(m.manipulation_date)::text, e.entry_date::text) as last_movement_date,
           CURRENT_DATE - COALESCE(MAX(m.manipulation_date), e.entry_date) as days_since_movement
    FROM salmon_entries e
    LEFT JOIN salmon_manipulations m ON m.entry_id=e.id AND m.status='ACTIVE'
    WHERE e.company_id=v_company AND e.status='ACTIVE'
    GROUP BY e.id, e.lot, e.supplier_name, e.entry_date, e.gross_kg
    HAVING (e.gross_kg - COALESCE(SUM(m.gross_out_kg),0)) > 0.01
       AND (CURRENT_DATE - COALESCE(MAX(m.manipulation_date), e.entry_date)) >= 3
    ORDER BY (CURRENT_DATE - COALESCE(MAX(m.manipulation_date), e.entry_date)) DESC
    LIMIT 5
  ) lp;

  v_result := jsonb_build_object(
    'saldo_bruto_kg', ROUND(v_saldo_bruto_kg,2),
    'estoque_limpo_kg', ROUND(v_estoque_limpo_kg,2),
    'low_gross', v_saldo_bruto_kg < v_min_gross_kg,
    'low_clean', v_estoque_limpo_kg < v_min_clean_kg,
    'min_gross_kg', v_min_gross_kg,
    'min_clean_kg', v_min_clean_kg,
    'total_entries_kg', ROUND(v_total_entries_kg,2),
    'total_value', ROUND(v_total_value,2),
    'avg_cost_per_kg', ROUND(v_avg_cost_per_kg,2),
    'entries_count', v_entries_count,
    'total_manipulated_kg', ROUND(v_total_manipulated_kg,2),
    'total_clean_kg', ROUND(v_total_clean_kg,2),
    'consumido_kg', ROUND(v_consumido_kg,2),
    'avg_yield_percent', ROUND(v_avg_yield_percent,2),
    'avg_loss_percent', ROUND(v_avg_loss_percent,2),
    'manipulation_count', v_manipulation_count,
    'perda_kg', ROUND(v_total_waste_kg,2),
    'perda_valor', ROUND(v_perda_valor,2),
    'avg_daily_consumption_kg', ROUND(v_avg_daily_consumption,2),
    'days_remaining', v_days_remaining,
    'revenue', ROUND(v_faturamento,2),
    'cmv_salmon_percent', v_cmv_salmon_percent,
    'custo_medio_kg_limpo', v_custo_medio_kg_limpo,
    'fifo_recomendados', v_fifo,
    'lotes_parados', v_lotes_parados
  );

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_salmon_inventory_adjustment_kg()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company       uuid;
  v_produto_id    uuid;
  v_adjustment_kg numeric := 0;
BEGIN
  v_company := public.assert_tenant();

  IF NOT public.has_any_permission(auth.uid(), ARRAY[
    'salmon:estoque:view', 'salmon:dashboard:view', 'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  SELECT id INTO v_produto_id
    FROM public.produtos
   WHERE company_id        = v_company
     AND is_salmon_raw_linked = true
   LIMIT 1;

  IF v_produto_id IS NULL THEN
    RETURN jsonb_build_object('adjustment_kg', 0, 'produto_found', false);
  END IF;

  SELECT COALESCE(SUM(
    CASE tipo
      WHEN 'AJUSTE_INVENTARIO_POSITIVO' THEN  quantidade
      WHEN 'AJUSTE_INVENTARIO_NEGATIVO' THEN -quantidade
      ELSE 0
    END
  ), 0)
    INTO v_adjustment_kg
    FROM public.movimentacoes_estoque
   WHERE company_id = v_company
     AND produto_id = v_produto_id
     AND status     = 'ATIVO'
     AND tipo IN ('AJUSTE_INVENTARIO_POSITIVO', 'AJUSTE_INVENTARIO_NEGATIVO');

  RETURN jsonb_build_object(
    'adjustment_kg',  v_adjustment_kg,
    'produto_found',  true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_salmon_reconciliation_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company        uuid;
  v_entries_count  bigint;
  v_entries_kg     numeric;
  v_manips_count   bigint;
  v_manips_kg      numeric;
  v_ledger_saldo   numeric;
BEGIN
  v_company := public.assert_tenant();

  IF NOT public.has_any_permission(auth.uid(), ARRAY[
    'salmon:entradas:view', 'salmon:read', 'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'Sem permissão para reconciliação de salmão';
  END IF;

  SELECT COUNT(*), COALESCE(SUM(gross_kg), 0)
    INTO v_entries_count, v_entries_kg
    FROM public.salmon_entries
   WHERE company_id = v_company
     AND status = 'ACTIVE';

  SELECT COUNT(*), COALESCE(SUM(gross_out_kg), 0)
    INTO v_manips_count, v_manips_kg
    FROM public.salmon_manipulations
   WHERE company_id = v_company
     AND status = 'ACTIVE';

  -- Replica exatamente a lógica do reduce no client: IN soma, OUT subtrai,
  -- e tipos de estorno são ignorados.
  SELECT COALESCE(SUM(
    CASE direction
      WHEN 'IN'  THEN  quantidade
      WHEN 'OUT' THEN -quantidade
      ELSE 0
    END
  ), 0)
    INTO v_ledger_saldo
    FROM public.movimentacoes_estoque
   WHERE company_id    = v_company
     AND source_module = 'salmon'
     AND status        = 'ATIVO'
     AND tipo NOT IN ('ENTRADA_ESTORNO', 'SAIDA_ESTORNO');

  RETURN jsonb_build_object(
    'entries', jsonb_build_object(
      'count',    v_entries_count,
      'total_kg', v_entries_kg
    ),
    'manips', jsonb_build_object(
      'count',    v_manips_count,
      'total_kg', v_manips_kg
    ),
    'ledger_saldo', v_ledger_saldo
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_first_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin') THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'admin') ON CONFLICT DO NOTHING;

  -- Corrigido: Removido o ::text que causava erro
  INSERT INTO public.audit_logs (
    module, action, entity, entity_id, actor_user_id, source, success, after, metadata
  ) VALUES (
    'system', 'create_first_admin', 'user_roles', NEW.id, NEW.id,
    'trigger', true,
    jsonb_build_object('user_id', NEW.id, 'role', 'admin'),
    jsonb_build_object('trigger', 'handle_first_admin', 'note', 'Bootstrap first admin')
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_company uuid;
BEGIN
 v_company:=NULLIF(NEW.raw_app_meta_data->>'company_id','')::uuid;
 IF v_company IS NULL THEN
   DELETE FROM multiunit_private.pending_identity_companies
   WHERE email=lower(NEW.email) AND expires_at>now() RETURNING company_id INTO v_company;
 END IF;
 IF v_company IS NULL OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=v_company AND ativo
   AND id<>'00000000-0000-0000-0000-000000000001'::uuid) THEN
   RAISE EXCEPTION 'TRUSTED_COMPANY_REQUIRED';
 END IF;
 INSERT INTO public.profiles(id,nome,email,company_id)
 VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'nome',''),COALESCE(NEW.email,''),v_company);
 -- The authorized RPC creates membership and grants in one transaction. If it
 -- fails after Auth creates the identity, retrying can safely finish provisioning.
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_companies()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_uid uuid;
  v_result jsonb;
BEGIN
  v_caller_uid := auth.uid();
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION '403: Não autenticado';
  END IF;

  IF NOT has_permission(v_caller_uid, 'system:global:manage') THEN
    RAISE EXCEPTION '403: Sem permissão';
  END IF;

  SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at)
  INTO v_result
  FROM (
    SELECT
      c.id,
      c.nome,
      c.cnpj,
      c.ativo,
      c.created_at,
      c.updated_at,
      (SELECT count(*) FROM public.company_memberships p WHERE p.company_id = c.id AND p.status='active') AS total_usuarios
    FROM companies c
    WHERE c.id <> '00000000-0000-0000-0000-000000000001'::uuid
    ORDER BY c.created_at
  ) t;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.list_fin_contas_pagar_abertas(p_search text DEFAULT NULL::text, p_valor numeric DEFAULT NULL::numeric, p_data date DEFAULT NULL::date, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_search text;
  v_limit int;
  v_result jsonb;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'financeiro:pagar:view',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  v_limit := LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100);
  v_search := NULLIF(btrim(lower(public.immutable_unaccent(p_search))), '');

  SELECT COALESCE(jsonb_agg(to_jsonb(t) - 'ordem' ORDER BY t.ordem, t.data_vencimento DESC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      cp.id,
      cp.descricao,
      cp.fornecedor,
      cp.valor,
      cp.status,
      cp.data_vencimento,
      cp.data_competencia,
      cp.conta_id,
      cp.categoria_id,
      public.fin_entity_has_category(cp.id, cp.categoria_id, cp.company_id) AS tem_categoria,
      (CASE WHEN p_valor IS NOT NULL AND abs(cp.valor - p_valor) < 0.01 THEN 0 ELSE 1 END)
        * 100000
        + LEAST(COALESCE(abs(cp.data_vencimento - COALESCE(p_data, CURRENT_DATE)), 99999), 99999) AS ordem
    FROM public.fin_contas_pagar cp
    WHERE cp.company_id = v_company
      AND cp.status IN ('RASCUNHO', 'AGUARDANDO_APROVACAO', 'APROVADO', 'VENCIDO')
      AND (
        v_search IS NULL
        OR cp.descricao_unaccent LIKE '%' || v_search || '%'
        OR cp.fornecedor_unaccent LIKE '%' || v_search || '%'
      )
    ORDER BY ordem, cp.data_vencimento DESC
    LIMIT v_limit
  ) t;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_audit(p_source text, p_module text, p_entity text, p_entity_id text, p_action text, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entity_uuid uuid;
  v_metadata jsonb;
BEGIN
  v_metadata := COALESCE(p_metadata, '{}'::jsonb);

  IF p_source IS NOT NULL AND p_source <> '' THEN
    v_metadata := jsonb_build_object('source', p_source) || v_metadata;
  END IF;

  IF p_entity_id IS NOT NULL
     AND p_entity_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    v_entity_uuid := p_entity_id::uuid;
    PERFORM public.log_audit(
      p_source := p_source,
      p_module := p_module,
      p_entity := p_entity,
      p_entity_id := v_entity_uuid,
      p_action := p_action,
      p_before := p_before,
      p_after := p_after,
      p_metadata := CASE WHEN v_metadata = '{}'::jsonb THEN NULL ELSE v_metadata END
    );
    RETURN;
  END IF;

  PERFORM public.audit_log_write(
    _module := p_module,
    _action := p_action,
    _entity_type := p_entity,
    _entity_id := p_entity_id,
    _before := p_before,
    _after := p_after,
    _metadata := CASE WHEN v_metadata = '{}'::jsonb THEN NULL ELSE v_metadata END,
    _severity := 'info'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count INT;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;

  UPDATE notifications
  SET read_at = now()
  WHERE recipient_user_id = auth.uid()
    AND read_at IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count > 0 THEN
    PERFORM log_audit(
      'rpc', 'notifications', 'notifications', NULL::uuid,
      'MARK_ALL_READ', NULL,
      jsonb_build_object('count', v_count, 'timestamp', now())
    );
  END IF;

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.onboard_new_company(p_company_name text, p_cnpj text DEFAULT NULL::text, p_admin_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_uid uuid;
  v_new_company_id uuid;
  v_result jsonb;
BEGIN
  v_caller_uid := auth.uid();
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION '403: Não autenticado';
  END IF;

  IF NOT has_permission(v_caller_uid, 'system:global:manage') THEN
    RAISE EXCEPTION '403: Sem permissão (system:global:manage)';
  END IF;

  IF p_company_name IS NULL OR trim(p_company_name) = '' THEN
    RAISE EXCEPTION '400: Nome da empresa é obrigatório';
  END IF;

  IF p_cnpj IS NOT NULL AND trim(p_cnpj) <> '' THEN
    IF EXISTS (SELECT 1 FROM companies WHERE cnpj = trim(p_cnpj)) THEN
      RAISE EXCEPTION '409: CNPJ já cadastrado';
    END IF;
  END IF;

  INSERT INTO companies (nome, cnpj, ativo)
  VALUES (trim(p_company_name), NULLIF(trim(p_cnpj), ''), true)
  RETURNING id INTO v_new_company_id;

  INSERT INTO public.turnos (company_id, nome, hora_inicio, hora_fim, ativo)
  VALUES
    (v_new_company_id, 'Manhã', '07:00:00'::time, '15:00:00'::time, true),
    (v_new_company_id, 'Tarde', '15:00:00'::time, '23:00:00'::time, true),
    (v_new_company_id, 'Noite', '23:00:00'::time, '07:00:00'::time, true),
    (v_new_company_id, 'Geral', '00:00:00'::time, '23:59:59'::time, true);

  -- Plano de contas fixo: raízes NÃO OPERACIONAIS sempre presentes, mesmo
  -- padrão de Ren Sushi/Moralles, desde a criação da empresa.
  PERFORM public.fin_get_categoria_desconto_baixa(v_new_company_id);
  PERFORM public.fin_get_categoria_desconto_concedido(v_new_company_id);

  INSERT INTO public.company_memberships(user_id, company_id) VALUES(v_caller_uid, v_new_company_id)
    ON CONFLICT(user_id, company_id) DO UPDATE SET status='active', updated_at=now();

  INSERT INTO user_roles (user_id, company_id, role)
  VALUES (v_caller_uid, v_new_company_id, 'admin')
  ON CONFLICT (user_id, company_id, role) DO NOTHING;

  IF p_admin_user_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_admin_user_id) THEN
      RAISE EXCEPTION '404: Usuário admin não encontrado';
    END IF;

    INSERT INTO public.company_memberships(user_id,company_id) VALUES(p_admin_user_id,v_new_company_id) ON CONFLICT(user_id,company_id) DO UPDATE SET status='active',updated_at=now();

    INSERT INTO user_roles (user_id, company_id, role)
    VALUES (p_admin_user_id, v_new_company_id, 'admin')
    ON CONFLICT (user_id, company_id, role) DO NOTHING;
  END IF;

  INSERT INTO job_roles (company_id, nome, descricao)
  VALUES
    (v_new_company_id, 'Gerente Geral', 'Responsável geral pela operação'),
    (v_new_company_id, 'Chef de Cozinha', 'Responsável pela cozinha e fichas técnicas'),
    (v_new_company_id, 'Estoquista', 'Responsável pelo controle de estoque'),
    (v_new_company_id, 'Comprador', 'Responsável pelas compras e fornecedores'),
    (v_new_company_id, 'Financeiro', 'Responsável pelo módulo financeiro'),
    (v_new_company_id, 'Operador', 'Operação geral do dia a dia')
  ON CONFLICT (company_id, nome) DO NOTHING;

  INSERT INTO admin_actions_log (actor_user_id, company_id, action, details)
  VALUES (
    v_caller_uid,
    v_new_company_id,
    'COMPANY_CREATED',
    jsonb_build_object(
      'company_name', trim(p_company_name),
      'cnpj', p_cnpj,
      'admin_user_id', p_admin_user_id
    )
  );

  v_result := jsonb_build_object(
    'success', true,
    'company_id', v_new_company_id,
    'company_name', trim(p_company_name)
  );

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.pay_conta_pagar(p_id uuid, p_expected_updated_at text, p_data_pagamento date DEFAULT NULL::date, p_conta_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_lanc_id uuid;
  v_company_id uuid;
  v_conta_id uuid;
  v_pag date;
  v_comp date;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;
  IF NOT public.has_any_permission(auth.uid(), ARRAY['financeiro:pagar:edit', 'financeiro:pagar:approve', 'finance:manage', 'system:global:manage']) THEN
    RAISE EXCEPTION 'Sem permissão para pagar contas.';
  END IF;

  v_company_id := public.assert_tenant();

  SELECT * INTO v_item FROM fin_contas_pagar
  WHERE id = p_id AND company_id = v_company_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: conta a pagar não encontrada.'; END IF;

  IF v_item.updated_at != p_expected_updated_at::timestamptz THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT: registro alterado por outro usuário. Recarregue.';
  END IF;
  IF v_item.status NOT IN ('APROVADO', 'AGUARDANDO_APROVACAO') THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: %', v_item.status;
  END IF;

  v_conta_id := COALESCE(p_conta_id, v_item.conta_id);
  IF v_conta_id IS NULL THEN
    RAISE EXCEPTION 'CONTA_OBRIGATORIA: selecione a conta bancária de onde o pagamento saiu.';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM fin_contas WHERE id = v_conta_id AND company_id = v_company_id) THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária não pertence à empresa';
  END IF;

  v_pag := COALESCE(p_data_pagamento, (now() AT TIME ZONE 'America/Sao_Paulo')::date);
  v_comp := COALESCE(v_item.data_competencia, v_item.data_vencimento, v_pag);

  INSERT INTO fin_lancamentos (
    tipo, valor, data_competencia, data_pagamento, descricao,
    categoria_id, centro_custo_id, conta_id,
    forma_pagamento, status, created_by,
    referencia_modulo, referencia_id, company_id, origem
  )
  VALUES (
    'DESPESA', v_item.valor, v_comp, v_pag, v_item.descricao,
    v_item.categoria_id, v_item.centro_custo_id, v_conta_id,
    v_item.forma_pagamento, 'REALIZADO', auth.uid(),
    'contas_pagar', p_id::text, v_company_id, 'espelho_cp'
  )
  RETURNING id INTO v_lanc_id;

  INSERT INTO fin_lancamento_rateios (lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id)
  SELECT v_lanc_id, categoria_id, centro_custo_id, valor, percentual, company_id
  FROM fin_lancamento_rateios
  WHERE lancamento_id = p_id AND company_id = v_company_id;

  UPDATE fin_contas_pagar
  SET status = 'PAGO', data_pagamento = v_pag, valor_pago = v_item.valor,
      lancamento_id = v_lanc_id, conta_id = v_conta_id
  WHERE id = p_id AND company_id = v_company_id;

  INSERT INTO fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
  VALUES ('contas_pagar', p_id, 'pagar', auth.uid(), v_company_id,
    jsonb_build_object('lancamento_id', v_lanc_id, 'conta_id', v_conta_id, 'data_pagamento', v_pag));

  PERFORM public.log_audit('rpc', 'financeiro', 'fin_contas_pagar', p_id, 'PAY',
    jsonb_build_object('status_anterior', v_item.status, 'valor', v_item.valor),
    jsonb_build_object('lancamento_id', v_lanc_id, 'status', 'PAGO', 'data_pagamento', v_pag,
      'data_competencia', v_comp, 'conta_id', v_conta_id));

  RETURN json_build_object('lancamento_id', v_lanc_id, 'status', 'PAGO', 'conta_id', v_conta_id);
END;
$function$

