CREATE OR REPLACE FUNCTION public.receive_conta_receber(p_id uuid, p_expected_updated_at text, p_data_recebimento date DEFAULT NULL::date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item RECORD;
  v_lanc_id uuid;
  v_company_id uuid;
  v_conta_exists boolean;
  v_rec date;
  v_comp date;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;
  IF NOT public.has_any_permission(auth.uid(), ARRAY['financeiro:receber:edit', 'finance:manage', 'system:global:manage']) THEN
    RAISE EXCEPTION 'Sem permissão para receber contas.';
  END IF;

  SELECT * INTO v_item FROM fin_contas_receber WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  IF v_item.updated_at != p_expected_updated_at::timestamptz THEN
    RAISE EXCEPTION 'Registro alterado por outro usuário. Recarregue.';
  END IF;
  IF v_item.status != 'A_RECEBER' THEN
    RAISE EXCEPTION 'Status inválido para recebimento: %', v_item.status;
  END IF;

  v_company_id := v_item.company_id;

  v_rec := COALESCE(p_data_recebimento, (now() AT TIME ZONE 'America/Sao_Paulo')::date);
  v_comp := COALESCE(v_item.data_competencia, v_item.data_vencimento, v_rec);

  IF v_item.conta_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM fin_contas WHERE id = v_item.conta_id AND company_id = v_company_id) INTO v_conta_exists;
    IF NOT v_conta_exists THEN
      RAISE EXCEPTION 'Conta bancária não encontrada ou não pertence à empresa';
    END IF;
  END IF;

  INSERT INTO fin_lancamentos (
    tipo, valor, data_competencia, data_pagamento, descricao,
    categoria_id, centro_custo_id, conta_id,
    forma_pagamento, status, created_by,
    referencia_modulo, referencia_id, company_id, origem
  )
  VALUES (
    'RECEITA', v_item.valor, v_comp, v_rec, v_item.descricao,
    v_item.categoria_id, v_item.centro_custo_id, v_item.conta_id,
    v_item.forma_pagamento, 'REALIZADO', auth.uid(),
    'contas_receber', p_id::text, v_company_id, 'espelho_cr'
  )
  RETURNING id INTO v_lanc_id;

  INSERT INTO fin_lancamento_rateios (lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id)
  SELECT v_lanc_id, categoria_id, centro_custo_id, valor, percentual, company_id
  FROM fin_lancamento_rateios
  WHERE lancamento_id = p_id AND company_id = v_company_id;

  UPDATE fin_contas_receber
  SET status = 'RECEBIDO', data_recebimento = v_rec, valor_recebido = v_item.valor, lancamento_id = v_lanc_id
  WHERE id = p_id;

  INSERT INTO fin_audit_logs (entidade, entidade_id, acao, user_id, company_id)
  VALUES ('contas_receber', p_id, 'receber', auth.uid(), v_company_id);

  PERFORM public.log_audit('rpc', 'financeiro', 'fin_contas_receber', p_id, 'RECEIVE',
    jsonb_build_object('status_anterior', v_item.status, 'valor', v_item.valor),
    jsonb_build_object('lancamento_id', v_lanc_id, 'status', 'RECEBIDO', 'data_recebimento', v_rec, 'data_competencia', v_comp));

  RETURN json_build_object('lancamento_id', v_lanc_id, 'status', 'RECEBIDO');
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_market_order_atomic(p_recebimento_id uuid, p_items jsonb, p_observacoes text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller uuid;
  v_company uuid;
  v_rec recebimentos%ROWTYPE;
  v_item jsonb;
  v_ri recebimento_itens%ROWTYPE;
  v_prod RECORD;
  v_orig_item RECORD;
  v_ref_id text;
  v_custo_unit numeric;
  v_qtd numeric;
  v_mov_id uuid;
  v_items_inserted int := 0;
  v_items_skipped int := 0;
BEGIN
  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF NOT has_permission(v_caller, 'compras:recebimentos:close') THEN
    RAISE EXCEPTION 'Sem permissão (compras:recebimentos:close)';
  END IF;

  v_company := public.assert_tenant();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Tenant não encontrado para o usuário';
  END IF;

  SELECT * INTO v_rec FROM recebimentos WHERE id = p_recebimento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Recebimento não encontrado: %', p_recebimento_id;
  END IF;

  IF v_rec.status NOT IN ('AGUARDANDO_RECEBIMENTO', 'RECEBIDO_CONFIRMADO') THEN
    RAISE EXCEPTION 'Status inválido para lançamento de estoque: %', v_rec.status;
  END IF;

  IF v_rec.estoque_atualizado_em IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_processed', true,
      'recebimento_id', p_recebimento_id,
      'message', 'Estoque já foi atualizado para este recebimento'
    );
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT * INTO v_ri FROM recebimento_itens
    WHERE id = (v_item->>'recebimento_item_id')::uuid
      AND recebimento_id = p_recebimento_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % não pertence ao recebimento %',
        v_item->>'recebimento_item_id', p_recebimento_id;
    END IF;

    IF v_ri.produto_id IS NULL OR v_ri.recebido = false THEN
      v_items_skipped := v_items_skipped + 1;
      CONTINUE;
    END IF;

    v_qtd := COALESCE(v_ri.qtd_recebida, v_ri.qtd_comprada);
    IF v_qtd <= 0 THEN
      v_items_skipped := v_items_skipped + 1;
      CONTINUE;
    END IF;

    v_ref_id := 'MARKET_POI:' || v_ri.id::text;

    SELECT custo_padrao INTO v_prod FROM produtos WHERE id = v_ri.produto_id;

    SELECT preco_unitario INTO v_orig_item
    FROM solic_compra_mercado_item WHERE id = v_ri.item_id;

    v_custo_unit := COALESCE(v_orig_item.preco_unitario, v_prod.custo_padrao, 0);

    IF NOT EXISTS (
      SELECT 1 FROM movimentacoes_estoque
      WHERE reference_type = 'MARKET_RECEBIMENTO_ITEM'
        AND reference_id = v_ref_id
        AND status = 'ATIVO'
    ) THEN
      INSERT INTO movimentacoes_estoque (
        produto_id, data, tipo, quantidade, custo_unitario, custo_total,
        origem, observacao, created_by, status,
        reference_type, reference_id, internal_transfer, source_module
      ) VALUES (
        v_ri.produto_id,
        CURRENT_DATE,
        'ENTRADA',
        v_qtd,
        ROUND(v_custo_unit::numeric, 4),
        ROUND((v_qtd * v_custo_unit)::numeric, 2),
        'Recebimento Mercado',
        'Entrada atômica — Recebimento ' || p_recebimento_id::text || ' Item ' || COALESCE(v_ri.item_id::text, '?'),
        v_caller,
        'ATIVO',
        'MARKET_RECEBIMENTO_ITEM',
        v_ref_id,
        false,
        'compras_mercado'
      ) RETURNING id INTO v_mov_id;

      UPDATE produtos SET
        last_cost_purchase_unit = v_custo_unit,
        last_cost_base_unit = ROUND(v_custo_unit::numeric, 4),
        last_purchase_date = CURRENT_DATE::text,
        custo_padrao = CASE
          WHEN custo_padrao IS NULL OR custo_padrao = 0 THEN v_custo_unit
          ELSE custo_padrao
        END
      WHERE id = v_ri.produto_id;

      v_items_inserted := v_items_inserted + 1;
    ELSE
      v_items_skipped := v_items_skipped + 1;
    END IF;
  END LOOP;

  UPDATE recebimentos SET
    status = 'RECEBIDO_CONFIRMADO',
    recebido_por = COALESCE(recebido_por, v_caller),
    recebido_em = COALESCE(recebido_em, now()),
    enviar_ao_estoque = true,
    estoque_atualizado_em = now(),
    estoque_atualizado_por = v_caller,
    observacoes = COALESCE(NULLIF(p_observacoes, ''), observacoes),
    updated_at = now()
  WHERE id = p_recebimento_id;

  UPDATE solic_compra_mercado SET
    status = 'ESTOQUE_ATUALIZADO',
    updated_at = now()
  WHERE id = v_rec.solicitacao_id;

  INSERT INTO confirmacoes_recebimento (
    recebimento_id, solicitacao_id, mensagem, criado_por, responsavel_compra_id
  )
  SELECT
    p_recebimento_id,
    v_rec.solicitacao_id,
    'Estoque atualizado via RPC atômica — ' || v_items_inserted || ' itens inseridos',
    v_caller,
    s.responsavel_user_id
  FROM solic_compra_mercado s
  WHERE s.id = v_rec.solicitacao_id;

  -- Fix: registro_id is UUID, cast properly
  INSERT INTO audit_log (tabela, registro_id, acao, user_id)
  VALUES ('recebimentos', p_recebimento_id, 'ESTOQUE_ATUALIZADO_ATOMIC', v_caller);

  RETURN jsonb_build_object(
    'success', true,
    'recebimento_id', p_recebimento_id,
    'items_inserted', v_items_inserted,
    'items_skipped', v_items_skipped,
    'already_processed', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase_order_atomic(p_order_id uuid, p_items jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order RECORD;
  v_item jsonb;
  v_oi RECORD;
  v_conv numeric;
  v_qty_base numeric;
  v_cost_base numeric;
  v_mov_id uuid;
  v_items_received int := 0;
  v_items_not_delivered int := 0;
  v_total_confirmed numeric := 0;
  v_new_status text;
  v_ref_id text;
  v_caller uuid;
  v_supplier_uuid uuid;
  v_qty_received numeric;
  v_qty_shortfall numeric;
  v_shortfall_item_id uuid;
BEGIN
  v_caller := auth.uid();
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;

  IF NOT has_any_permission(v_caller, ARRAY[
    'purchases:receiving:manage',
    'compras:recebimentos:edit',
    'compras:recebimentos:close',
    'compras:recebimentos:create',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'Sem permissão para receber pedidos.';
  END IF;

  SELECT * INTO v_order FROM purchase_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado: %', p_order_id; END IF;
  IF v_order.status NOT IN ('IN_RECEIVING', 'OPEN', 'SHOPPING_OK', 'PARTIAL') THEN
    RAISE EXCEPTION 'Status inválido para recebimento: %', v_order.status;
  END IF;

  IF v_order.supplier_name IS NOT NULL AND v_order.supplier_name != '' THEN
    INSERT INTO suppliers (name) VALUES (v_order.supplier_name)
    ON CONFLICT (name) DO UPDATE SET updated_at = now()
    RETURNING id INTO v_supplier_uuid;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT * INTO v_oi FROM purchase_order_items
    WHERE id = (v_item->>'order_item_id')::uuid AND order_id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % não pertence ao pedido %', v_item->>'order_item_id', p_order_id;
    END IF;

    IF (v_item->>'status') = 'NOT_DELIVERED' THEN
      UPDATE purchase_order_items SET
        received_status = 'NOT_DELIVERED',
        not_delivered_reason = COALESCE(v_item->>'reason', 'Não entregue'),
        received_at = now(), received_by = v_caller, updated_at = now()
      WHERE id = v_oi.id;
      v_items_not_delivered := v_items_not_delivered + 1;
    ELSE
      v_qty_received := COALESCE((v_item->>'qty_received')::numeric, 0);
      IF v_qty_received <= 0 THEN
        RAISE EXCEPTION 'Quantidade deve ser > 0 para item %', v_oi.name_snapshot;
      END IF;

      -- Detect partial receipt: qty_received < qty_requested
      v_qty_shortfall := v_oi.qty_requested - v_qty_received;

      UPDATE purchase_order_items SET
        qty_received = v_qty_received,
        received_status = 'RECEIVED', received_at = now(),
        received_by = v_caller, updated_at = now()
      WHERE id = v_oi.id;

      -- If there's a shortfall, create a new NOT_DELIVERED item for the difference
      IF v_qty_shortfall > 0.001 THEN
        INSERT INTO purchase_order_items (
          order_id, stock_item_id, name_snapshot, unit_snapshot,
          estimated_unit_value, qty_requested, qty_received,
          received_status, not_delivered_reason, received_at, received_by,
          shopping_status, shopping_note,
          purchase_unit_snapshot, purchase_unit_cost_snapshot, conversion_factor_snapshot
        ) VALUES (
          p_order_id, v_oi.stock_item_id, v_oi.name_snapshot, v_oi.unit_snapshot,
          v_oi.estimated_unit_value, v_qty_shortfall, 0,
          'NOT_DELIVERED',
          'Item marcado como comprado no Checklist, porém no recebimento foi informada quantidade inferior à prevista. Previsto: ' || v_oi.qty_requested || ' ' || v_oi.unit_snapshot || ', Recebido: ' || v_qty_received || ' ' || v_oi.unit_snapshot || '.',
          now(), v_caller,
          v_oi.shopping_status, v_oi.shopping_note,
          v_oi.purchase_unit_snapshot, v_oi.purchase_unit_cost_snapshot, v_oi.conversion_factor_snapshot
        ) RETURNING id INTO v_shortfall_item_id;

        v_items_not_delivered := v_items_not_delivered + 1;
      END IF;

      -- Stock entry logic
      IF v_oi.stock_item_id IS NOT NULL THEN
        v_conv := COALESCE(v_oi.conversion_factor_snapshot, 1);
        v_qty_base := v_qty_received * v_conv;
        v_cost_base := CASE WHEN v_conv > 0
          THEN COALESCE((v_item->>'unit_cost')::numeric, v_oi.estimated_unit_value) / v_conv
          ELSE COALESCE((v_item->>'unit_cost')::numeric, v_oi.estimated_unit_value)
        END;

        v_ref_id := 'POI:' || v_oi.id::text;

        IF NOT EXISTS (
          SELECT 1 FROM movimentacoes_estoque
          WHERE reference_type = 'PURCHASE_ORDER_ITEM' AND reference_id = v_ref_id AND status = 'ATIVO'
        ) THEN
          INSERT INTO movimentacoes_estoque (
            produto_id, data, tipo, quantidade, custo_unitario, custo_total,
            origem, observacao, created_by, status,
            reference_type, reference_id, internal_transfer, source_module
          ) VALUES (
            v_oi.stock_item_id,
            COALESCE((v_item->>'movement_date')::date, CURRENT_DATE),
            'ENTRADA', v_qty_base, ROUND(v_cost_base::numeric, 4),
            ROUND((v_qty_base * v_cost_base)::numeric, 2),
            'Recebimento Pedido/Compra',
            'Recebimento atômico — Pedido ' || p_order_id::text || ' Item ' || v_oi.name_snapshot,
            v_caller, 'ATIVO', 'PURCHASE_ORDER_ITEM', v_ref_id, false, 'purchases'
          ) RETURNING id INTO v_mov_id;

          UPDATE produtos SET
            last_cost_purchase_unit = COALESCE((v_item->>'unit_cost')::numeric, v_oi.estimated_unit_value),
            last_cost_base_unit = ROUND(v_cost_base::numeric, 4),
            last_purchase_date = CURRENT_DATE::text,
            last_supplier = v_order.supplier_name
          WHERE id = v_oi.stock_item_id;

          IF v_supplier_uuid IS NOT NULL AND v_oi.stock_item_id IS NOT NULL THEN
            INSERT INTO supplier_item_prices (supplier_id, produto_id, unit_cost, purchase_unit, conversion_factor)
            VALUES (v_supplier_uuid, v_oi.stock_item_id,
              COALESCE((v_item->>'unit_cost')::numeric, v_oi.estimated_unit_value),
              COALESCE(v_oi.purchase_unit_snapshot, v_oi.unit_snapshot),
              COALESCE(v_oi.conversion_factor_snapshot, 1))
            ON CONFLICT (supplier_id, produto_id) DO UPDATE SET
              unit_cost = EXCLUDED.unit_cost,
              purchase_unit = EXCLUDED.purchase_unit,
              conversion_factor = EXCLUDED.conversion_factor,
              updated_at = now();
          END IF;
        END IF;
      END IF;

      v_total_confirmed := v_total_confirmed + (v_qty_received * COALESCE((v_item->>'unit_cost')::numeric, v_oi.estimated_unit_value));
      v_items_received := v_items_received + 1;
    END IF;
  END LOOP;

  -- Determine new order status based on ALL items in the order (not just current batch)
  IF EXISTS (
    SELECT 1 FROM purchase_order_items
    WHERE order_id = p_order_id AND deleted_at IS NULL AND received_status = 'PENDING'
  ) THEN
    v_new_status := 'IN_RECEIVING';
  ELSIF EXISTS (
    SELECT 1 FROM purchase_order_items
    WHERE order_id = p_order_id AND deleted_at IS NULL AND received_status = 'NOT_DELIVERED'
  ) THEN
    v_new_status := 'PARTIAL';
  ELSE
    v_new_status := 'COMPLETED';
  END IF;

  UPDATE purchase_orders SET
    status = v_new_status,
    total_confirmed = COALESCE(total_confirmed, 0) + v_total_confirmed,
    concluded_at = CASE WHEN v_new_status = 'COMPLETED' THEN now() ELSE concluded_at END,
    updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO audit_log (tabela, registro_id, acao, user_id, valor_novo)
  VALUES ('purchase_orders', p_order_id, 'RECEBIMENTO_ATOMICO', v_caller,
    jsonb_build_object('status', v_new_status, 'received', v_items_received, 'not_delivered', v_items_not_delivered)::text);

  RETURN jsonb_build_object(
    'status', v_new_status,
    'items_received', v_items_received,
    'items_not_delivered', v_items_not_delivered,
    'total_confirmed', v_total_confirmed
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_auto_bind_transfer_counterparts(p_conta_id uuid, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_line jsonb;
  v_external_id text;
  v_tipo text;
  v_data date;
  v_valor numeric;
  v_lancamento_id uuid;
  v_candidate_count integer;
  v_matched_external_ids jsonb := '[]'::jsonb;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: p_lines deve ser um array';
  END IF;
  IF jsonb_array_length(p_lines) > 5000 THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: máximo de 5000 linhas por importação';
  END IF;

  PERFORM 1
  FROM public.fin_contas c
  WHERE c.id = p_conta_id
    AND c.company_id = v_company;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_company::text || ':' || p_conta_id::text, 0)
  );

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_external_id := NULLIF(btrim(v_line->>'external_id'), '');
    v_tipo := v_line->>'tipo';

    IF v_external_id IS NULL OR length(v_external_id) > 512
       OR v_tipo NOT IN ('RECEITA', 'DESPESA')
       OR (v_line->>'data') IS NULL
       OR (v_line->>'valor') IS NULL THEN
      CONTINUE;
    END IF;

    BEGIN
      v_data := (v_line->>'data')::date;
      v_valor := (v_line->>'valor')::numeric;
    EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
      CONTINUE;
    END;

    IF v_valor <= 0 THEN
      CONTINUE;
    END IF;

    SELECT v.lancamento_id INTO v_lancamento_id
    FROM public.fin_conciliacao_vinculos v
    WHERE v.company_id = v_company
      AND v.conta_id = p_conta_id
      AND v.external_id = v_external_id
      AND v.tipo = v_tipo;

    IF v_lancamento_id IS NOT NULL THEN
      v_matched_external_ids := v_matched_external_ids || jsonb_build_array(v_external_id);
      CONTINUE;
    END IF;

    v_lancamento_id := NULL;
    v_candidate_count := 0;

    WITH candidates AS (
      SELECT
        l.id,
        abs(l.data_competencia - v_data) AS date_distance
      FROM public.fin_lancamentos l
      WHERE l.company_id = v_company
        AND l.tipo = 'TRANSFERENCIA'
        AND l.status = 'REALIZADO'
        AND l.valor = v_valor
        AND l.data_competencia BETWEEN (v_data - 3) AND (v_data + 3)
        AND (
          (v_tipo = 'DESPESA' AND l.conta_id = p_conta_id)
          OR
          (v_tipo = 'RECEITA' AND l.conta_destino_id = p_conta_id)
        )
        AND EXISTS (
          SELECT 1
          FROM public.fin_conciliacao_vinculos source_link
          WHERE source_link.company_id = v_company
            AND source_link.lancamento_id = l.id
            AND source_link.conta_id <> p_conta_id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.fin_conciliacao_vinculos target_link
          WHERE target_link.company_id = v_company
            AND target_link.lancamento_id = l.id
            AND target_link.conta_id = p_conta_id
        )
    ), nearest AS (
      SELECT c.id
      FROM candidates c
      WHERE c.date_distance = (SELECT min(c2.date_distance) FROM candidates c2)
    )
    SELECT count(*)::integer, (array_agg(n.id ORDER BY n.id))[1]
    INTO v_candidate_count, v_lancamento_id
    FROM nearest n;

    IF v_candidate_count <> 1 OR v_lancamento_id IS NULL THEN
      CONTINUE;
    END IF;

    INSERT INTO public.fin_conciliacao_vinculos (
      company_id, conta_id, external_id, tipo, lancamento_id, created_by
    ) VALUES (
      v_company, p_conta_id, v_external_id, v_tipo, v_lancamento_id, v_uid
    )
    ON CONFLICT (company_id, conta_id, external_id, tipo)
    DO NOTHING;

    v_matched_external_ids := v_matched_external_ids || jsonb_build_array(v_external_id);
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'ok',
    'matched_external_ids', v_matched_external_ids,
    'matched_count', jsonb_array_length(v_matched_external_ids)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_batch_lancamentos(p_lancamento_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_count int;
  v_missing int;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED: Usuário não autenticado'; END IF;
  v_company_id := public.assert_tenant();
  IF NOT public.has_any_permission(v_user_id, ARRAY['financeiro:conciliacao:reconcile', 'finance:manage', 'system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  SELECT count(*) INTO v_missing
  FROM public.fin_lancamentos l
  WHERE l.company_id = v_company_id
    AND l.id = ANY(p_lancamento_ids)
    AND l.tipo <> 'TRANSFERENCIA'
    AND NOT public.fin_entity_has_category(l.id, l.categoria_id, l.company_id);
  IF v_missing > 0 THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = format('CATEGORY_REQUIRED: %s lançamento(s) sem categoria', v_missing);
  END IF;

  UPDATE public.fin_lancamentos
  SET conciliado = true, conciliado_em = now(), conciliado_por = v_user_id
  WHERE company_id = v_company_id AND id = ANY(p_lancamento_ids)
    AND conciliado IS DISTINCT FROM true;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count > 0 THEN
    INSERT INTO public.fin_audit_logs (entidade, acao, user_id, company_id, depois)
    VALUES ('lancamentos', 'reconcile_batch', v_user_id, v_company_id,
      jsonb_build_object('count', v_count, 'ids', p_lancamento_ids, 'category_validation', 'passed'));
  END IF;
  RETURN jsonb_build_object('status', 'ok', 'reconciled_count', v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_bind_extrato(p_conta_id uuid, p_external_id text, p_tipo text, p_lancamento_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_external_id text;
  v_existing_lancamento_id uuid;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  v_external_id := NULLIF(btrim(p_external_id), '');
  IF v_external_id IS NULL OR length(v_external_id) > 512 THEN
    RAISE EXCEPTION 'INVALID_EXTERNAL_ID';
  END IF;
  IF p_tipo NOT IN ('RECEITA', 'DESPESA') THEN
    RAISE EXCEPTION 'INVALID_TYPE';
  END IF;

  PERFORM 1
  FROM public.fin_contas c
  WHERE c.id = p_conta_id AND c.company_id = v_company;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: conta bancária'; END IF;

  PERFORM 1
  FROM public.fin_lancamentos l
  WHERE l.id = p_lancamento_id
    AND l.company_id = v_company
    AND (
      (l.tipo = 'TRANSFERENCIA' AND (l.conta_id = p_conta_id OR l.conta_destino_id = p_conta_id))
      OR (l.tipo <> 'TRANSFERENCIA' AND l.conta_id = p_conta_id)
    );
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: lançamento não pertence à conta'; END IF;

  SELECT v.lancamento_id INTO v_existing_lancamento_id
  FROM public.fin_conciliacao_vinculos v
  WHERE v.company_id = v_company
    AND v.conta_id = p_conta_id
    AND v.external_id = v_external_id
    AND v.tipo = p_tipo
  FOR UPDATE;

  IF v_existing_lancamento_id IS NOT NULL AND v_existing_lancamento_id <> p_lancamento_id THEN
    RAISE EXCEPTION 'EXTERNAL_ID_CONFLICT: linha bancária já vinculada a outro lançamento';
  END IF;

  INSERT INTO public.fin_conciliacao_vinculos (
    company_id, conta_id, external_id, tipo, lancamento_id, created_by
  ) VALUES (
    v_company, p_conta_id, v_external_id, p_tipo, p_lancamento_id, v_uid
  )
  ON CONFLICT (company_id, conta_id, external_id, tipo)
  DO UPDATE SET lancamento_id = EXCLUDED.lancamento_id;

  RETURN jsonb_build_object('status', 'ok', 'lancamento_id', p_lancamento_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_create_transfer_from_extrato(p_data date, p_valor numeric, p_descricao text, p_conta_origem_id uuid, p_conta_destino_id uuid, p_external_id text, p_external_tipo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_lancamento_id uuid;
  v_existing_id uuid;
  v_existing_type text;
  v_existing_status text;
  v_existing_count integer;
  v_external_id text;
  v_extrato_conta_id uuid;
  v_status text := 'ok';
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF p_valor IS NULL OR p_valor <= 0 THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: valor deve ser maior que zero';
  END IF;
  IF p_conta_origem_id = p_conta_destino_id THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: contas de origem e destino devem ser diferentes';
  END IF;
  IF p_external_tipo NOT IN ('RECEITA', 'DESPESA') THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: tipo bancário inválido';
  END IF;

  v_external_id := NULLIF(btrim(p_external_id), '');
  IF v_external_id IS NOT NULL AND length(v_external_id) > 512 THEN
    RAISE EXCEPTION 'INVALID_EXTERNAL_ID';
  END IF;
  v_extrato_conta_id := CASE
    WHEN p_external_tipo = 'DESPESA' THEN p_conta_origem_id
    ELSE p_conta_destino_id
  END;

  PERFORM 1 FROM public.fin_contas c
  WHERE c.id = p_conta_origem_id AND c.company_id = v_company;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: conta de origem'; END IF;
  PERFORM 1 FROM public.fin_contas c
  WHERE c.id = p_conta_destino_id AND c.company_id = v_company;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: conta de destino'; END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_company::text || ':transfer:' ||
      least(p_conta_origem_id::text, p_conta_destino_id::text) || ':' ||
      greatest(p_conta_origem_id::text, p_conta_destino_id::text),
      0
    )
  );

  IF v_external_id IS NOT NULL THEN
    SELECT v.lancamento_id, l.tipo, l.status
    INTO v_lancamento_id, v_existing_type, v_existing_status
    FROM public.fin_conciliacao_vinculos v
    JOIN public.fin_lancamentos l ON l.id = v.lancamento_id
    WHERE v.company_id = v_company
      AND v.conta_id = v_extrato_conta_id
      AND v.external_id = v_external_id
      AND v.tipo = p_external_tipo
      AND l.company_id = v_company;
    IF v_lancamento_id IS NOT NULL THEN
      IF v_existing_type = 'TRANSFERENCIA' AND v_existing_status = 'REALIZADO' THEN
        RETURN jsonb_build_object('status', 'duplicate', 'lancamento_id', v_lancamento_id);
      END IF;
      RAISE EXCEPTION 'EXTERNAL_ID_ALREADY_LINKED: linha bancária já vinculada ao lançamento %', v_lancamento_id;
    END IF;
  END IF;

  -- Reuse only one unclaimed manual candidate. A transfer already linked to a
  -- different line on this account is never stolen by a repeated transaction.
  WITH candidates AS (
    SELECT l.id, abs(l.data_competencia - p_data) AS date_distance
    FROM public.fin_lancamentos l
    WHERE l.company_id = v_company
      AND l.tipo = 'TRANSFERENCIA'
      AND l.status = 'REALIZADO'
      AND l.conta_id = p_conta_origem_id
      AND l.conta_destino_id = p_conta_destino_id
      AND l.valor = p_valor
      AND l.data_competencia BETWEEN (p_data - 3) AND (p_data + 3)
      AND NOT EXISTS (
        SELECT 1
        FROM public.fin_conciliacao_vinculos claimed
        WHERE claimed.company_id = v_company
          AND claimed.conta_id = v_extrato_conta_id
          AND claimed.lancamento_id = l.id
      )
  ), nearest AS (
    SELECT c.id
    FROM candidates c
    WHERE c.date_distance = (SELECT min(c2.date_distance) FROM candidates c2)
  )
  SELECT count(*)::integer, (array_agg(n.id ORDER BY n.id))[1]
  INTO v_existing_count, v_existing_id
  FROM nearest n;

  IF v_existing_count = 1 AND v_existing_id IS NOT NULL THEN
    v_lancamento_id := v_existing_id;
    v_status := 'existing';
  ELSE
    INSERT INTO public.fin_lancamentos (
      tipo, valor, data_competencia, data_pagamento, descricao,
      conta_id, conta_destino_id, status, forma_pagamento,
      conciliado, conciliado_em, conciliado_por, created_by,
      company_id, origem
    ) VALUES (
      'TRANSFERENCIA', p_valor, p_data, p_data,
      COALESCE(NULLIF(btrim(p_descricao), ''), 'Transferência de extrato'),
      p_conta_origem_id, p_conta_destino_id, 'REALIZADO', 'TRANSFERENCIA',
      true, now(), v_uid, v_uid, v_company, 'transferencia'
    )
    RETURNING id INTO v_lancamento_id;

    INSERT INTO public.fin_audit_logs (
      entidade, entidade_id, acao, user_id, company_id, depois
    ) VALUES (
      'transferencia', v_lancamento_id, 'reconcile_transfer_from_extrato', v_uid, v_company,
      jsonb_build_object(
        'origem', p_conta_origem_id,
        'destino', p_conta_destino_id,
        'valor', p_valor,
        'data', p_data,
        'external_id_used', v_external_id IS NOT NULL
      )
    );
  END IF;

  IF v_external_id IS NOT NULL THEN
    INSERT INTO public.fin_conciliacao_vinculos (
      company_id, conta_id, external_id, tipo, lancamento_id, created_by
    ) VALUES (
      v_company, v_extrato_conta_id, v_external_id, p_external_tipo, v_lancamento_id, v_uid
    )
    ON CONFLICT (company_id, conta_id, external_id, tipo) DO NOTHING;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'EXTERNAL_ID_ALREADY_LINKED: linha bancária vinculada concorrentemente';
    END IF;
  END IF;

  RETURN jsonb_build_object('status', v_status, 'lancamento_id', v_lancamento_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_create_transfer(p_data date, p_valor numeric, p_descricao text, p_conta_origem_id uuid, p_conta_destino_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_lancamento_id uuid;
  v_nome_origem text;
  v_nome_destino text;
  v_existing_id uuid;
  v_existing_count integer;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF p_valor IS NULL OR p_valor <= 0 THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: valor deve ser maior que zero';
  END IF;

  IF p_conta_origem_id = p_conta_destino_id THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: contas de origem e destino devem ser diferentes';
  END IF;

  SELECT c.nome INTO v_nome_origem
  FROM public.fin_contas c
  WHERE c.id = p_conta_origem_id AND c.company_id = v_company;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: conta de origem';
  END IF;

  SELECT c.nome INTO v_nome_destino
  FROM public.fin_contas c
  WHERE c.id = p_conta_destino_id AND c.company_id = v_company;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: conta de destino';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_company::text || ':transfer:' ||
      least(p_conta_origem_id::text, p_conta_destino_id::text) || ':' ||
      greatest(p_conta_origem_id::text, p_conta_destino_id::text),
      0
    )
  );

  WITH candidates AS (
    SELECT l.id, abs(l.data_competencia - p_data) AS date_distance
    FROM public.fin_lancamentos l
    WHERE l.company_id = v_company
      AND l.tipo = 'TRANSFERENCIA'
      AND l.status = 'REALIZADO'
      AND l.conta_id = p_conta_origem_id
      AND l.conta_destino_id = p_conta_destino_id
      AND l.valor = p_valor
      AND l.data_competencia BETWEEN (p_data - 3) AND (p_data + 3)
  ), nearest AS (
    SELECT c.id
    FROM candidates c
    WHERE c.date_distance = (SELECT min(c2.date_distance) FROM candidates c2)
  )
  SELECT count(*)::integer, (array_agg(n.id ORDER BY n.id))[1]
  INTO v_existing_count, v_existing_id
  FROM nearest n;

  IF v_existing_count = 1 AND v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'existing', 'lancamento_id', v_existing_id);
  END IF;

  INSERT INTO public.fin_lancamentos (
    tipo, valor, data_competencia, data_pagamento,
    descricao, conta_id, conta_destino_id,
    status, forma_pagamento, conciliado, conciliado_em, conciliado_por,
    created_by, company_id, origem
  )
  VALUES (
    'TRANSFERENCIA', p_valor, p_data, p_data,
    COALESCE(NULLIF(btrim(p_descricao), ''), format('Transferência: %s → %s', v_nome_origem, v_nome_destino)),
    p_conta_origem_id, p_conta_destino_id,
    'REALIZADO', 'TRANSFERENCIA', true, now(), v_uid,
    v_uid, v_company, 'transferencia'
  )
  RETURNING id INTO v_lancamento_id;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, user_id, company_id, depois
  )
  VALUES (
    'transferencia', v_lancamento_id, 'reconcile_transfer', v_uid, v_company,
    jsonb_build_object(
      'lancamento_id', v_lancamento_id,
      'origem', p_conta_origem_id,
      'destino', p_conta_destino_id,
      'valor', p_valor,
      'data', p_data,
      'modelo', 'registro_unico'
    )
  );

  RETURN jsonb_build_object('status', 'ok', 'lancamento_id', v_lancamento_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_ignorar_lancamento(p_conta_id uuid, p_data date, p_valor numeric, p_tipo text, p_descricao text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_id uuid;
  v_company_id uuid;
  v_uid uuid;
  v_descricao_normalizada text;
BEGIN
  v_company_id := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  PERFORM 1
  FROM public.fin_contas c
  WHERE c.id = p_conta_id
    AND c.company_id = v_company_id
    AND c.ativo = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária ativa';
  END IF;
  IF p_valor IS NULL OR p_valor <= 0 OR p_tipo NOT IN ('RECEITA', 'DESPESA') OR p_data IS NULL THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: data, valor e tipo são obrigatórios';
  END IF;

  v_descricao_normalizada := lower(public.immutable_unaccent(
    regexp_replace(btrim(COALESCE(p_descricao, '')), '\s+', ' ', 'g')
  ));
  IF v_descricao_normalizada LIKE '%aplicacao%contamax%'
     OR v_descricao_normalizada LIKE '%resgate%contamax%' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'AUTOMATIC_INVESTMENT_REQUIRES_NEUTRALIZATION: aplicação/resgate ContaMax é movimentação interna';
  END IF;

  INSERT INTO public.fin_conciliacao_ignoradas (
    company_id, conta_id, data, valor, tipo, descricao,
    ignorado_por, tratamento
  ) VALUES (
    v_company_id, p_conta_id, p_data, round(p_valor, 2), p_tipo,
    regexp_replace(btrim(COALESCE(p_descricao, '')), '\s+', ' ', 'g'),
    v_uid, 'IGNORADA_MANUAL'
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('status', 'ok', 'id', v_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_import_lancamento(p_data date, p_descricao text, p_valor numeric, p_tipo text, p_conta_id uuid, p_user_id uuid, p_rateio_linhas jsonb DEFAULT NULL::jsonb, p_external_id text DEFAULT NULL::text, p_force_duplicate boolean DEFAULT false, p_occurrence_index integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_lancamento_id uuid;
  v_idem_key text;
  v_legacy_idem_key text;
  v_external_id text;
  v_company uuid;
  v_uid uuid;
  v_rateio_item jsonb;
  v_cat_id uuid;
  v_cc_id uuid;
  v_invalid_categories int;
  v_dup_id uuid;
  v_dup_created_at timestamptz;
  v_existing_count int;
  v_occurrence_index int;
  v_descricao_normalizada text;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;
  IF p_tipo NOT IN ('RECEITA', 'DESPESA', 'TRANSFERENCIA') THEN RAISE EXCEPTION 'INVALID_TYPE'; END IF;

  v_occurrence_index := GREATEST(COALESCE(p_occurrence_index, 0), 0);

  IF p_tipo <> 'TRANSFERENCIA' THEN
    IF p_rateio_linhas IS NULL OR jsonb_typeof(p_rateio_linhas) <> 'array' OR jsonb_array_length(p_rateio_linhas) = 0 THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'CATEGORY_REQUIRED: selecione uma categoria antes de conciliar';
    END IF;
    SELECT count(*) INTO v_invalid_categories
    FROM jsonb_array_elements(p_rateio_linhas) item
    LEFT JOIN public.fin_categorias c
      ON c.id = NULLIF(item->>'categoria_id', '')::uuid
      AND c.company_id = v_company AND c.ativo = true
    WHERE c.id IS NULL OR c.tipo <> lower(p_tipo);
    IF v_invalid_categories > 0 THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'CATEGORY_REQUIRED: categoria inválida ou incompatível com o tipo';
    END IF;
  END IF;

  v_external_id := NULLIF(btrim(p_external_id), '');
  IF v_external_id IS NOT NULL AND length(v_external_id) > 512 THEN
    RAISE EXCEPTION 'INVALID_EXTERNAL_ID';
  END IF;

  v_legacy_idem_key := md5(v_company::text || p_data::text || p_descricao || p_valor::text || p_tipo || p_conta_id::text);
  v_idem_key := CASE
    WHEN v_external_id IS NOT NULL
      THEN md5(concat_ws('|', v_company::text, p_conta_id::text, 'external', v_external_id))
    ELSE v_legacy_idem_key
  END;

  SELECT id INTO v_lancamento_id
  FROM public.fin_lancamentos
  WHERE idempotency_key = v_idem_key AND company_id = v_company;

  IF v_lancamento_id IS NULL AND v_external_id IS NOT NULL THEN
    SELECT id INTO v_lancamento_id
    FROM public.fin_lancamentos
    WHERE idempotency_key = v_legacy_idem_key AND company_id = v_company;

    IF v_lancamento_id IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM public.fin_conciliacao_vinculos v
        WHERE v.company_id = v_company
          AND v.conta_id = p_conta_id
          AND v.lancamento_id = v_lancamento_id
          AND v.external_id <> v_external_id
      ) THEN
        v_lancamento_id := NULL;
      ELSE
        UPDATE public.fin_lancamentos
        SET idempotency_key = v_idem_key
        WHERE id = v_lancamento_id;
      END IF;
    END IF;
  END IF;

  IF v_lancamento_id IS NOT NULL THEN
    UPDATE public.fin_lancamentos
    SET conciliado = true, conciliado_em = now(), conciliado_por = v_uid
    WHERE id = v_lancamento_id;
    RETURN jsonb_build_object('status', 'duplicate', 'lancamento_id', v_lancamento_id);
  END IF;

  -- Colapsa espaços internos antes de comparar: o MEMO do OFX varia o espaçamento
  -- entre exportações do mesmo extrato (ex.: Santander), então uma comparação exata
  -- de string (mesmo com lower+unaccent) deixa passar duplicata como se fosse nova.
  v_descricao_normalizada := regexp_replace(lower(public.immutable_unaccent(btrim(p_descricao))), '\s+', ' ', 'g');

  IF NOT p_force_duplicate THEN
    SELECT count(*) INTO v_existing_count
    FROM public.fin_lancamentos l
    WHERE l.company_id = v_company
      AND l.conta_id = p_conta_id
      AND l.tipo = p_tipo
      AND l.valor = p_valor
      AND l.data_pagamento = p_data
      AND regexp_replace(lower(public.immutable_unaccent(btrim(l.descricao))), '\s+', ' ', 'g') = v_descricao_normalizada
      AND l.origem IN ('conciliacao', 'espelho_cp', 'espelho_cr');

    IF v_occurrence_index < v_existing_count THEN
      SELECT l.id, l.created_at INTO v_dup_id, v_dup_created_at
      FROM public.fin_lancamentos l
      WHERE l.company_id = v_company
        AND l.conta_id = p_conta_id
        AND l.tipo = p_tipo
        AND l.valor = p_valor
        AND l.data_pagamento = p_data
        AND regexp_replace(lower(public.immutable_unaccent(btrim(l.descricao))), '\s+', ' ', 'g') = v_descricao_normalizada
        AND l.origem IN ('conciliacao', 'espelho_cp', 'espelho_cr')
      ORDER BY l.created_at ASC
      OFFSET v_occurrence_index
      LIMIT 1;

      IF v_dup_id IS NOT NULL THEN
        RETURN jsonb_build_object(
          'status', 'possible_duplicate',
          'lancamento_id', v_dup_id,
          'criado_em', v_dup_created_at
        );
      END IF;
    END IF;
  END IF;

  IF p_rateio_linhas IS NOT NULL AND jsonb_array_length(p_rateio_linhas) = 1 THEN
    v_cat_id := NULLIF(p_rateio_linhas->0->>'categoria_id', '')::uuid;
    v_cc_id := NULLIF(p_rateio_linhas->0->>'centro_custo_id', '')::uuid;
  END IF;

  INSERT INTO public.fin_lancamentos (
    tipo, valor, data_competencia, data_pagamento, descricao, conta_id,
    forma_pagamento, status, conciliado, conciliado_em, conciliado_por,
    created_by, idempotency_key, company_id, origem, categoria_id, centro_custo_id
  ) VALUES (
    p_tipo, p_valor, p_data, p_data, p_descricao, p_conta_id,
    'extrato', 'REALIZADO', true, now(), v_uid,
    v_uid, v_idem_key, v_company, 'conciliacao', v_cat_id, v_cc_id
  ) RETURNING id INTO v_lancamento_id;

  IF p_rateio_linhas IS NOT NULL AND jsonb_array_length(p_rateio_linhas) > 0 THEN
    FOR v_rateio_item IN SELECT * FROM jsonb_array_elements(p_rateio_linhas) LOOP
      INSERT INTO public.fin_lancamento_rateios (
        lancamento_id, categoria_id, centro_custo_id, valor, percentual, observacao, company_id
      ) VALUES (
        v_lancamento_id, (v_rateio_item->>'categoria_id')::uuid,
        NULLIF(v_rateio_item->>'centro_custo_id', '')::uuid,
        (v_rateio_item->>'valor')::numeric, (v_rateio_item->>'percentual')::numeric,
        v_rateio_item->>'observacao', v_company
      );
    END LOOP;
  END IF;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
  VALUES ('lancamentos', v_lancamento_id, 'reconcile_import', v_uid, v_company,
    jsonb_build_object('valor', p_valor, 'tipo', p_tipo, 'data', p_data,
      'descricao', p_descricao, 'categoria_id', v_cat_id, 'rateios', p_rateio_linhas,
      'external_id_used', v_external_id IS NOT NULL, 'category_validation', 'passed',
      'force_duplicate', p_force_duplicate, 'occurrence_index', v_occurrence_index));
  RETURN jsonb_build_object('status', 'ok', 'lancamento_id', v_lancamento_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_link_existing_lancamento(p_conta_id uuid, p_lancamento_id uuid, p_external_id text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_data_extrato date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_lanc record;
  v_conta_ajustada boolean := false;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.fin_contas WHERE id = p_conta_id AND company_id = v_company) THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária';
  END IF;

  SELECT * INTO v_lanc FROM public.fin_lancamentos
  WHERE id = p_lancamento_id AND company_id = v_company
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: lançamento'; END IF;

  IF v_lanc.status = 'CANCELADO' THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: lançamento cancelado não pode ser conciliado';
  END IF;

  IF v_lanc.conta_id IS NOT NULL
     AND v_lanc.conta_id <> p_conta_id
     AND COALESCE(v_lanc.conta_destino_id, '00000000-0000-0000-0000-000000000000'::uuid) <> p_conta_id THEN
    RAISE EXCEPTION 'CONTA_DIVERGENTE: o lançamento pertence a outra conta bancária';
  END IF;

  IF v_lanc.tipo <> 'TRANSFERENCIA'
     AND NOT public.fin_entity_has_category(v_lanc.id, v_lanc.categoria_id, v_lanc.company_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'CATEGORY_REQUIRED: o lançamento está sem categoria — corrija antes de conciliar';
  END IF;

  IF v_lanc.conta_id IS NULL THEN
    UPDATE public.fin_lancamentos
    SET conta_id = p_conta_id,
        conciliado = true,
        conciliado_em = now(),
        conciliado_por = v_uid,
        justificativa_edicao = 'Conta bancária definida na conciliação do extrato',
        updated_at = now()
    WHERE id = p_lancamento_id AND company_id = v_company;
    v_conta_ajustada := true;
  ELSIF v_lanc.conciliado IS DISTINCT FROM true THEN
    UPDATE public.fin_lancamentos
    SET conciliado = true, conciliado_em = now(), conciliado_por = v_uid, updated_at = now()
    WHERE id = p_lancamento_id AND company_id = v_company;
  END IF;

  IF NULLIF(btrim(p_external_id), '') IS NOT NULL AND p_tipo IN ('RECEITA', 'DESPESA') THEN
    PERFORM public.reconcile_bind_extrato(p_conta_id, p_external_id, p_tipo, p_lancamento_id);
  END IF;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
  VALUES ('lancamentos', p_lancamento_id, 'reconcile_link_existing', v_uid, v_company,
    jsonb_build_object('conta_id', p_conta_id, 'external_id', p_external_id,
      'origem_lancamento', v_lanc.origem, 'conta_ajustada', v_conta_ajustada,
      'data_extrato', p_data_extrato));

  RETURN jsonb_build_object(
    'status', 'ok',
    'lancamento_id', p_lancamento_id,
    'origem', v_lanc.origem,
    'conta_ajustada', v_conta_ajustada
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_neutralize_contamax(p_conta_id uuid, p_linhas jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_uid uuid;
  v_bank text;
  v_bank_digits text;
  v_line record;
  v_data date;
  v_valor numeric;
  v_tipo text;
  v_descricao text;
  v_descricao_normalizada text;
  v_external_id text;
  v_processed integer;
  v_inserted integer;
  v_audited integer;
BEGIN
  v_company_id := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF p_linhas IS NULL OR jsonb_typeof(p_linhas) <> 'array' THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: p_linhas deve ser um array JSON';
  END IF;

  v_processed := jsonb_array_length(p_linhas);
  IF v_processed > 10000 THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: máximo de 10000 linhas por lote';
  END IF;
  IF v_processed = 0 THEN
    RETURN jsonb_build_object('status', 'ok', 'processed', 0, 'inserted', 0, 'existing', 0);
  END IF;

  SELECT lower(public.immutable_unaccent(btrim(COALESCE(c.banco, '')))),
         regexp_replace(COALESCE(c.banco, ''), '\D', '', 'g')
  INTO v_bank, v_bank_digits
  FROM public.fin_contas c
  WHERE c.id = p_conta_id
    AND c.company_id = v_company_id
    AND c.ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária ativa';
  END IF;
  IF v_bank_digits <> '033' AND v_bank NOT LIKE '%santander%' THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: ContaMax automático só é aceito em conta Santander';
  END IF;

  -- Validate every row before the all-or-nothing INSERT. Cast failures are
  -- converted into the same stable validation error instead of leaking a
  -- partial or obscure PostgreSQL exception to the client.
  FOR v_line IN
    SELECT value, ordinality
    FROM jsonb_array_elements(p_linhas) WITH ORDINALITY
  LOOP
    BEGIN
      v_data := (v_line.value ->> 'data')::date;
      v_valor := round(abs((v_line.value ->> 'valor')::numeric), 2);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'VALIDATION_ERROR: data/valor inválido na linha %', v_line.ordinality;
    END;

    v_tipo := upper(btrim(COALESCE(v_line.value ->> 'tipo', '')));
    v_descricao := regexp_replace(btrim(COALESCE(v_line.value ->> 'descricao', '')), '\s+', ' ', 'g');
    v_descricao_normalizada := lower(public.immutable_unaccent(v_descricao));
    v_external_id := NULLIF(btrim(v_line.value ->> 'external_id'), '');

    IF v_valor <= 0 OR v_tipo NOT IN ('RECEITA', 'DESPESA') OR v_descricao = '' THEN
      RAISE EXCEPTION 'VALIDATION_ERROR: linha ContaMax inválida na posição %', v_line.ordinality;
    END IF;
    IF v_external_id IS NOT NULL AND length(v_external_id) > 512 THEN
      RAISE EXCEPTION 'INVALID_EXTERNAL_ID';
    END IF;
    IF NOT (
      (v_tipo = 'DESPESA' AND v_descricao_normalizada LIKE '%aplicacao%contamax%')
      OR (v_tipo = 'RECEITA' AND v_descricao_normalizada LIKE '%resgate%contamax%')
    ) THEN
      RAISE EXCEPTION 'VALIDATION_ERROR: somente aplicação/resgate ContaMax é movimentação interna (linha %)', v_line.ordinality;
    END IF;
  END LOOP;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_company_id::text || ':contamax:' || p_conta_id::text, 0)
  );

  WITH input_rows AS (
    SELECT
      ordinality,
      (value ->> 'data')::date AS data,
      round(abs((value ->> 'valor')::numeric), 2) AS valor,
      upper(btrim(value ->> 'tipo')) AS tipo,
      regexp_replace(btrim(value ->> 'descricao'), '\s+', ' ', 'g') AS descricao,
      NULLIF(btrim(value ->> 'external_id'), '') AS external_id
    FROM jsonb_array_elements(p_linhas) WITH ORDINALITY
  ), numbered AS (
    SELECT
      input_rows.*,
      row_number() OVER (
        PARTITION BY
          data,
          valor,
          tipo,
          lower(public.immutable_unaccent(descricao))
        ORDER BY ordinality
      ) - 1 AS occurrence_index
    FROM input_rows
  ), inserted AS (
    INSERT INTO public.fin_conciliacao_ignoradas (
      company_id, conta_id, data, valor, tipo, descricao,
      ignorado_por, tratamento, occurrence_index, external_id
    )
    SELECT
      v_company_id, p_conta_id, n.data, n.valor, n.tipo, n.descricao,
      v_uid, 'MOVIMENTACAO_INTERNA_CONTAMAX', n.occurrence_index, n.external_id
    FROM numbered n
    ON CONFLICT (
      company_id, conta_id, data, valor, tipo, descricao_unaccent, occurrence_index
    ) WHERE tratamento = 'MOVIMENTACAO_INTERNA_CONTAMAX'
    DO NOTHING
    RETURNING id, company_id, conta_id, data, valor, tipo, descricao, occurrence_index, external_id
  ), audited AS (
    INSERT INTO public.fin_audit_logs (
      entidade, entidade_id, acao, user_id, company_id, depois
    )
    SELECT
      'conciliacao_interna', i.id, 'neutralizar_contamax', v_uid, i.company_id,
      jsonb_build_object(
        'conta_id', i.conta_id,
        'data', i.data,
        'valor', i.valor,
        'tipo', i.tipo,
        'descricao', i.descricao,
        'occurrence_index', i.occurrence_index,
        'external_id_used', i.external_id IS NOT NULL,
        'financial_effect', 0
      )
    FROM inserted i
    RETURNING id
  )
  SELECT
    (SELECT count(*)::integer FROM inserted),
    (SELECT count(*)::integer FROM audited)
  INTO v_inserted, v_audited;

  IF v_inserted <> v_audited THEN
    RAISE EXCEPTION 'CONTAMAX_AUDIT_MISMATCH';
  END IF;

  RETURN jsonb_build_object(
    'status', 'ok',
    'processed', v_processed,
    'inserted', v_inserted,
    'existing', v_processed - v_inserted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_pay_conta_pagar(p_conta_pagar_id uuid, p_conta_bancaria_id uuid, p_data_pagamento date, p_user_id uuid, p_valor_extrato numeric DEFAULT NULL::numeric, p_ajuste_tipo text DEFAULT NULL::text, p_ajuste_categoria_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_cp record;
  v_lancamento_id uuid;
  v_next_cp_id uuid;
  v_existing_lanc_id uuid;
  v_existing_conta_id uuid;
  v_found boolean;
  v_diff numeric;
  v_ajuste_id uuid;
  v_ajuste_tipo text;
  v_ajuste_lanc_tipo text;
  v_ajuste_cat_id uuid;
  v_cat_tipo text;
  v_rotulo text;
BEGIN
  v_company := public.assert_tenant();
  v_uid := COALESCE(auth.uid(), p_user_id);

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF p_conta_bancaria_id IS NULL THEN
    RAISE EXCEPTION 'CONTA_OBRIGATORIA: informe a conta bancária do extrato';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.fin_contas WHERE id = p_conta_bancaria_id AND company_id = v_company
  ) THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária não pertence à empresa';
  END IF;

  SELECT * INTO v_cp
  FROM public.fin_contas_pagar
  WHERE id = p_conta_pagar_id AND company_id = v_company
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: conta a pagar %', p_conta_pagar_id;
  END IF;

  IF v_cp.status = 'PAGO' THEN
    RETURN jsonb_build_object(
      'status', 'noop',
      'message', 'Conta já está paga',
      'lancamento_id', v_cp.lancamento_id,
      'data_pagamento', v_cp.data_pagamento
    );
  END IF;

  IF v_cp.status NOT IN ('APROVADO', 'AGUARDANDO_APROVACAO') THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: %', v_cp.status;
  END IF;

  v_diff := 0;
  IF p_valor_extrato IS NOT NULL THEN
    v_diff := round(p_valor_extrato - v_cp.valor, 2);

    IF abs(v_diff) >= 0.01 THEN
      v_ajuste_tipo := upper(btrim(COALESCE(p_ajuste_tipo, '')));

      IF v_ajuste_tipo NOT IN ('JUROS', 'TARIFA', 'DESCONTO') THEN
        RAISE EXCEPTION
          'DIVERGENCIA_VALOR: extrato % x boleto % (diferença %). Classifique como JUROS, TARIFA ou DESCONTO.',
          p_valor_extrato, v_cp.valor, v_diff;
      END IF;

      IF v_diff > 0 AND v_ajuste_tipo = 'DESCONTO' THEN
        RAISE EXCEPTION 'AJUSTE_INVALIDO: o extrato é maior que o boleto — a diferença é JUROS ou TARIFA, não desconto.';
      END IF;
      IF v_diff < 0 AND v_ajuste_tipo <> 'DESCONTO' THEN
        RAISE EXCEPTION 'AJUSTE_INVALIDO: o extrato é menor que o boleto — a diferença é DESCONTO.';
      END IF;

      v_ajuste_lanc_tipo := CASE WHEN v_diff > 0 THEN 'DESPESA' ELSE 'RECEITA' END;

      v_ajuste_cat_id := p_ajuste_categoria_id;
      IF v_ajuste_cat_id IS NULL AND v_ajuste_tipo = 'DESCONTO' THEN
        v_ajuste_cat_id := public.fin_get_categoria_desconto_baixa(v_company);
      END IF;

      SELECT c.tipo INTO v_cat_tipo
      FROM public.fin_categorias c
      WHERE c.id = v_ajuste_cat_id AND c.company_id = v_company AND c.ativo = true;

      IF v_cat_tipo IS NULL THEN
        RAISE EXCEPTION 'CATEGORY_REQUIRED: selecione a categoria da diferença (%).', v_ajuste_tipo;
      END IF;
      IF v_cat_tipo <> lower(v_ajuste_lanc_tipo) THEN
        RAISE EXCEPTION 'CATEGORY_REQUIRED: a categoria da diferença precisa ser de %.', lower(v_ajuste_lanc_tipo);
      END IF;

      IF v_ajuste_tipo = 'DESCONTO'
         AND NOT public.fin_categoria_fora_do_resultado(v_ajuste_cat_id, v_company) THEN
        RAISE EXCEPTION
          'CATEGORIA_OPERACIONAL: o desconto obtido não pode entrar como receita operacional — use uma categoria sob RECEITAS NÃO OPERACIONAIS (ex.: "Descontos Obtidos"), senão ele soma no faturamento do DRE.';
      END IF;
    END IF;
  END IF;

  v_existing_lanc_id := v_cp.lancamento_id;
  IF v_existing_lanc_id IS NULL THEN
    SELECT id INTO v_existing_lanc_id
    FROM public.fin_lancamentos
    WHERE referencia_modulo = 'contas_pagar'
      AND referencia_id = p_conta_pagar_id::text
      AND company_id = v_company
      AND status <> 'CANCELADO'
    LIMIT 1;
  END IF;

  v_found := false;
  IF v_existing_lanc_id IS NOT NULL THEN
    SELECT conta_id, true INTO v_existing_conta_id, v_found
    FROM public.fin_lancamentos
    WHERE id = v_existing_lanc_id AND company_id = v_company AND status <> 'CANCELADO';
  END IF;

  IF v_found THEN
    UPDATE public.fin_contas_pagar
    SET status = 'PAGO', data_pagamento = p_data_pagamento, valor_pago = v_cp.valor,
        lancamento_id = v_existing_lanc_id, conta_id = p_conta_bancaria_id, updated_at = now()
    WHERE id = p_conta_pagar_id AND company_id = v_company;

    UPDATE public.fin_lancamentos
    SET conciliado = true, conciliado_em = now(), conciliado_por = v_uid,
        conta_id = p_conta_bancaria_id,
        data_pagamento = p_data_pagamento, status = 'REALIZADO',
        justificativa_edicao = CASE
          WHEN v_existing_conta_id IS DISTINCT FROM p_conta_bancaria_id
            THEN 'Conta bancária definida na conciliação do extrato'
          ELSE justificativa_edicao
        END
    WHERE id = v_existing_lanc_id AND company_id = v_company;

    INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
    VALUES ('contas_pagar', p_conta_pagar_id, 'reconcile_pay_existing', v_uid, v_company,
      jsonb_build_object('lancamento_id', v_existing_lanc_id, 'reused', true));

    RETURN jsonb_build_object('status', 'ok', 'lancamento_id', v_existing_lanc_id,
      'reused', true, 'recorrente', v_cp.recorrente);
  END IF;

  UPDATE public.fin_contas_pagar
  SET status = 'PAGO', data_pagamento = p_data_pagamento, valor_pago = v_cp.valor,
      conta_id = p_conta_bancaria_id, updated_at = now()
  WHERE id = p_conta_pagar_id AND company_id = v_company;

  INSERT INTO public.fin_lancamentos (
    tipo, valor, data_competencia, data_pagamento, descricao,
    categoria_id, centro_custo_id, conta_id,
    forma_pagamento, status, conciliado, conciliado_em, conciliado_por,
    created_by, referencia_modulo, referencia_id, company_id, origem
  )
  VALUES (
    'DESPESA', v_cp.valor,
    COALESCE(v_cp.data_competencia, v_cp.data_vencimento, p_data_pagamento), p_data_pagamento, v_cp.descricao,
    v_cp.categoria_id, v_cp.centro_custo_id, p_conta_bancaria_id,
    v_cp.forma_pagamento, 'REALIZADO', true, now(), v_uid,
    v_uid, 'contas_pagar', p_conta_pagar_id::text, v_cp.company_id, 'espelho_cp'
  )
  RETURNING id INTO v_lancamento_id;

  INSERT INTO public.fin_lancamento_rateios (lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id)
  SELECT v_lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id
  FROM public.fin_lancamento_rateios
  WHERE lancamento_id = p_conta_pagar_id AND company_id = v_company;

  UPDATE public.fin_contas_pagar SET lancamento_id = v_lancamento_id
  WHERE id = p_conta_pagar_id AND company_id = v_company;

  IF abs(v_diff) >= 0.01 THEN
    v_rotulo := CASE v_ajuste_tipo
      WHEN 'JUROS' THEN 'Juros'
      WHEN 'TARIFA' THEN 'Tarifa bancária'
      ELSE 'Desconto'
    END;

    INSERT INTO public.fin_lancamentos (
      tipo, valor, data_competencia, data_pagamento, descricao,
      categoria_id, conta_id, forma_pagamento, status,
      conciliado, conciliado_em, conciliado_por,
      created_by, referencia_modulo, referencia_id, company_id, origem
    )
    VALUES (
      v_ajuste_lanc_tipo, abs(v_diff), p_data_pagamento, p_data_pagamento,
      v_rotulo || ' — ' || v_cp.descricao,
      v_ajuste_cat_id, p_conta_bancaria_id, v_cp.forma_pagamento, 'REALIZADO',
      true, now(), v_uid,
      v_uid, 'contas_pagar', p_conta_pagar_id::text, v_company, 'ajuste_pagamento'
    )
    RETURNING id INTO v_ajuste_id;
  END IF;

  IF v_cp.recorrente AND v_cp.recorrencia_config IS NOT NULL THEN
    DECLARE
      v_freq text; v_max_parcelas int; v_geradas int; v_nova_data date;
    BEGIN
      v_freq := COALESCE(v_cp.recorrencia_config->>'frequencia', 'mensal');
      v_max_parcelas := (v_cp.recorrencia_config->>'parcelas')::int;
      v_geradas := COALESCE((v_cp.recorrencia_config->>'parcelas_geradas')::int, 0) + 1;
      IF v_max_parcelas IS NULL OR v_geradas < v_max_parcelas THEN
        IF v_freq = 'semanal' THEN v_nova_data := v_cp.data_vencimento + interval '7 days';
        ELSIF v_freq = 'quinzenal' THEN v_nova_data := v_cp.data_vencimento + interval '15 days';
        ELSE v_nova_data := v_cp.data_vencimento + interval '1 month'; END IF;
        INSERT INTO public.fin_contas_pagar (
          descricao, valor, data_vencimento, status, categoria_id, centro_custo_id, conta_id, fornecedor,
          forma_pagamento, recorrente, lancamento_pai_id, recorrencia_config, parcela_atual, parcela_total,
          created_by, company_id
        ) VALUES (
          v_cp.descricao, v_cp.valor, v_nova_data, 'AGUARDANDO_APROVACAO',
          v_cp.categoria_id, v_cp.centro_custo_id, v_cp.conta_id, v_cp.fornecedor,
          v_cp.forma_pagamento, true, COALESCE(v_cp.lancamento_pai_id, v_cp.id),
          jsonb_build_object('frequencia', v_freq, 'parcelas', v_max_parcelas, 'parcelas_geradas', v_geradas),
          COALESCE(v_cp.parcela_atual, 0) + 1, v_max_parcelas, v_uid, v_company
        ) RETURNING id INTO v_next_cp_id;
      END IF;
    END;
  END IF;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
  VALUES ('contas_pagar', p_conta_pagar_id, 'reconcile_pay', v_uid, v_company,
    jsonb_build_object('lancamento_id', v_lancamento_id, 'valor', v_cp.valor,
      'valor_extrato', p_valor_extrato, 'diferenca', v_diff, 'ajuste_tipo', v_ajuste_tipo,
      'ajuste_categoria_id', v_ajuste_cat_id, 'ajuste_lancamento_id', v_ajuste_id,
      'data_pagamento', p_data_pagamento, 'recorrente', v_cp.recorrente, 'next_cp_id', v_next_cp_id));

  RETURN jsonb_build_object('status', 'ok', 'lancamento_id', v_lancamento_id,
    'next_cp_id', v_next_cp_id, 'recorrente', v_cp.recorrente,
    'ajuste_lancamento_id', v_ajuste_id, 'diferenca', v_diff);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_receive_conta_receber(p_conta_receber_id uuid, p_conta_bancaria_id uuid, p_data_recebimento date, p_user_id uuid, p_valor_extrato numeric DEFAULT NULL::numeric, p_ajuste_tipo text DEFAULT NULL::text, p_ajuste_categoria_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_cr record;
  v_lancamento_id uuid;
  v_next_cr_id uuid;
  v_uid uuid;
  v_company uuid;
  v_existing_lanc_id uuid;
  v_existing_conta_id uuid;
  v_conta_exists boolean;
  v_found boolean;
  v_reused boolean;
  v_diff numeric;
  v_ajuste_id uuid;
  v_ajuste_tipo text;
  v_ajuste_lanc_tipo text;
  v_ajuste_cat_id uuid;
  v_cat_tipo text;
  v_rotulo text;
BEGIN
  v_company := public.assert_tenant();
  v_uid := COALESCE(auth.uid(), p_user_id);
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  IF p_conta_bancaria_id IS NULL THEN
    RAISE EXCEPTION 'CONTA_OBRIGATORIA: informe a conta bancária do extrato';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.fin_contas WHERE id = p_conta_bancaria_id AND company_id = v_company
  ) THEN
    RAISE EXCEPTION 'NOT_FOUND: conta bancária não pertence à empresa';
  END IF;

  SELECT * INTO v_cr
  FROM public.fin_contas_receber
  WHERE id = p_conta_receber_id AND company_id = v_company
  FOR UPDATE;

  IF v_cr IS NULL THEN RAISE EXCEPTION 'Conta a receber não encontrada'; END IF;

  IF v_cr.status = 'RECEBIDO' THEN
    RETURN jsonb_build_object('status', 'noop', 'message', 'Conta já foi recebida', 'lancamento_id', v_cr.lancamento_id);
  END IF;
  IF v_cr.status != 'A_RECEBER' THEN
    RAISE EXCEPTION 'Status inválido para recebimento: %', v_cr.status;
  END IF;

  -- Divergência entre o valor do título e o que efetivamente entrou no banco —
  -- espelho de reconcile_pay_conta_pagar com o sinal invertido: receber A MENOS
  -- que o título é desconto concedido ao cliente (DESPESA não operacional, senão
  -- infla despesas operacionais no DRE); receber A MAIS é juros/multa (RECEITA).
  v_diff := 0;
  IF p_valor_extrato IS NOT NULL THEN
    v_diff := round(p_valor_extrato - v_cr.valor, 2);

    IF abs(v_diff) >= 0.01 THEN
      v_ajuste_tipo := upper(btrim(COALESCE(p_ajuste_tipo, '')));

      IF v_ajuste_tipo NOT IN ('JUROS', 'TARIFA', 'DESCONTO') THEN
        RAISE EXCEPTION
          'DIVERGENCIA_VALOR: extrato % x título % (diferença %). Classifique como JUROS, TARIFA ou DESCONTO.',
          p_valor_extrato, v_cr.valor, v_diff;
      END IF;

      IF v_diff < 0 AND v_ajuste_tipo <> 'DESCONTO' THEN
        RAISE EXCEPTION 'AJUSTE_INVALIDO: o extrato é menor que o título — a diferença é DESCONTO.';
      END IF;
      IF v_diff > 0 AND v_ajuste_tipo = 'DESCONTO' THEN
        RAISE EXCEPTION 'AJUSTE_INVALIDO: o extrato é maior que o título — a diferença é JUROS ou TARIFA, não desconto.';
      END IF;

      v_ajuste_lanc_tipo := CASE WHEN v_diff < 0 THEN 'DESPESA' ELSE 'RECEITA' END;

      v_ajuste_cat_id := p_ajuste_categoria_id;
      IF v_ajuste_cat_id IS NULL AND v_ajuste_tipo = 'DESCONTO' THEN
        v_ajuste_cat_id := public.fin_get_categoria_desconto_concedido(v_company);
      END IF;

      SELECT c.tipo INTO v_cat_tipo
      FROM public.fin_categorias c
      WHERE c.id = v_ajuste_cat_id AND c.company_id = v_company AND c.ativo = true;

      IF v_cat_tipo IS NULL THEN
        RAISE EXCEPTION 'CATEGORY_REQUIRED: selecione a categoria da diferença (%).', v_ajuste_tipo;
      END IF;
      IF v_cat_tipo <> lower(v_ajuste_lanc_tipo) THEN
        RAISE EXCEPTION 'CATEGORY_REQUIRED: a categoria da diferença precisa ser de %.', lower(v_ajuste_lanc_tipo);
      END IF;

      IF v_ajuste_tipo = 'DESCONTO'
         AND NOT public.fin_categoria_fora_do_resultado(v_ajuste_cat_id, v_company) THEN
        RAISE EXCEPTION
          'CATEGORIA_OPERACIONAL: o desconto concedido não pode entrar como despesa operacional — use uma categoria sob DESPESAS NÃO OPERACIONAIS (ex.: "Descontos Concedidos"), senão ele infla as despesas do DRE.';
      END IF;
    END IF;
  END IF;

  v_existing_lanc_id := v_cr.lancamento_id;
  IF v_existing_lanc_id IS NULL THEN
    SELECT id INTO v_existing_lanc_id
    FROM public.fin_lancamentos
    WHERE referencia_modulo = 'contas_receber'
      AND referencia_id = p_conta_receber_id::text
      AND company_id = v_company
      AND status <> 'CANCELADO'
    LIMIT 1;
  END IF;

  v_found := false;
  IF v_existing_lanc_id IS NOT NULL THEN
    SELECT conta_id, true INTO v_existing_conta_id, v_found
    FROM public.fin_lancamentos
    WHERE id = v_existing_lanc_id AND company_id = v_company AND status <> 'CANCELADO';
  END IF;

  v_reused := COALESCE(v_found, false);

  IF v_reused THEN
    UPDATE public.fin_contas_receber
    SET status = 'RECEBIDO', data_recebimento = p_data_recebimento, valor_recebido = v_cr.valor,
        lancamento_id = v_existing_lanc_id, updated_at = now()
    WHERE id = p_conta_receber_id AND company_id = v_company;

    UPDATE public.fin_lancamentos
    SET conciliado = true, conciliado_em = now(), conciliado_por = v_uid,
        conta_id = p_conta_bancaria_id,
        data_pagamento = p_data_recebimento, status = 'REALIZADO',
        justificativa_edicao = CASE
          WHEN v_existing_conta_id IS DISTINCT FROM p_conta_bancaria_id
            THEN 'Conta bancária definida na conciliação do extrato'
          ELSE justificativa_edicao
        END
    WHERE id = v_existing_lanc_id AND company_id = v_company;

    v_lancamento_id := v_existing_lanc_id;
  ELSE
    UPDATE public.fin_contas_receber
    SET status = 'RECEBIDO', data_recebimento = p_data_recebimento, valor_recebido = v_cr.valor, updated_at = now()
    WHERE id = p_conta_receber_id AND company_id = v_company;

    INSERT INTO public.fin_lancamentos (
      tipo, valor, data_competencia, data_pagamento, descricao,
      categoria_id, centro_custo_id, conta_id,
      forma_pagamento, status, conciliado, conciliado_em, conciliado_por,
      created_by, referencia_modulo, referencia_id, company_id, origem
    )
    VALUES (
      'RECEITA', v_cr.valor,
      COALESCE(v_cr.data_competencia, v_cr.data_vencimento, p_data_recebimento), p_data_recebimento, v_cr.descricao,
      v_cr.categoria_id, v_cr.centro_custo_id, p_conta_bancaria_id,
      v_cr.forma_pagamento, 'REALIZADO', true, now(), v_uid,
      v_uid, 'contas_receber', p_conta_receber_id::text, v_company, 'espelho_cr'
    )
    RETURNING id INTO v_lancamento_id;

    INSERT INTO public.fin_lancamento_rateios (lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id)
    SELECT v_lancamento_id, categoria_id, centro_custo_id, valor, percentual, company_id
    FROM public.fin_lancamento_rateios
    WHERE lancamento_id = p_conta_receber_id AND company_id = v_company;

    UPDATE public.fin_contas_receber SET lancamento_id = v_lancamento_id WHERE id = p_conta_receber_id AND company_id = v_company;
  END IF;

  -- Ajuste (juros/tarifa/desconto) sempre entra, reaproveitando lançamento ou não —
  -- mesmo princípio da correção em reconcile_pay_conta_pagar.
  IF abs(v_diff) >= 0.01 THEN
    v_rotulo := CASE v_ajuste_tipo
      WHEN 'JUROS' THEN 'Juros'
      WHEN 'TARIFA' THEN 'Tarifa bancária'
      ELSE 'Desconto concedido'
    END;

    INSERT INTO public.fin_lancamentos (
      tipo, valor, data_competencia, data_pagamento, descricao,
      categoria_id, conta_id, forma_pagamento, status,
      conciliado, conciliado_em, conciliado_por,
      created_by, referencia_modulo, referencia_id, company_id, origem
    )
    VALUES (
      v_ajuste_lanc_tipo, abs(v_diff), p_data_recebimento, p_data_recebimento,
      v_rotulo || ' — ' || v_cr.descricao,
      v_ajuste_cat_id, p_conta_bancaria_id, v_cr.forma_pagamento, 'REALIZADO',
      true, now(), v_uid,
      v_uid, 'contas_receber', p_conta_receber_id::text, v_company, 'ajuste_recebimento'
    )
    RETURNING id INTO v_ajuste_id;
  END IF;

  IF NOT v_reused AND v_cr.recorrente AND v_cr.recorrencia_config IS NOT NULL THEN
    DECLARE
      v_freq text; v_max_parcelas int; v_geradas int; v_nova_data date;
    BEGIN
      v_freq := COALESCE(v_cr.recorrencia_config->>'frequencia', 'mensal');
      v_max_parcelas := (v_cr.recorrencia_config->>'parcelas')::int;
      v_geradas := COALESCE((v_cr.recorrencia_config->>'parcelas_geradas')::int, 0) + 1;
      IF v_max_parcelas IS NULL OR v_geradas < v_max_parcelas THEN
        IF v_freq = 'semanal' THEN v_nova_data := v_cr.data_vencimento::date + interval '7 days';
        ELSIF v_freq = 'quinzenal' THEN v_nova_data := v_cr.data_vencimento::date + interval '15 days';
        ELSE v_nova_data := v_cr.data_vencimento::date + interval '1 month'; END IF;
        INSERT INTO public.fin_contas_receber (
          descricao, valor, data_vencimento, status, categoria_id, centro_custo_id, conta_id, cliente,
          forma_pagamento, recorrente, lancamento_pai_id, recorrencia_config, parcela_atual, parcela_total, created_by, company_id
        ) VALUES (
          v_cr.descricao, v_cr.valor, v_nova_data, 'A_RECEBER',
          v_cr.categoria_id, v_cr.centro_custo_id, v_cr.conta_id, v_cr.cliente,
          v_cr.forma_pagamento, true, COALESCE(v_cr.lancamento_pai_id, v_cr.id),
          jsonb_build_object('frequencia', v_freq, 'parcelas', v_max_parcelas, 'parcelas_geradas', v_geradas),
          COALESCE(v_cr.parcela_atual, 0) + 1, v_max_parcelas, v_uid, v_company
        ) RETURNING id INTO v_next_cr_id;
      END IF;
    END;
  END IF;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, depois)
  VALUES ('contas_receber', p_conta_receber_id,
    CASE WHEN v_reused THEN 'reconcile_receive_existing' ELSE 'reconcile_receive' END,
    v_uid, v_company,
    jsonb_build_object('lancamento_id', v_lancamento_id, 'valor', v_cr.valor,
      'valor_extrato', p_valor_extrato, 'diferenca', v_diff, 'ajuste_tipo', v_ajuste_tipo,
      'ajuste_categoria_id', v_ajuste_cat_id, 'ajuste_lancamento_id', v_ajuste_id,
      'data_recebimento', p_data_recebimento, 'recorrente', v_cr.recorrente, 'next_cr_id', v_next_cr_id,
      'reused', v_reused));

  RETURN jsonb_build_object('status', 'ok', 'lancamento_id', v_lancamento_id,
    'next_cr_id', v_next_cr_id, 'recorrente', v_cr.recorrente,
    'ajuste_lancamento_id', v_ajuste_id, 'diferenca', v_diff, 'reused', v_reused);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_reconsiderar_ignorada(p_ignorada_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_uid uuid;
  v_tratamento text;
  v_deleted_id uuid;
BEGIN
  v_company_id := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:conciliacao:reconcile',
    'finance:manage',
    'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  SELECT i.tratamento
  INTO v_tratamento
  FROM public.fin_conciliacao_ignoradas i
  WHERE i.id = p_ignorada_id
    AND i.company_id = v_company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND';
  END IF;
  IF v_tratamento = 'MOVIMENTACAO_INTERNA_CONTAMAX' THEN
    RAISE EXCEPTION 'INTERNAL_MOVEMENT_CANNOT_BE_RECONSIDERED';
  END IF;

  DELETE FROM public.fin_conciliacao_ignoradas
  WHERE id = p_ignorada_id
    AND company_id = v_company_id
    AND tratamento = 'IGNORADA_MANUAL'
  RETURNING id INTO v_deleted_id;

  IF v_deleted_id IS NULL THEN
    RAISE EXCEPTION 'NOT_FOUND';
  END IF;

  RETURN jsonb_build_object('status', 'ok', 'id', v_deleted_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_materialized_views()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_start timestamptz; 
  v_results jsonb := '[]'::jsonb; 
  v_mv text; 
  v_elapsed numeric;
  -- List now includes schema prefix
  v_views text[] := ARRAY[
    'reporting.mv_fin_dre_mensal',
    'reporting.mv_fin_fluxo_caixa_diario',
    'reporting.mv_consumo_itens_semana',
    'reporting.mv_giro_estoque',
    'reporting.mv_pedidos_status_resumo'
  ];
BEGIN
  FOREACH v_mv IN ARRAY v_views LOOP
    v_start := clock_timestamp();
    -- Dynamic SQL needs fully qualified names, which we provided in the array
    EXECUTE 'REFRESH MATERIALIZED VIEW ' || v_mv;
    v_elapsed := EXTRACT(EPOCH FROM clock_timestamp() - v_start) * 1000;

    v_results := v_results || jsonb_build_object('view', v_mv, 'ms', round(v_elapsed::numeric, 1));

    -- Log slow refreshes (>800ms)
    IF v_elapsed > 800 THEN
      INSERT INTO audit_logs (source, module, entity, action, metadata, success)
      VALUES ('db', 'perf', v_mv, 'SLOW_QUERY', jsonb_build_object('type', 'mv_refresh', 'duration_ms', round(v_elapsed::numeric, 1)), true);
    END IF;
  END LOOP;

  -- Clear cache
  DELETE FROM dashboard_cache WHERE expires_at < now();

  -- Log job completion
  INSERT INTO audit_logs (source, module, entity, action, metadata, success)
  VALUES ('db', 'system', 'materialized_views', 'JOB_RUN', v_results, true);

  RETURN v_results;
END; 
$function$

CREATE OR REPLACE FUNCTION public.reject_ponto_record(p_id uuid, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record rh_ponto_registros%ROWTYPE;
  v_caller uuid;
  v_company uuid;
BEGIN
  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION '401: Não autenticado';
  END IF;

  -- Tenant resolution
  v_company := public.assert_tenant();
  IF v_company IS NULL OR v_company = '00000000-0000-0000-0000-000000000001'::uuid THEN
    RAISE EXCEPTION '403: Tenant não resolvido';
  END IF;

  -- Permission check
  IF NOT has_permission(v_caller, 'rh:ponto:manage') THEN
    RAISE EXCEPTION '403: Sem permissão rh:ponto:manage';
  END IF;

  -- Lock the record
  SELECT * INTO v_record
  FROM rh_ponto_registros
  WHERE id = p_id AND company_id = v_company
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '404: Registro não encontrado';
  END IF;

  -- Idempotency: already rejected
  IF v_record.status = 'REJEITADO' THEN
    RETURN jsonb_build_object('status', 'noop', 'message', 'Já rejeitado');
  END IF;

  -- Reject
  UPDATE rh_ponto_registros SET
    status = 'REJEITADO',
    rejeitado_por = v_caller,
    rejeitado_em = now(),
    motivo_rejeicao = COALESCE(NULLIF(p_reason, ''), 'Rejeitado pelo gestor'),
    updated_at = now()
  WHERE id = p_id;

  -- Audit (entidade_id é uuid — nunca ::text)
  INSERT INTO rh_audit_log (acao, entidade, entidade_id, company_id, user_id, antes, depois)
  VALUES (
    'rejeitar_ponto',
    'rh_ponto_registros',
    p_id,
    v_company,
    v_caller,
    jsonb_build_object('status', v_record.status, 'aprovado', v_record.aprovado),
    jsonb_build_object('status', 'REJEITADO', 'motivo', p_reason)
  );

  RETURN jsonb_build_object('status', 'ok', 'message', 'Ponto rejeitado');
END;
$function$

CREATE OR REPLACE FUNCTION public.reopen_inventory(p_id uuid, p_justificativa text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_user_id uuid; v_inv record; v_before jsonb; v_after jsonb; v_deleted_moves int;
BEGIN
  v_tenant := assert_tenant(); v_user_id := auth.uid();
  IF NOT has_any_permission(v_user_id, ARRAY['inventario:auditoria:edit', 'system:global:manage']) THEN RAISE EXCEPTION 'Forbidden: inventario:auditoria:edit required'; END IF;
  SELECT * INTO v_inv FROM inventarios WHERE id = p_id AND company_id = v_tenant AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inventário não encontrado'; END IF;
  IF v_inv.status NOT IN ('FINALIZADO', 'SOB_ANALISE') THEN RAISE EXCEPTION 'Só é possível reabrir inventários FINALIZADO ou SOB_ANALISE (atual: %)', v_inv.status; END IF;
  v_before := jsonb_build_object('status', v_inv.status, 'finalizado_em', v_inv.finalizado_em, 'finalizado_por', v_inv.finalizado_por);

  -- Revert ALL inventory-related movements (both standard and quick inventory)
  DELETE FROM movimentacoes_estoque 
  WHERE reference_id = p_id::text 
    AND reference_type IN ('INVENTARIO_AJUSTE', 'QUICK_INVENTORY')
    AND company_id = v_tenant;
  GET DIAGNOSTICS v_deleted_moves = ROW_COUNT;

  UPDATE inventarios SET status = 'EM_REVISAO', finalizado_em = NULL, finalizado_por = NULL, aprovado_por = NULL, aprovacao_admin_em = NULL, updated_at = now() WHERE id = p_id AND company_id = v_tenant;
  v_after := jsonb_build_object('status', 'EM_REVISAO', 'movimentacoes_revertidas', v_deleted_moves);
  INSERT INTO audit_inventario_log (company_id, inventario_id, user_id, user_role, acao, antes, depois, ip_address)
  VALUES (v_tenant, p_id, v_user_id, COALESCE((SELECT string_agg(role::text, ',') FROM user_roles WHERE user_id = v_user_id AND company_id = public.assert_tenant()), 'unknown'), 'REOPEN', v_before, v_after || jsonb_build_object('justificativa', p_justificativa), '');
  RETURN jsonb_build_object('success', true, 'movimentacoes_revertidas', v_deleted_moves);
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_fin_categoria(p_category_id uuid, p_direction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_user_id uuid;
  v_cat RECORD;
  v_sibling RECORD;
BEGIN
  -- Resolve actor
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  -- Get category with lock
  SELECT id, parent_id, tipo, ordem, company_id
  INTO v_cat
  FROM fin_categorias
  WHERE id = p_category_id AND ativo = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Categoria não encontrada';
  END IF;

  v_company_id := v_cat.company_id;

  -- Verify tenant
  IF NOT EXISTS (
    SELECT 1 WHERE v_company_id = public.assert_tenant()
  ) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  -- Find adjacent sibling
  IF p_direction = 'up' THEN
    SELECT id, ordem
    INTO v_sibling
    FROM fin_categorias
    WHERE company_id = v_company_id
      AND ativo = true
      AND tipo = v_cat.tipo
      AND COALESCE(parent_id, '00000000-0000-0000-0000-000000000000') = COALESCE(v_cat.parent_id, '00000000-0000-0000-0000-000000000000')
      AND (ordem < v_cat.ordem OR (ordem = v_cat.ordem AND id < p_category_id))
      AND id != p_category_id
    ORDER BY ordem DESC, id DESC
    LIMIT 1;
  ELSIF p_direction = 'down' THEN
    SELECT id, ordem
    INTO v_sibling
    FROM fin_categorias
    WHERE company_id = v_company_id
      AND ativo = true
      AND tipo = v_cat.tipo
      AND COALESCE(parent_id, '00000000-0000-0000-0000-000000000000') = COALESCE(v_cat.parent_id, '00000000-0000-0000-0000-000000000000')
      AND (ordem > v_cat.ordem OR (ordem = v_cat.ordem AND id > p_category_id))
      AND id != p_category_id
    ORDER BY ordem ASC, id ASC
    LIMIT 1;
  ELSE
    RAISE EXCEPTION 'Direção inválida: use up ou down';
  END IF;

  IF v_sibling.id IS NULL THEN
    RETURN jsonb_build_object('status', 'noop', 'message', 'Já está na posição limite');
  END IF;

  -- Swap ordem values
  UPDATE fin_categorias SET ordem = v_sibling.ordem, updated_at = now() WHERE id = p_category_id;
  UPDATE fin_categorias SET ordem = v_cat.ordem, updated_at = now() WHERE id = v_sibling.id;

  -- If both had the same ordem, assign distinct values
  IF v_cat.ordem = v_sibling.ordem THEN
    UPDATE fin_categorias SET ordem = v_cat.ordem + 1, updated_at = now()
    WHERE id = (CASE WHEN p_direction = 'up' THEN v_sibling.id ELSE p_category_id END);
  END IF;

  RETURN jsonb_build_object('status', 'ok');
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_company_invitation(p_actor_user_id uuid, p_company_id uuid, p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_permissions text[];
BEGIN
 v_permissions:=public.get_company_permissions(p_actor_user_id,p_company_id);
 IF NOT v_permissions && ARRAY['configuracoes:usuarios:manage','users:manage','system:global:manage'] THEN
   SELECT public.get_company_permissions(p_actor_user_id,company_id) INTO v_permissions FROM public.profiles WHERE id=p_actor_user_id;
   IF NOT COALESCE('system:global:manage'=ANY(v_permissions),false) THEN
     RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='PERMISSION_DENIED';
   END IF;
 END IF;
 INSERT INTO multiunit_private.pending_identity_companies(email,company_id,expires_at)
 VALUES(lower(btrim(p_email)),p_company_id,now()+interval '5 minutes')
 ON CONFLICT(email) DO UPDATE SET company_id=EXCLUDED.company_id,expires_at=EXCLUDED.expires_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_confirmacoes_approve(p_confirmacao_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_conf confirmacoes_recebimento%ROWTYPE;
BEGIN
  -- Auth check
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  -- Permission guard
  IF NOT has_permission(v_user_id, 'compras:confirmacoes:approve') THEN
    RAISE EXCEPTION 'Sem permissão (compras:confirmacoes:approve)';
  END IF;

  -- Get confirmation
  SELECT * INTO v_conf FROM confirmacoes_recebimento WHERE id = p_confirmacao_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Confirmação não encontrada';
  END IF;

  -- Mark as seen/approved by this user (add to visto_por array if not already there)
  UPDATE confirmacoes_recebimento SET
    visto_por = array_append(
      COALESCE(visto_por, ARRAY[]::uuid[]),
      v_user_id
    )
  WHERE id = p_confirmacao_id
    AND NOT (COALESCE(visto_por, ARRAY[]::uuid[]) @> ARRAY[v_user_id]);

  RETURN jsonb_build_object(
    'success', true,
    'confirmacao_id', p_confirmacao_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_create_company(p_nome text, p_cnpj text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF NOT has_permission(auth.uid(), 'system:admin') THEN
    RAISE EXCEPTION 'Sem permissão (system:admin).';
  END IF;

  INSERT INTO public.companies (nome, cnpj)
  VALUES (p_nome, p_cnpj)
  RETURNING id INTO v_id;

  INSERT INTO public.audit_logs (module, action, entity, entity_id, actor_user_id, source, success, after)
  VALUES (
    'system', 'create_company', 'companies', v_id, auth.uid(), 'rpc', true,
    jsonb_build_object('nome', p_nome, 'cnpj', p_cnpj)
  );

  RETURN jsonb_build_object('id', v_id);
END;
$function$

