CREATE OR REPLACE FUNCTION public.rpc_upsert_fechamento_caixa_com_marcas(p_data date, p_faturamento_bruto numeric, p_taxas numeric DEFAULT 0, p_descontos numeric DEFAULT 0, p_observacao text DEFAULT NULL::text, p_marcas jsonb DEFAULT '[]'::jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_action text;
  v_company_id uuid;
  v_existing record;
  v_marcas jsonb := COALESCE(p_marcas, '[]'::jsonb);
  v_total_marcas numeric := 0;
  v_marca_count integer := 0;
BEGIN
  v_company_id := public.assert_tenant();

  IF p_faturamento_bruto IS NULL OR p_faturamento_bruto < 0 THEN
    RAISE EXCEPTION 'Faturamento bruto não pode ser negativo.';
  END IF;
  IF COALESCE(p_taxas, 0) < 0 THEN
    RAISE EXCEPTION 'Taxas não podem ser negativas.';
  END IF;
  IF COALESCE(p_descontos, 0) < 0 THEN
    RAISE EXCEPTION 'Descontos não podem ser negativos.';
  END IF;
  IF COALESCE(p_descontos, 0) > p_faturamento_bruto THEN
    RAISE EXCEPTION 'Descontos não podem ser maiores que o faturamento bruto.';
  END IF;
  IF jsonb_typeof(v_marcas) <> 'array' THEN
    RAISE EXCEPTION 'MARCAS_INVALIDAS';
  END IF;

  IF jsonb_array_length(v_marcas) > 0 THEN
    BEGIN
      SELECT
        count(*),
        COALESCE(sum((item->>'valor')::numeric), 0)
      INTO v_marca_count, v_total_marcas
      FROM jsonb_array_elements(v_marcas) AS t(item)
      WHERE item ? 'marca_id'
        AND item ? 'valor'
        AND (item->>'valor')::numeric >= 0;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'MARCAS_INVALIDAS';
    END;

    IF v_marca_count <> jsonb_array_length(v_marcas) THEN
      RAISE EXCEPTION 'MARCAS_INVALIDAS';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_marcas) AS t(item)
      GROUP BY item->>'marca_id'
      HAVING count(*) > 1
    ) THEN
      RAISE EXCEPTION 'MARCA_DUPLICADA';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_marcas) AS t(item)
      LEFT JOIN public.financeiro_fechamento_marcas m
        ON m.id = (item->>'marca_id')::uuid
       AND m.company_id = v_company_id
      WHERE m.id IS NULL
    ) THEN
      RAISE EXCEPTION 'MARCA_INVALIDA';
    END IF;

    IF round(v_total_marcas, 2) <> round(p_faturamento_bruto, 2) THEN
      RAISE EXCEPTION 'TOTAL_MARCAS_DIVERGENTE';
    END IF;
  END IF;

  SELECT id, updated_at
  INTO v_existing
  FROM public.financeiro_fechamento_caixa
  WHERE data = p_data
    AND company_id = v_company_id
  FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF NOT public.has_any_permission(auth.uid(), ARRAY[
      'financeiro:fechamento:edit',
      'finance:manage',
      'system:global:manage'
    ]) THEN
      RAISE EXCEPTION 'PERMISSION_DENIED';
    END IF;
    IF p_expected_updated_at IS NOT NULL
       AND v_existing.updated_at <> p_expected_updated_at THEN
      RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
    END IF;

    UPDATE public.financeiro_fechamento_caixa
    SET faturamento_bruto = round(p_faturamento_bruto, 2),
        taxas = round(COALESCE(p_taxas, 0), 2),
        descontos = round(COALESCE(p_descontos, 0), 2),
        observacao = p_observacao,
        updated_at = now()
    WHERE id = v_existing.id;

    v_id := v_existing.id;
    v_action := 'update';
  ELSE
    IF NOT public.has_any_permission(auth.uid(), ARRAY[
      'financeiro:fechamento:create',
      'finance:manage',
      'system:global:manage'
    ]) THEN
      RAISE EXCEPTION 'PERMISSION_DENIED';
    END IF;

    INSERT INTO public.financeiro_fechamento_caixa (
      data, faturamento_bruto, taxas, descontos, observacao, created_by, company_id
    ) VALUES (
      p_data,
      round(p_faturamento_bruto, 2),
      round(COALESCE(p_taxas, 0), 2),
      round(COALESCE(p_descontos, 0), 2),
      p_observacao,
      auth.uid(),
      v_company_id
    )
    RETURNING id INTO v_id;

    v_action := 'create';
  END IF;

  DELETE FROM public.financeiro_fechamento_marca_valores
  WHERE company_id = v_company_id
    AND fechamento_id = v_id;

  INSERT INTO public.financeiro_fechamento_marca_valores (
    company_id, fechamento_id, marca_id, valor_bruto, created_by
  )
  SELECT
    v_company_id,
    v_id,
    (item->>'marca_id')::uuid,
    round((item->>'valor')::numeric, 2),
    auth.uid()
  FROM jsonb_array_elements(v_marcas) AS t(item);

  RETURN jsonb_build_object(
    'id', v_id,
    'action', v_action,
    'total_marcas', round(v_total_marcas, 2),
    'quantidade_marcas', jsonb_array_length(v_marcas)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_upsert_fechamento_caixa(p_data date, p_faturamento_bruto numeric, p_taxas numeric DEFAULT 0, p_descontos numeric DEFAULT 0, p_observacao text DEFAULT NULL::text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_action text;
  v_company_id uuid;
  v_existing record;
BEGIN
  v_company_id := assert_tenant();

  -- Validate inputs
  IF p_faturamento_bruto < 0 THEN
    RAISE EXCEPTION 'Faturamento bruto não pode ser negativo.';
  END IF;
  IF COALESCE(p_taxas, 0) < 0 THEN
    RAISE EXCEPTION 'Taxas não podem ser negativas.';
  END IF;
  IF COALESCE(p_descontos, 0) < 0 THEN
    RAISE EXCEPTION 'Descontos não podem ser negativos.';
  END IF;
  IF COALESCE(p_descontos, 0) > p_faturamento_bruto THEN
    RAISE EXCEPTION 'Descontos não podem ser maiores que o faturamento bruto.';
  END IF;

  -- Check if record exists
  SELECT id, updated_at INTO v_existing
  FROM financeiro_fechamento_caixa
  WHERE data = p_data AND company_id = v_company_id
  FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    -- UPDATE path
    IF NOT has_any_permission(auth.uid(), ARRAY['financeiro:fechamento:edit', 'system:global:manage']) THEN
      RAISE EXCEPTION 'PERMISSION_DENIED';
    END IF;

    -- Optimistic locking
    IF p_expected_updated_at IS NOT NULL AND v_existing.updated_at != p_expected_updated_at THEN
      RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
    END IF;

    v_action := 'update';
    UPDATE financeiro_fechamento_caixa SET
      faturamento_bruto = p_faturamento_bruto,
      taxas = COALESCE(p_taxas, 0),
      descontos = COALESCE(p_descontos, 0),
      observacao = p_observacao,
      updated_at = now()
    WHERE id = v_existing.id;
    v_id := v_existing.id;
  ELSE
    -- CREATE path
    IF NOT has_any_permission(auth.uid(), ARRAY['financeiro:fechamento:create', 'system:global:manage']) THEN
      RAISE EXCEPTION 'PERMISSION_DENIED';
    END IF;

    v_action := 'create';
    INSERT INTO financeiro_fechamento_caixa (data, faturamento_bruto, taxas, descontos, observacao, created_by, company_id)
    VALUES (p_data, p_faturamento_bruto, COALESCE(p_taxas, 0), COALESCE(p_descontos, 0), p_observacao, auth.uid(), v_company_id)
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('id', v_id::text, 'action', v_action);
END;
$function$

