CREATE OR REPLACE FUNCTION public.trg_po_block_post_approval_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status NOT IN ('OPEN','DRAFT','SUBMITTED') THEN
    IF NEW.supplier_name IS DISTINCT FROM OLD.supplier_name THEN
