CREATE OR REPLACE FUNCTION public.trg_validate_rateio_sum()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lancamento_id uuid;
  v_lancamento_valor numeric;
  v_soma_rateios numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_lancamento_id := OLD.lancamento_id;
  ELSE
    v_lancamento_id := NEW.lancamento_id;
  END IF;

  -- Try fin_lancamentos first
  SELECT ABS(valor) INTO v_lancamento_valor
  FROM fin_lancamentos
  WHERE id = v_lancamento_id
  FOR UPDATE;

  -- If not found, try fin_contas_pagar
  IF v_lancamento_valor IS NULL THEN
    SELECT ABS(valor) INTO v_lancamento_valor
    FROM fin_contas_pagar
    WHERE id = v_lancamento_id
    FOR UPDATE;
  END IF;

  -- If not found, try fin_contas_receber
  IF v_lancamento_valor IS NULL THEN
    SELECT ABS(valor) INTO v_lancamento_valor
    FROM fin_contas_receber
    WHERE id = v_lancamento_id
    FOR UPDATE;
  END IF;

  IF v_lancamento_valor IS NULL THEN
    RAISE EXCEPTION 'Lançamento não encontrado: %', v_lancamento_id
      USING ERRCODE = 'P0002';
  END IF;

  IF TG_OP = 'DELETE' THEN
    SELECT COALESCE(SUM(ABS(valor)), 0) INTO v_soma_rateios
    FROM fin_lancamento_rateios
    WHERE lancamento_id = v_lancamento_id AND id <> OLD.id;
  ELSE
    SELECT COALESCE(SUM(ABS(valor)), 0) INTO v_soma_rateios
    FROM fin_lancamento_rateios
    WHERE lancamento_id = v_lancamento_id AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
    v_soma_rateios := v_soma_rateios + ABS(NEW.valor);
  END IF;

  IF v_soma_rateios > v_lancamento_valor + 0.01 THEN
    RAISE EXCEPTION 'Soma dos rateios (%) excede o valor do lançamento (%). Diferença: %',
      v_soma_rateios, v_lancamento_valor, v_soma_rateios - v_lancamento_valor
      USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.unreconcile_lancamento(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company_id uuid;
  v_uid uuid;
  v_lanc record;
  v_vinculos_removidos int;
BEGIN
  v_company_id := public.assert_tenant();
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuário não autenticado';
  END IF;

  IF NOT public.has_any_permission(v_uid, ARRAY['financeiro:conciliacao:reconcile', 'finance:manage', 'system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:conciliacao:reconcile necessário';
  END IF;

  SELECT * INTO v_lanc
  FROM public.fin_lancamentos
  WHERE id = p_id AND company_id = v_company_id
  FOR UPDATE;

  IF v_lanc IS NULL THEN
    RAISE EXCEPTION 'NOT_FOUND: Lançamento não encontrado';
  END IF;

  IF v_lanc.conciliado IS NOT TRUE THEN
    RETURN jsonb_build_object('status', 'noop', 'deleted', false);
  END IF;

  UPDATE public.fin_lancamentos
  SET conciliado = false, conciliado_em = NULL, conciliado_por = NULL
  WHERE id = p_id AND company_id = v_company_id;

  DELETE FROM public.fin_conciliacao_vinculos
  WHERE lancamento_id = p_id AND company_id = v_company_id;
  GET DIAGNOSTICS v_vinculos_removidos = ROW_COUNT;

  INSERT INTO public.fin_audit_logs (entidade, entidade_id, acao, user_id, company_id, antes)
  VALUES ('lancamentos', p_id, 'unreconcile', v_uid, v_company_id,
    jsonb_build_object('conciliado_em', v_lanc.conciliado_em, 'origem', v_lanc.origem,
      'vinculos_removidos', v_vinculos_removidos));

  RETURN jsonb_build_object('status', 'ok', 'deleted', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_company(p_company_id uuid, p_nome text DEFAULT NULL::text, p_cnpj text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_uid uuid;
  v_old record;
BEGIN
  v_caller_uid := auth.uid();
  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION '403: Não autenticado';
  END IF;

  IF NOT has_permission(v_caller_uid, 'system:global:manage') THEN
    RAISE EXCEPTION '403: Sem permissão';
  END IF;

  IF p_company_id = '00000000-0000-0000-0000-000000000001'::uuid THEN
    RAISE EXCEPTION '400: Não é possível editar a empresa placeholder';
  END IF;

  SELECT * INTO v_old FROM companies WHERE id = p_company_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION '404: Empresa não encontrada';
  END IF;

  IF p_cnpj IS NOT NULL AND trim(p_cnpj) <> '' AND trim(p_cnpj) <> COALESCE(v_old.cnpj, '') THEN
    IF EXISTS (SELECT 1 FROM companies WHERE cnpj = trim(p_cnpj) AND id <> p_company_id) THEN
      RAISE EXCEPTION '409: CNPJ já cadastrado em outra empresa';
    END IF;
  END IF;

  UPDATE companies SET
    nome       = COALESCE(NULLIF(trim(p_nome), ''), v_old.nome),
    cnpj       = CASE WHEN p_cnpj IS NOT NULL THEN NULLIF(trim(p_cnpj), '') ELSE v_old.cnpj END,
    ativo      = COALESCE(p_ativo, v_old.ativo),
    updated_at = now()
  WHERE id = p_company_id;

  INSERT INTO audit_logs (actor_user_id, company_id, action, module, entity, entity_id, metadata)
  VALUES (v_caller_uid, p_company_id, 'COMPANY_UPDATED', 'admin', 'companies', p_company_id, jsonb_build_object(
    'old_nome', v_old.nome, 'new_nome', COALESCE(NULLIF(trim(p_nome), ''), v_old.nome),
    'old_ativo', v_old.ativo, 'new_ativo', COALESCE(p_ativo, v_old.ativo)
  ));

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_cotacao_atomic(p_id uuid, p_titulo text, p_observacao text DEFAULT NULL::text, p_data_validade date DEFAULT NULL::date, p_itens jsonb DEFAULT '[]'::jsonb, p_fornecedores jsonb DEFAULT '[]'::jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_user    uuid;
  v_cot     record;
  v_elem    jsonb;
BEGIN
  v_company := public.assert_tenant();
  v_user := auth.uid();

  IF NOT public.has_any_permission(v_user, ARRAY['compras:cotacao:edit','system:global:manage']) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: compras:cotacao:edit';
  END IF;

  SELECT id, status, updated_at INTO v_cot
  FROM public.cotacoes
  WHERE id = p_id AND company_id = v_company AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;

  IF v_cot.status NOT IN ('RASCUNHO','EM_COTACAO') THEN
    RAISE EXCEPTION 'STATUS_INVALIDO: % (edição só em RASCUNHO/EM_COTACAO)', v_cot.status;
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_cot.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'OPTIMISTIC_LOCK_CONFLICT';
  END IF;
  IF p_titulo IS NULL OR length(btrim(p_titulo)) = 0 THEN
    RAISE EXCEPTION 'VALIDATION: título obrigatório';
  END IF;

  UPDATE public.cotacoes
     SET titulo = btrim(p_titulo),
         observacao = NULLIF(btrim(coalesce(p_observacao,'')),''),
         data_validade = p_data_validade
   WHERE id = p_id;

  DELETE FROM public.cotacao_itens WHERE cotacao_id = p_id;
  DELETE FROM public.cotacao_fornecedores WHERE cotacao_id = p_id;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_itens
      (cotacao_id, company_id, produto_id, produto_nome_snapshot, unidade_snapshot,
       purchase_unit_snapshot, conversion_factor_snapshot, quantidade, observacao)
    VALUES (
      p_id, v_company,
      NULLIF(v_elem->>'produto_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'produto_nome_snapshot'),''), 'Item'),
      NULLIF(v_elem->>'unidade_snapshot',''),
      NULLIF(v_elem->>'purchase_unit_snapshot',''),
      coalesce((v_elem->>'conversion_factor_snapshot')::numeric, 1),
      coalesce((v_elem->>'quantidade')::numeric, 0),
      NULLIF(v_elem->>'observacao','')
    );
  END LOOP;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(coalesce(p_fornecedores, '[]'::jsonb)) LOOP
    INSERT INTO public.cotacao_fornecedores
      (cotacao_id, company_id, supplier_id, supplier_nome_snapshot, whatsapp_snapshot, pedido_minimo_snapshot, status)
    VALUES (
      p_id, v_company,
      NULLIF(v_elem->>'supplier_id','')::uuid,
      coalesce(NULLIF(btrim(v_elem->>'supplier_nome_snapshot'),''), 'Fornecedor'),
      NULLIF(v_elem->>'whatsapp_snapshot',''),
      coalesce((v_elem->>'pedido_minimo_snapshot')::numeric, 0),
      'AGUARDANDO'
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', p_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_transfer(p_lancamento_id uuid, p_valor numeric, p_data_competencia date, p_descricao text, p_conta_origem_id uuid, p_conta_destino_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_company uuid;
  v_uid uuid;
  v_target public.fin_lancamentos%ROWTYPE;
  v_parent_id uuid;
  v_child_id uuid;
  v_nome_origem text;
  v_nome_destino text;
BEGIN
  v_company := public.assert_tenant();
  v_uid := auth.uid();

  IF NOT public.has_any_permission(v_uid, ARRAY[
    'financeiro:lancamentos:edit', 'finance:manage', 'system:global:manage'
  ]) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: financeiro:lancamentos:edit necessário';
  END IF;

  IF p_valor IS NULL OR p_valor <= 0 THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: valor deve ser maior que zero';
  END IF;
  IF p_conta_origem_id = p_conta_destino_id THEN
    RAISE EXCEPTION 'VALIDATION_ERROR: contas de origem e destino devem ser diferentes';
  END IF;

  SELECT l.* INTO v_target
  FROM public.fin_lancamentos l
  WHERE l.id = p_lancamento_id
    AND l.company_id = v_company
    AND l.tipo = 'TRANSFERENCIA';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_FOUND: transferência';
  END IF;

  SELECT c.nome INTO v_nome_origem
  FROM public.fin_contas c
  WHERE c.id = p_conta_origem_id AND c.company_id = v_company;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: conta de origem'; END IF;

  SELECT c.nome INTO v_nome_destino
  FROM public.fin_contas c
  WHERE c.id = p_conta_destino_id AND c.company_id = v_company;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: conta de destino'; END IF;

  v_parent_id := COALESCE(v_target.lancamento_pai_id, v_target.id);
  SELECT l.id INTO v_child_id
  FROM public.fin_lancamentos l
  WHERE l.lancamento_pai_id = v_parent_id
    AND l.company_id = v_company
    AND l.tipo = 'TRANSFERENCIA'
  LIMIT 1;

  IF v_child_id IS NOT NULL THEN
    UPDATE public.fin_lancamentos SET
      valor = p_valor,
      data_competencia = p_data_competencia,
      data_pagamento = p_data_competencia,
      descricao = 'Transferência para ' || v_nome_destino,
      observacoes = p_descricao,
      conta_id = p_conta_origem_id,
      conta_destino_id = p_conta_destino_id,
      updated_at = now()
    WHERE id = v_parent_id AND company_id = v_company;

    UPDATE public.fin_lancamentos SET
      valor = p_valor,
      data_competencia = p_data_competencia,
      data_pagamento = p_data_competencia,
      descricao = 'Transferência de ' || v_nome_origem,
      observacoes = p_descricao,
      conta_id = p_conta_destino_id,
      conta_destino_id = p_conta_origem_id,
      updated_at = now()
    WHERE id = v_child_id AND company_id = v_company;
  ELSE
    UPDATE public.fin_lancamentos SET
      valor = p_valor,
      data_competencia = p_data_competencia,
      data_pagamento = p_data_competencia,
      descricao = COALESCE(NULLIF(btrim(p_descricao), ''), format('Transferência: %s → %s', v_nome_origem, v_nome_destino)),
      conta_id = p_conta_origem_id,
      conta_destino_id = p_conta_destino_id,
      updated_at = now()
    WHERE id = v_target.id AND company_id = v_company;
  END IF;

  INSERT INTO public.fin_audit_logs (
    entidade, entidade_id, acao, user_id, company_id, antes, depois
  )
  VALUES (
    'transferencia', v_target.id, 'editar', v_uid, v_company,
    jsonb_build_object('valor', v_target.valor, 'data', v_target.data_competencia, 'origem', v_target.conta_id, 'destino', v_target.conta_destino_id),
    jsonb_build_object('valor', p_valor, 'data', p_data_competencia, 'origem', p_conta_origem_id, 'destino', p_conta_destino_id)
  );
END;
$function$

