CREATE OR REPLACE FUNCTION public.validate_estorno_movement()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_original RECORD;
BEGIN
  -- Only validate ESTORNO types
  IF NEW.tipo NOT IN ('ENTRADA_ESTORNO', 'SAIDA_ESTORNO') THEN
    RETURN NEW;
  END IF;

  -- 1. Must have estorno_de_id
  IF NEW.estorno_de_id IS NULL THEN
    RAISE EXCEPTION '400: Movimentação de estorno deve referenciar a movimentação original (estorno_de_id obrigatório).';
  END IF;

  -- 2. Original movement must exist and belong to same company
  SELECT id, company_id, status INTO v_original
  FROM public.movimentacoes_estoque
  WHERE id = NEW.estorno_de_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION '404: Movimentação original não encontrada.';
  END IF;

  IF v_original.company_id != NEW.company_id THEN
    RAISE EXCEPTION '403: Movimentação original pertence a outro tenant.';
  END IF;

  -- 3. Original must not already be CANCELADO
  IF v_original.status = 'CANCELADO' THEN
    RAISE EXCEPTION '409: Movimentação original já foi cancelada. Estorno duplicado bloqueado.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_fechamento_marca_total()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fechamento_id uuid;
  v_company_id uuid;
  v_faturamento_bruto numeric;
  v_total_marcas numeric;
  v_quantidade integer;
BEGIN
  IF TG_TABLE_NAME = 'financeiro_fechamento_caixa' THEN
    IF TG_OP = 'DELETE' THEN
      v_fechamento_id := OLD.id;
      v_company_id := OLD.company_id;
    ELSE
      v_fechamento_id := NEW.id;
      v_company_id := NEW.company_id;
    END IF;
  ELSE
    IF TG_OP = 'UPDATE'
       AND (OLD.company_id, OLD.fechamento_id, OLD.marca_id)
           IS DISTINCT FROM (NEW.company_id, NEW.fechamento_id, NEW.marca_id) THEN
      RAISE EXCEPTION 'IDENTIDADE_MARCA_VALOR_IMUTAVEL';
    END IF;

    IF TG_OP = 'DELETE' THEN
      v_fechamento_id := OLD.fechamento_id;
      v_company_id := OLD.company_id;
    ELSE
      v_fechamento_id := NEW.fechamento_id;
      v_company_id := NEW.company_id;
    END IF;
  END IF;

  SELECT fc.faturamento_bruto
  INTO v_faturamento_bruto
  FROM public.financeiro_fechamento_caixa fc
  WHERE fc.id = v_fechamento_id
    AND fc.company_id = v_company_id;

  IF NOT FOUND THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  SELECT count(*), COALESCE(sum(v.valor_bruto), 0)
  INTO v_quantidade, v_total_marcas
  FROM public.financeiro_fechamento_marca_valores v
  WHERE v.fechamento_id = v_fechamento_id
    AND v.company_id = v_company_id;

  IF v_quantidade > 0
     AND round(v_total_marcas, 2) <> round(v_faturamento_bruto, 2) THEN
    RAISE EXCEPTION 'TOTAL_MARCAS_DIVERGENTE';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_marca_categoria_vinculo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_categoria record;
BEGIN
  IF NEW.categoria_id IS NULL THEN
    RAISE EXCEPTION 'CATEGORIA_MARCA_OBRIGATORIA';
  END IF;

  SELECT c.tipo, c.ativo, c.excluir_dos_totais
  INTO v_categoria
  FROM public.fin_categorias c
  WHERE c.id = NEW.categoria_id
    AND c.company_id = NEW.company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CATEGORIA_MARCA_INVALIDA';
  END IF;

  IF v_categoria.tipo <> 'receita'
     OR v_categoria.ativo IS NOT TRUE
     OR v_categoria.excluir_dos_totais IS TRUE THEN
    RAISE EXCEPTION 'CATEGORIA_MARCA_INVALIDA';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.fin_categorias f
    WHERE f.parent_id = NEW.categoria_id
      AND f.company_id = NEW.company_id
      AND f.ativo = true
  ) THEN
    RAISE EXCEPTION 'CATEGORIA_MARCA_NAO_FOLHA';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_ponto_registro()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_tipo TEXT;
  v_colab_status TEXT;
BEGIN
  -- Check collaborator is active
  SELECT status INTO v_colab_status 
  FROM rh_colaboradores WHERE id = NEW.colaborador_id;

  IF v_colab_status IS NULL THEN
    RAISE EXCEPTION 'Colaborador não encontrado';
  END IF;

  IF v_colab_status != 'ativo' THEN
    RAISE EXCEPTION 'Colaborador inativo não pode registrar ponto';
  END IF;

  -- Check for duplicate ENTRADA without SAIDA
  IF NEW.tipo = 'ENTRADA' THEN
    SELECT tipo INTO v_last_tipo
    FROM rh_ponto_registros
    WHERE colaborador_id = NEW.colaborador_id
      AND data = NEW.data
    ORDER BY hora DESC
    LIMIT 1;

    IF v_last_tipo = 'ENTRADA' OR v_last_tipo = 'FIM_INTERVALO' THEN
      RAISE EXCEPTION 'Já existe uma entrada sem saída para esta data. Registre a saída primeiro.';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_ponto_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_colab_user_id UUID;
  v_caller_id UUID;
BEGIN
  v_caller_id := auth.uid();

  -- Get the user_id of the collaborator who owns this ponto
  SELECT user_id INTO v_colab_user_id
  FROM rh_colaboradores
  WHERE id = NEW.colaborador_id;

  -- If caller is the owner and trying to set aprovado=true, block it
  IF v_caller_id = v_colab_user_id AND NEW.aprovado = true AND (OLD.aprovado IS NULL OR OLD.aprovado = false) THEN
    RAISE EXCEPTION 'Não é permitido aprovar o próprio ponto';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_purchase_order_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.qty_requested <= 0 THEN
    RAISE EXCEPTION 'qty_requested deve ser > 0 (recebido: %)', NEW.qty_requested;
  END IF;
  IF NEW.estimated_unit_value < 0 THEN
    RAISE EXCEPTION 'estimated_unit_value não pode ser negativo';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_requisicao_item_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  allowed_statuses text[] := ARRAY['SOLICITADO', 'ATENDIDO', 'RECUSADO'];
BEGIN
  IF NOT (NEW.status = ANY(allowed_statuses)) THEN
    RAISE EXCEPTION 'Status de item inválido: %. Permitidos: %', NEW.status, array_to_string(allowed_statuses, ', ');
  END IF;

  -- If marking as RECUSADO, require motivo_recusa
  IF NEW.status = 'RECUSADO' AND (NEW.motivo_recusa IS NULL OR trim(NEW.motivo_recusa) = '') THEN
    RAISE EXCEPTION 'Motivo de recusa é obrigatório para itens recusados';
  END IF;

  -- If marking as RECUSADO, require recusado_por and recusado_em
  IF NEW.status = 'RECUSADO' AND (NEW.recusado_por IS NULL OR NEW.recusado_em IS NULL) THEN
    RAISE EXCEPTION 'recusado_por e recusado_em são obrigatórios para itens recusados';
  END IF;

  -- If marking as ATENDIDO, require atendido_por and atendido_em
  IF NEW.status = 'ATENDIDO' AND (NEW.atendido_por IS NULL OR NEW.atendido_em IS NULL) THEN
    RAISE EXCEPTION 'atendido_por e atendido_em são obrigatórios para itens atendidos';
  END IF;

  -- Prevent changing from terminal status
  IF TG_OP = 'UPDATE' AND OLD.status IN ('ATENDIDO', 'RECUSADO') AND OLD.status IS DISTINCT FROM NEW.status THEN
    RAISE EXCEPTION 'Não é possível alterar status de item já % ', OLD.status;
  END IF;

  RETURN NEW;
END;
$function$

